218:      * Returns the owner of some modelelement object. In most cases this will be
219:      * the owning namespace but in some cases it will be null (the root model)
220:      * or for instance the owning class with an attribute.
221:      * @param handle the modelelement
222:      * @return Object the owner
223:      */
224:     public Object getOwner(Object handle) {
225:         if (handle instanceof MBase) {
226:             return ((MBase) handle).getModelElementContainer();
227:         }
228:         return null;
229:     }
230:     
231:     /**
232:      * Utility method to quickly delete a collection of modelelements. This
233:      * method should only be called from within the model component. The only
234:      * reason it is public is that the other helpers/factories are in other
235:      * packages and therefore cannot see this method if it is not public.
236:      * @param col a collection of modelelements
237:      */
238:     public void deleteCollection(Collection col) {
239:         Iterator it = col.iterator();
240:         while (it.hasNext()) {
241:             UmlFactory.getFactory().delete(it.next());
242:         }        
243:     }
244:     
245:     /**
246:      * Returns the source of some relationship. 
247:      * This is the element in binary relations from which a relation 'departs'.
248:      * @param relationShip the relationship to be tested
249:      * @return the source of the relationship
250:      */
251:     public Object getSource(Object relationShip) {
252:         if (relationShip == null) {
253:             throw new IllegalArgumentException("Argument relationship is null");
254:         }
255:         if (!(ModelFacade.isAModelElement(relationShip) 
256:                 || relationShip instanceof CommentEdge)) {
257:            throw new IllegalArgumentException("Argument relationship of class " 
258:                    + relationShip.getClass().toString() 
259:                    + " is not a valid relationship"); 
260:         }     
261:         if (relationShip instanceof CommentEdge) {
262:             return ((CommentEdge) relationShip).getSource();
263:         }
264:         if (ModelFacade.isARelationship(relationShip)) { 
265:             // handles all children of relationship including extend and 
266:             // include which are not members of core 
267:             return CoreHelper.getHelper().getSource(relationShip);
268:         }
269:         if (ModelFacade.isATransition(relationShip)) {
270:             return StateMachinesHelper.getHelper().getSource(relationShip);
271:         }
272:         return null;
273:     }
274:     
275:     /**
276:      * Returns the destination of some relationship. 
277:      * This is the element in binary relations at which a relation 'arrives'.
278:      * @param relationShip  the relationship to be tested
279:      * @return the destination of the relationship
280:      */
281:     public Object getDestination(Object relationShip) {
282:         if (relationShip == null) {
283:             throw new IllegalArgumentException("Argument relationship is null");
284:         }
285:         if (!(ModelFacade.isAModelElement(relationShip) 
286:                 || relationShip instanceof CommentEdge)) {
287:            throw new IllegalArgumentException("Argument relationship of class " 
288:                    + relationShip.getClass().toString() 
289:                    + " is not a valid relationship"); 
290:         }     
291:         if (relationShip instanceof CommentEdge) {
292:             return ((CommentEdge) relationShip).getDestination();
293:         }
294:         if (ModelFacade.isARelationship(relationShip)) { 
295:             // handles all children of relationship including extend and 
296:             // include which are not members of core 
297:             return CoreHelper.getHelper().getDestination(relationShip);
298:         }
299:         if (ModelFacade.isATransition(relationShip)) {
300:             return StateMachinesHelper.getHelper().getDestination(relationShip);
301:         }
302:         return null;
303:     }
