385:     private void softAddStereotype(String name, Object elem)
386:         throws ParseException {
387:         MNamespace ns =  (MNamespace)
388:             ProjectManager.getManager().getCurrentProject().getModel();
389:         
390:         Iterator it =
391:             ExtensionMechanismsHelper.getHelper()
392:                 .getStereotypes(ns).iterator();
393:         while (it.hasNext()) {
394:             MStereotype s = (MStereotype) it.next();
395:             if (name.equals(s.getName())) {
396:                 return;
397:             }
398:         }
399:         ExtensionMechanismsFactory.getFactory().buildStereotype(
400:             elem, 
401:             name,
402:             ns);
403:     }
