65:      * OCL editor can be used.
66:      */
67: 
68:     public PropPanelExtend() {
69:         super("Extend", ConfigLoader.getTabPropsOrientation());
70: 
71:         addField(Translator.localize("label.name"),
72: 		 getNameTextField());
