82:         // base use case.
83: 
84:         addField(Translator.localize("label.usecase-base"),
85: 		 new UMLComboBox2(new UMLExtendBaseComboBoxModel(),
86: 				  ActionSetExtendBase.getInstance()));
87: 
88:         addField(Translator.localize("label.extension"),
89: 		 new UMLComboBox2(new UMLExtendExtensionComboBoxModel(),
90: 				  ActionSetExtendExtension.getInstance()));
91: 
92:         JList extensionPointList =
93: 	    new UMLMutableLinkedList(new UMLExtendExtensionPointListModel(),
94: 		ActionAddExtendExtensionPoint.getInstance(),
95: 		ActionNewExtendExtensionPoint.SINGLETON);
96:         addField(Translator.localize("label.extension-points"),
97: 		new JScrollPane(extensionPointList));
98: 
99:         addSeperator();
100: 
101: //        UMLExpressionModel conditionModel =
102: //            new UMLExpressionModel(this, 
103: //                                   (Class) ModelFacade.EXTEND,
104: //                                   "condition",
105: //				   (Class) ModelFacade.BOOLEAN_EXPRESSION,
106: //                                   "getCondition", 
107: //                                   "setCondition");
108:         UMLExpressionModel2 conditionModel =
109:             new UMLConditionExpressionModel(this, "condition");
110: 
111:         JTextArea conditionArea = new UMLExpressionBodyField(conditionModel,
112: 							     true);
