123:         new PropPanelButton(this,
124:                 lookupIcon("ExtensionPoint"),
125:                 localize("New Extension Point"),
126:                 "newExtensionPoint",
127:                 null);
128:         addButton(new PropPanelButton2(this, new ActionRemoveFromModel()));
129:     }
130: 
131: 
132:     /**
133:      * Get the condition associated with the extend relationship.<p>
134:      *
135:      * The condition is actually of type {@link
136:      * ru.novosoft.uml.foundation.data_types.MBooleanExpression},
137:      * which defines both a language and a body. We are only
138:      * interested in the body, which is just a string.<p>
139:      *
140:      * @return The body of the {@link
141:      * ru.novosoft.uml.foundation.data_types.MBooleanExpression} which
142:      * is the condition associated with this extend relationship, or
143:      * <code>null</code> if there is none.
144:      */
145:     public String getCondition() {
146:         String condBody = null;
147:         Object target   = getTarget();
148: 
149:         if (ModelFacade.isAExtend(target)) {
150:             Object condition = ModelFacade.getCondition(target);
151: 
152:             if (condition != null) {
153:                 condBody = (String) ModelFacade.getBody(condition);
154:             }
155:         }
156: 
157:         return condBody;
158:     }
