161:     /**
162:      * Set the condition associated with the extend relationship.<p>
163:      *
164:      * The condition is actually of type {@link
165:      * ru.novosoft.uml.foundation.data_types.MBooleanExpression},
166:      * which defines both a language and a body. We are only
167:      * interested in setting the body, which is just a string.<p>
168:      *
169:      * @param condBody  The body of the condition to associate with this
170:      *                  extend relationship.
171:      */
172:     public void setCondition(String condBody) {
173: 
174:         // Give up if we are not an extend relationship
175: 
176:         Object target = getTarget();
177: 
178:         if (!(org.argouml.model.ModelFacade.isAExtend(target))) {
179:             return;
180:         }
181: 
182:         // Set the condition body.
183: 
184:         ModelFacade.setCondition(target,
185: 				 UmlFactory.getFactory().getDataTypes()
186: 				     .createBooleanExpression(null, condBody));
187:     }
188: 
189: 
