191:      * Invoked by the "New Extension Point" toolbar button to create a new
192:      *   extension point for this extend relationship in the same namespace as
193:      *   the current extend relationship.<p>
194:      *
195:      * This code uses getFactory and adds the extension point to
196:      *   the current extend relationship.<p>
197:      */
198:     public void newExtensionPoint() {
199:         Object target = getTarget();
200: 
201:         if (org.argouml.model.ModelFacade.isAExtend(target)) {
202:             Object    extend    = /*(MExtend)*/ target;
203:             Object ns = ModelFacade.getNamespace(extend);
204: 
205:             if (ns != null) {
206:                 if (ModelFacade.getBase(extend) != null) {
207: 
208: 		    Object extensionPoint =
209: 			UseCasesFactory.getFactory()
210: 			    .buildExtensionPoint(ModelFacade.getBase(extend));
211: 
212: 		    ModelFacade.addExtensionPoint(extend, extensionPoint);
213:                 }
214: 
215:             }
216:         }
217:     }
218: 
219: } /* end class PropPanelExtend */
