346:     public void paintClarifiers(Graphics g) {
347:         int iconPos = 25, gap = 1, xOff = -4, yOff = -4;
348:         Point p = new Point();
349:         ToDoList list = Designer.theDesigner().getToDoList();
350:         Vector items = list.elementsForOffender(getOwner());
351:         int size = items.size();
352:         for (int i = 0; i < size; i++) {
353:             ToDoItem item = (ToDoItem) items.elementAt(i);
354:             Icon icon = item.getClarifier();
355:             if (icon instanceof Clarifier) {
356:                 ((Clarifier) icon).setFig(this);
357:                 ((Clarifier) icon).setToDoItem(item);
358:             }
359:             if (icon != null) {
360:                 stuffPointAlongPerimeter(iconPos, p);
361:                 icon.paintIcon(null, g, p.x + xOff, p.y + yOff);
362:                 iconPos += icon.getIconWidth() + gap;
363:             }
364:         }
365:         items = list.elementsForOffender(this);
366:         size = items.size();
367:         for (int i = 0; i < size; i++) {
368:             ToDoItem item = (ToDoItem) items.elementAt(i);
369:             Icon icon = item.getClarifier();
370:             if (icon instanceof Clarifier) {
371:                 ((Clarifier) icon).setFig(this);
372:                 ((Clarifier) icon).setToDoItem(item);
373:             }
374:             if (icon != null) {
375:                 stuffPointAlongPerimeter(iconPos, p);
376:                 icon.paintIcon(null, g, p.x + xOff, p.y + yOff);
377:                 iconPos += icon.getIconWidth() + gap;
378:             }
379:         }
380:     }
