1187:             Object[] l = (Object[]) iter.next();
1188:             Object property = l[1];
1189:             if (property == null) {
1190:                 Model.getPump().removeModelEventListener(this, l[0]);
1191:             } else if (property instanceof String[]) {
1192:                 Model.getPump().removeModelEventListener(this, l[0],
1193:                         (String[]) property);
1194:             } else if (property instanceof String) {
1195:                 Model.getPump().removeModelEventListener(this, l[0],
1196:                         (String) property);
1197:             } else {
