514:             // Add/remove name change listeners for applied stereotypes
515:             if (src == getOwner()
516:                     && "stereotype".equals(pName)) {
517:                 if (pve instanceof RemoveAssociationEvent) {
518:                     removeElementListener(pve.getOldValue());
519:                 } else if (pve instanceof AddAssociationEvent) {
520:                     addElementListener(pve.getNewValue(), "name");
521:                 }
522:             }
523:             // Pass everything except editing events to superclass
524:             super.propertyChange(pve);
525:         }
526: 
527:         if (Model.getFacade().isAModelElement(src) && !Model.getUmlFactory().isRemoved(getOwner())) {
528:             /* If the source of the event is an UML object,
529:              * then the UML model has been changed.*/
530:             modelChanged(pve);
