740:     /**
741:      * In ArgoUML, for every Fig, this setOwner() function
742:      * may only be called twice: Once after the fig is created, 
743:      * with a non-null argument, and once at end-of-life of the Fig,
744:      * with a null argument. It is not allowed in ArgoUML to change 
745:      * the owner of a fig in any other way. <p>
746:      * 
747:      * Hence, during the lifetime of this Fig object, 
748:      * the owner shall go from null to some UML object, and to null again.
749:      * 
750:      * @see org.tigris.gef.presentation.Fig#setOwner(java.lang.Object)
751:      */
752:     public void setOwner(Object newOwner) {
753:         if (newOwner != null && !Model.getFacade().isAModelElement(newOwner)) {
754:             throw new IllegalArgumentException(
755:                     "The owner must be a model element - got a "
756:                     + newOwner.getClass().getName());
757:         }
758:         updateListeners(newOwner);
759:         super.setOwner(newOwner);
760:         initNotationProviders(newOwner);
761:         if (newOwner != null) {
762:             renderingChanged();
763:         }
764:     }
