382:     /**
383:      * The user clicked on the clarifier.
384:      *
385:      * @param x the x of the point clicked
386:      * @param y the y of the point clicked
387:      * @return the todo item clicked
388:      */
389:     public ToDoItem hitClarifier(int x, int y) {
390:         int iconPos = 25, xOff = -4, yOff = -4;
391:         Point p = new Point();
392:         ToDoList list = Designer.theDesigner().getToDoList();
393:         Vector items = list.elementsForOffender(getOwner());
394:         int size = items.size();
395:         for (int i = 0; i < size; i++) {
396:             ToDoItem item = (ToDoItem) items.elementAt(i);
397:             Icon icon = item.getClarifier();
398:             stuffPointAlongPerimeter(iconPos, p);
399:             int width = icon.getIconWidth();
400:             int height = icon.getIconHeight();
401:             if (y >= p.y + yOff
402:                 && y <= p.y + height + yOff
403:                 && x >= p.x + xOff
404:                 && x <= p.x + width + xOff)
405:                 return item;
406:             iconPos += width;
407:         }
408:         for (int i = 0; i < size; i++) {
409:             ToDoItem item = (ToDoItem) items.elementAt(i);
410:             Icon icon = item.getClarifier();
411:             if (icon instanceof Clarifier) {
412:                 ((Clarifier) icon).setFig(this);
413:                 ((Clarifier) icon).setToDoItem(item);
414:                 if (((Clarifier) icon).hit(x, y))
415:                     return item;
416:             }
417:         }
418:         items = list.elementsForOffender(this);
419:         size = items.size();
420:         for (int i = 0; i < size; i++) {
421:             ToDoItem item = (ToDoItem) items.elementAt(i);
422:             Icon icon = item.getClarifier();
423:             stuffPointAlongPerimeter(iconPos, p);
424:             int width = icon.getIconWidth();
425:             int height = icon.getIconHeight();
426:             if (y >= p.y + yOff
427:                 && y <= p.y + height + yOff
428:                 && x >= p.x + xOff
429:                 && x <= p.x + width + xOff)
430:                 return item;
431:             iconPos += width;
432:         }
433:         for (int i = 0; i < size; i++) {
434:             ToDoItem item = (ToDoItem) items.elementAt(i);
435:             Icon icon = item.getClarifier();
436:             if (icon instanceof Clarifier) {
437:                 ((Clarifier) icon).setFig(this);
438:                 ((Clarifier) icon).setToDoItem(item);
439:                 if (((Clarifier) icon).hit(x, y))
440:                     return item;
441:             }
442:         }
443:         return null;
444:     }
