497:     /**
498:      * @see java.beans.PropertyChangeListener#propertyChange(java.beans.PropertyChangeEvent)
499:      */
500:     public void propertyChange(PropertyChangeEvent pve) {
501:         Object src = pve.getSource();
502:         String pName = pve.getPropertyName();
503:         // We handle and consume editing events
504:         if (pName.equals("editing")
505:             && Boolean.FALSE.equals(pve.getNewValue())) {
506:             LOG.debug("finished editing");
507:             textEdited((FigText) src);
508:             calcBounds();
509:             endTrans();
510:         } else if (pName.equals("editing")
511:                 && Boolean.TRUE.equals(pve.getNewValue())) {
512:             textEditStarted((FigText) src);
513:         } else {
514:             // Add/remove name change listeners for applied stereotypes
515:             if (src == getOwner()
516:                     && "stereotype".equals(pName)) {
517:                 if (pve instanceof RemoveAssociationEvent) {
518:                     removeElementListener(pve.getOldValue());
519:                 } else if (pve instanceof AddAssociationEvent) {
520:                     addElementListener(pve.getNewValue(), "name");
521:                 }
522:             }
523:             // Pass everything except editing events to superclass
524:             super.propertyChange(pve);
525:         }
526: 
527:         if (Model.getFacade().isAModelElement(src) && !Model.getUmlFactory().isRemoved(getOwner())) {
528:             /* If the source of the event is an UML object,
529:              * then the UML model has been changed.*/
530:             modelChanged(pve);
531:         }
532:         damage();  // TODO: (MVW) Is this required?
533:         // After all these events? I doubt it...
534:     }
