949:     /**
950:      * <p>Updates the classifiers the edge is attached to.  <p>Calls a
951:      * helper method (layoutThisToSelf) to avoid this edge
952:      * disappearing if the new source and dest are the same node.
953:      *
954:      * @return boolean whether or not the update was sucessful
955:      */
956:     protected boolean updateClassifiers() {
957:         Object owner = getOwner();
958:         if (owner == null || getLayer() == null) {
959:             return false;
960:         }
961: 
962:         Object newSource = getSource();
963:         Object newDest = getDestination();
964: 
965:         Fig currentSourceFig = getSourceFigNode();
966:         Fig currentDestFig = getDestFigNode();
967:         Object currentSource = null;
968:         Object currentDestination = null;
969:         if (currentSourceFig != null && currentDestFig != null) {
970:             currentSource = currentSourceFig.getOwner();
971:             currentDestination = currentDestFig.getOwner();
972:         }
973:         if (newSource != currentSource || newDest != currentDestination) {
974:             Fig newSourceFig = null;
975:             if (newSource != null)
976:                 newSourceFig = getLayer().presentationFor(newSource);
977:             Fig newDestFig = null;
978:             if (newDest != null)
979:                 newDestFig = getLayer().presentationFor(newDest);
980:             if (newSourceFig == null || newDestFig == null) {
981:                 removeFromDiagram();
982:                 return false;
983:             }
984:             if (newSourceFig != null && newSourceFig != currentSourceFig) {
985:                 setSourceFigNode((FigNode) newSourceFig);
986:                 setSourcePortFig(newSourceFig);
987: 
988:             }
989:             if (newDestFig != null && newDestFig != currentDestFig) {
990:                 setDestFigNode((FigNode) newDestFig);
991:                 setDestPortFig(newDestFig);
992:             }
993:             if (newDestFig != null && newSourceFig != null) {
994:                 ((FigNode) newSourceFig).updateEdges();
995:             }
996:             if (newSourceFig != null && newDestFig != null) {
997:                 ((FigNode) newDestFig).updateEdges();
998:             }
999:             calcBounds();
1000: 
1001:             // adapted from SelectionWButtons from line 280
1002:             // calls a helper method to avoid this edge disappearing
1003:             // if the new source and dest are the same node.
1004:             if (newSourceFig == newDestFig) {
1005: 
1006:                 layoutThisToSelf();
1007:             }
1008: 
1009:         }
1010: 
1011:         return true;
1012:     }
1013: 
1014:     /**
1015:      * helper method for updateClassifiers() in order to automatically
1016:      * layout an edge that is now from and to the same node type.
1017:      * <p>adapted from SelectionWButtons from line 280
1018:      */
1019:     private void layoutThisToSelf() {
1020: 
1021:         FigPoly edgeShape = new FigPoly();
1022:         //newFC = _content;
1023:         Point fcCenter =
1024:             new Point(getSourceFigNode().getX() / 2,
1025:                     getSourceFigNode().getY() / 2);
1026:         Point centerRight =
1027:             new Point(
1028: 		      (int) (fcCenter.x
1029: 			     + getSourceFigNode().getSize().getWidth() / 2),
1030: 		      fcCenter.y);
1031: 
1032:         int yoffset = (int) ((getSourceFigNode().getSize().getHeight() / 2));
1033:         edgeShape.addPoint(fcCenter.x, fcCenter.y);
1034:         edgeShape.addPoint(centerRight.x, centerRight.y);
1035:         edgeShape.addPoint(centerRight.x + 30, centerRight.y);
1036:         edgeShape.addPoint(centerRight.x + 30, centerRight.y + yoffset);
1037:         edgeShape.addPoint(centerRight.x, centerRight.y + yoffset);
1038: 
1039:         // place the edge on the layer and update the diagram
1040:         this.setBetweenNearestPoints(true);
1041:         edgeShape.setLineColor(Color.black);
1042:         edgeShape.setFilled(false);
1043:         edgeShape.setComplete(true);
1044:         this.setFig(edgeShape);
1045:     }
