328:     /**
329:      * distance formula: (x-h)^2 + (y-k)^2 = distance^2
330:      *
331:      * @param p1 point
332:      * @param p2 point
333:      * @return the square of the distance
334:      */
335:     public int getSquaredDistance(Point p1, Point p2) {
336:         int xSquared = p2.x - p1.x;
337:         xSquared *= xSquared;
338:         int ySquared = p2.y - p1.y;
339:         ySquared *= ySquared;
340:         return xSquared + ySquared;
341:     }
