32: package uci.gef;
33: 
34: import java.awt.*;
35: import java.awt.event.MouseEvent;
36: import uci.util.*;
37: import uci.graph.*;
38: 
39: /** A Mode to interpret user input while creating an edge.  Basically
40:  *  mouse down starts creating an edge from a source port Fig, mouse
41:  *  motion paints a rubberband line, mouse up finds the destination port
42:  *  and finishes creating the edge and makes an FigEdge and sends
43:  *  it to the back of the Layer.
44:  *
45:  *  The argument "edgeClass" determines the type if edge to suggest
46:  *  that the Editor's GraphModel construct.  The GraphModel is
47:  *  responsible for acutally making an edge in the underlying model
48:  *  and connecting it to other model elements. */
49: 
50: public class ModeCreateEdge extends ModeCreate {
51:   ////////////////////////////////////////////////////////////////
52:   // instance variables
53: 
54:   /** The NetPort where the arc is paintn from */
55:   private Object _startPort;
56: 
57:   /** The Fig that presents the starting NetPort */
58:   private Fig _startPortFig;
59: 
60:   /** The FigNode on the NetNode that owns the start port */
61:   private FigNode _sourceFigNode;
62: 
63:   /** The new NetEdge that is being created */
64:   private Object _newEdge;
65: 
66:   ////////////////////////////////////////////////////////////////
67:   // constructor
68: 
69:   public ModeCreateEdge() { super(); }
70:   public ModeCreateEdge(Editor par) { super(par); }
71: 
72:   ////////////////////////////////////////////////////////////////
73:   // Mode API
74: 
75:   public String instructions() {
76:     return "Drag to define an edge to another port";
77:   }
78: 
79:   ////////////////////////////////////////////////////////////////
80:   // ModeCreate API
81: 
82:   /** Create the new item that will be drawn. In this case I would
83:    *  rather create the FigEdge when I am done. Here I just
84:    *  create a rubberband FigLine to show during dragging. */
85:   public Fig createNewItem(MouseEvent me, int snapX, int snapY) {
86:     return new FigLine(snapX, snapY, 0, 0,
87: 		       Globals.getPrefs().getRubberbandColor());
88:   }
89: 
90:   ////////////////////////////////////////////////////////////////
91:   // event handlers
92: 
93:   /** On mousePressed determine what port the user is dragging from.
94:    *  The mousePressed event is sent via ModeSelect. */
95:   public void mousePressed(MouseEvent me) {
96:     int x = me.getX(), y = me.getY();
97:     Editor _editor = Globals.curEditor();
98:     Fig underMouse = _editor.hit(x, y);
99:     if (underMouse == null) { 
100:       //System.out.println("bighit");
101:         underMouse = _editor.hit(x-16, y-16, 32, 32); 
102:     }
103:     if (underMouse == null) { done(); me.consume(); return; }
104:     if (!(underMouse instanceof FigNode)) { done(); me.consume(); return; }
105:     _sourceFigNode = (FigNode) underMouse;
106:     _startPort = _sourceFigNode.deepHitPort(x, y);
107:     if (_startPort == null) { done(); me.consume(); return; }
108:     _startPortFig = _sourceFigNode.getPortFig(_startPort);
109:     super.mousePressed(me);
110:   }
111: 
112:   /** On mouseReleased, find the destination port, ask the GraphModel
113:    *  to connect the two ports.  If that connection is allowed, then
114:    *  construct a new FigEdge and add it to the Layer and send it to
115:    *  the back. */
116:   public void mouseReleased(MouseEvent me) {
117:     if (_sourceFigNode == null) { done(); me.consume(); return; }
118: 
119:     int x = me.getX(), y = me.getY();
120:     Class arcClass;
121:     Editor _editor = Globals.curEditor();
122:     Fig f = _editor.hit(x, y);
123:     if (f == null) { f = _editor.hit(x-16, y-16, 32, 32); }
124:     GraphModel gm = _editor.getGraphModel();
125:     if (!(gm instanceof MutableGraphModel)) f = null;
126:     MutableGraphModel mgm = (MutableGraphModel) gm;
127:     // needs-more-work: potential class cast exception
128: 
129:     if (f instanceof FigNode) {
130:       FigNode destFigNode = (FigNode) f;
131:       // If its a FigNode, then check within the  
132:       // FigNode to see if a port exists 
133:       Object foundPort = destFigNode.deepHitPort(x, y);
134: 
135:       if (foundPort != null && foundPort != _startPort) {
136: 	Fig destPortFig = destFigNode.getPortFig(foundPort);
137: 	Class edgeClass = (Class) getArg("edgeClass");
138: 	if (edgeClass != null)
139: 	  _newEdge = mgm.connect(_startPort, foundPort, edgeClass);
140: 	else
141: 	  _newEdge = mgm.connect(_startPort, foundPort);
142: 
143: 	// Calling connect() will add the edge to the GraphModel and
144: 	// any LayerPersectives on that GraphModel will get a
145: 	// edgeAdded event and will add an appropriate FigEdge
146: 	// (determined by the GraphEdgeRenderer).
147: 
148: 	if (null != _newEdge) {
149: 	  LayerManager lm = _editor.getLayerManager();
150: 	  _editor.damaged(_newItem);
151: 	  _sourceFigNode.damage();
152: 	  destFigNode.damage();
153: 	  _newItem = null;
154: 
155: 	  Fig pers = _editor.getLayerManager().getActiveLayer().
156: 	    presentationFor(_newEdge);
157: 	  if (pers != null) _editor.getSelectionManager().select(pers);
158: 	  done();
159: 	  me.consume();
160: 	  return;
161: 	}
162: 	else
163: 	  System.out.println("connection return null");
164:       }
165:     }
166:     _sourceFigNode.damage();
167:     _editor.damaged(_newItem);
168:     _newItem = null;
169:     done();
170:     me.consume();
171:   }
172: 
173: } /* end class ModeCreateEdge */
