348:                     parsedPackage);
349:         }
350:         if (_class == null) {
351:             _class = Model.getFacade().lookupIn(parsedPackage, "TestClass");
352:             assertNotNull("No class \"TestClass\" found.", _class);
353:         }
354:         Collection operations = Model.getFacade().getOperations(_class);
355:         assertNotNull("No operations found ib class.", operations);
356:         assertEquals("Number of operations is wrong", 4, operations.size());
357:         Object operation = null;
358:         Object operation_TestClass = null;
359:         Object operation_update = null;
360:         Object operation_getString = null;
361:         Object operation_x = null;
362:         Iterator iter = operations.iterator();
363:         while (iter.hasNext()) {
364:             operation = iter.next();
365:             assertTrue("The operation should be recognized as an operation.", 
366:                     Model.getFacade().isAOperation(operation));
367:             if ("TestClass".equals(Model.getFacade().getName(operation))) {
368:                 operation_TestClass = operation;
369:             } else if ("update".equals(Model.getFacade().getName(operation))) {
370:                 operation_update = operation;
371:             } else if ("getString".equals(Model.getFacade().getName(operation))) {
372:                 operation_getString = operation;
373:             } else if ("x".equals(Model.getFacade().getName(operation))) {
374:                 operation_x = operation;
375:             }
376:         }
377:         assertTrue("The operations have wrong names.",
378:             operation_TestClass != null 
379:             && operation_update != null 
380:             && operation_getString != null 
381:             && operation_x != null);
382:         assertTrue("Operation TestClass should be protected.", 
383:                 Model.getFacade().isProtected(operation_TestClass));
384:         assertEquals("The body of operation TestClass is wrong.",
385:             "\n        // A constructor with a single line comment\n        this.n = n;\n", getBody(operation_TestClass));
386:         assertTrue("Operation update should be public.", 
387:                 Model.getFacade().isPublic(operation_update));
388:         assertEquals("The body of operation update is wrong.",
389:             "\n        if (arg instanceof TestClass) testClass = (TestClass)arg;\n", 
390:             getBody(operation_update));
391:         assertTrue("Operation getString should be static.", 
392:                 Model.getFacade().isClassifierScope(operation_getString));
393:         assertTrue("Operation getString should be private.", 
394:                 Model.getFacade().isPrivate(operation_getString));
395:         assertEquals("The body of operation getString is wrong.",
