397:             getBody(operation_getString));
398:         assertTrue("Operation x should be abstract.", 
399:                 Model.getFacade().isAbstract(operation_x));
400:         assertTrue("Operation x should have package visibility.", 
401:                 Model.getFacade().isPackage(operation_x));
402:     }
