62: public class SelectionComponentInstance extends SelectionWButtons {
63:     protected static Category cat = 
64:         Category.getInstance(SelectionComponentInstance.class);
65:   ////////////////////////////////////////////////////////////////
66:   // constants
67:   public static Icon dep = ResourceLoaderWrapper.getResourceLoaderWrapper().lookupIconResource("Dependency");
68:   public static Icon depRight = 
69:       ResourceLoaderWrapper.getResourceLoaderWrapper().lookupIconResource("DependencyRight");
70: 
71: 
72:   ////////////////////////////////////////////////////////////////
73:   // constructors
74: 
75:   /** Construct a new SelectionComponentInstanceInstance for the given Fig */
76:   public SelectionComponentInstance(Fig f) { super(f); }
77: 
78:   public void hitHandle(Rectangle r, Handle h) {
79:     super.hitHandle(r, h);
80:     if (h.index != -1) return;
81:     if (!_paintButtons) return;
82:     Editor ce = Globals.curEditor();
83:     SelectionManager sm = ce.getSelectionManager();
84:     if (sm.size() != 1) return;
85:     ModeManager mm = ce.getModeManager();
86:     if (mm.includes(ModeModify.class) && _pressedButton == -1) return;
87:     int cx = _content.getX();
88:     int cy = _content.getY();
89:     int cw = _content.getWidth();
90:     int ch = _content.getHeight();
91:     int aw = dep.getIconWidth();
92:     int ah = dep.getIconHeight();
93:     if (hitAbove(cx + cw/2, cy, aw, ah, r)) {
94:       h.index = 10;
95:       h.instructions = "Add a component-instance";
96:     }
97:     else if (hitBelow(cx + cw/2, cy + ch, aw, ah, r)) {
98:       h.index = 11;
99:       h.instructions = "Add a component-instance";
100:     }
101:     else if (hitLeft(cx + cw, cy + ch/2, aw, ah, r)) {
102:       h.index = 12;
103:       h.instructions = "Add a component-instance";
104:     }
105:     else if (hitRight(cx, cy + ch/2, aw, ah, r)) {
106:       h.index = 13;
107:       h.instructions = "Add a component-instance";
108:     }
109:     else {
110:       h.index = -1;
111:       h.instructions = "Move object(s)";
112:     }
113:   }
114: 
115: 
116:   /** Paint the handles at the four corners and midway along each edge
117:    * of the bounding box.  */
118:   public void paintButtons(Graphics g) {
119:     int cx = _content.getX();
120:     int cy = _content.getY();
121:     int cw = _content.getWidth();
122:     int ch = _content.getHeight();
123:     paintButtonAbove(dep, g, cx + cw/2, cy, 10);
124:     paintButtonBelow(dep, g, cx + cw/2, cy + ch, 11);
125:     paintButtonLeft(depRight, g, cx + cw, cy + ch/2, 12);
126:     paintButtonRight(depRight, g, cx, cy + ch/2, 13);
127:   }
128: 
129: 
130:   public void dragHandle(int mX, int mY, int anX, int anY, Handle hand) {
131:     if (hand.index < 10) {
132:       _paintButtons = false;
133:       super.dragHandle(mX, mY, anX, anY, hand);
134:       return;
135:     }
136:     int cx = _content.getX(), cy = _content.getY();
137:     int cw = _content.getWidth(), ch = _content.getHeight();
138:     int newX = cx, newY = cy, newW = cw, newH = ch;
139:     Dimension minSize = _content.getMinimumSize();
140:     int minWidth = minSize.width, minHeight = minSize.height;
141:     Class edgeClass = null;
142:     Class nodeClass = MComponentInstanceImpl.class;
143:     int bx = mX, by = mY;
144:     boolean reverse = false;
145:     switch (hand.index) {
146:     case 10: //add dep
147:       edgeClass = MDependency.class;
148:       // reverse = true;
149:       by = cy;
150:       bx = cx + cw/2;
151:       break;
152:     case 11: //add dep
153:       edgeClass = MDependency.class;
154:       reverse = true;
155:       by = cy + ch;
156:       bx = cx + cw/2;
157:       break;
158:     case 12: //add dep
159:       edgeClass = MDependency.class;
160:       // reverse = true;
161:       by = cy + ch/2;
162:       bx = cx + cw;
163:       break;
164:     case 13: // add dep
165:       edgeClass = MDependency.class;
166:       reverse = true;
167:       by = cy + ch/2;
168:       bx = cx;
169:       break;
170:     default:
171:       cat.warn("invalid handle number");
172:       break;
173:     }
174:     if (edgeClass != null && nodeClass != null) {
175:       Editor ce = Globals.curEditor();
176:       ModeCreateEdgeAndNode m = new
177: 	ModeCreateEdgeAndNode(ce, edgeClass, nodeClass, false);
178:       m.setup((FigNode)_content, _content.getOwner(), bx, by, reverse);
179:       ce.mode(m);
180:     }
181: 
182:   }
183: 
184: 
185:   public void buttonClicked(int buttonCode) {
186:     super.buttonClicked(buttonCode);
187:     MComponentInstance newNode = UmlFactory.getFactory().getCommonBehavior().createComponentInstance();
188:     FigComponentInstance fc = (FigComponentInstance) _content;
189:     MComponentInstance cls = (MComponentInstance) fc.getOwner();
190: 
191:     Editor ce = Globals.curEditor();
192:     GraphModel gm = ce.getGraphModel();
193:     if (!(gm instanceof MutableGraphModel)) return;
194:     MutableGraphModel mgm = (MutableGraphModel) gm;
195: 
196:     if (!mgm.canAddNode(newNode)) return;
197:     GraphNodeRenderer renderer = ce.getGraphNodeRenderer();
198:     LayerPerspective lay = (LayerPerspective)
199:       ce.getLayerManager().getActiveLayer();
200:     Fig newFC = renderer.getFigNodeFor(gm, lay, newNode);
201: 
202:     Rectangle outputRect = new Rectangle(Math.max(0, fc.getX() - 200),
203: 					 Math.max(0, fc.getY() - 200),
204: 					 fc.getWidth() + 400,
205: 					 fc.getHeight() + 400);
206:    // handle the case that it is not a self association
207:         if (buttonCode >=10 && buttonCode <= 13) {
208:             int x = 0;
209:             int y = 0; 
210:             if (buttonCode == 10) {
211:                 // superclass
212:                 x = fc.getX();
213:                 y = Math.max(0, fc.getY() - 200);
214:             }
215:             else if (buttonCode == 11) {
216:                 x = fc.getX();
217:                 y = fc.getY() + fc.getHeight() + 100;
218:             }
219:             else if (buttonCode == 12) {
220:                 x = fc.getX() + fc.getWidth() + 100;
221:                 y = fc.getY();
222:             }
223:             else if (buttonCode == 13) {
224:                 x = Math.max(0, fc.getX() - 200);
225:                 y = fc.getY();
226:                 
227:             }        
228:             // place the fig if it is not a selfassociation       
229:             if (!placeFig(newFC, lay, x, y, outputRect)) return;
230:         }
231:     ce.add(newFC);
232:     mgm.addNode(newNode);
233: 
234:     FigPoly edgeShape = new FigPoly();
235:     Point fcCenter = fc.center();
236:     edgeShape.addPoint(fcCenter.x, fcCenter.y);
237:     Point newFCCenter = newFC.center();
238:     edgeShape.addPoint(newFCCenter.x, newFCCenter.y);
239:     Object newEdge = null;
240: 
241:     if (buttonCode == 10) newEdge = addCompClassAbove(mgm, cls, newNode);
242:     else if (buttonCode == 11) newEdge = addCompClassBelow(mgm, cls, newNode);
243:     else if (buttonCode == 12) newEdge = addCompClassRight(mgm, cls, newNode);
244:     else if (buttonCode == 13) newEdge = addCompClassLeft(mgm, cls, newNode);
245: 
246:     FigEdge fe = (FigEdge) lay.presentationFor(newEdge);
247:     edgeShape.setLineColor(Color.black);
248:     edgeShape.setFilled(false);
249:     edgeShape._isComplete = true;
250:     fe.setFig(edgeShape);
251:     ce.getSelectionManager().select(fc);
252:   }
253: 
254:   public Object addCompClassAbove(MutableGraphModel mgm, MComponentInstance cls,
255: 			    MComponentInstance newCls) {
256:     return mgm.connect(cls, newCls, MDependency.class);
257:   }
258: 
259:   public Object addCompClassBelow(MutableGraphModel mgm, MComponentInstance cls,
260: 			    MComponentInstance newCls) {
261:     return mgm.connect(newCls, cls, MDependency.class);
262:   }
263:   public Object addCompClassRight(MutableGraphModel mgm, MComponentInstance cls,
264: 			    MComponentInstance newCls) {
265:     return mgm.connect(cls, newCls, MDependency.class);
266:   }
267: 
268:   public Object addCompClassLeft(MutableGraphModel mgm, MComponentInstance cls,
269: 			    MComponentInstance newCls) {
270:     return mgm.connect(newCls, cls, MDependency.class);
271:   }
272: 
273: 
274: } /* end class SelectionComponentInstanceInstance */
