120:         int ih = inherit.getIconHeight();
121:         int aw = assoc.getIconWidth();
122:         int ah = assoc.getIconHeight();
123:         int saw = selfassoc.getIconWidth();
124:         int sah = selfassoc.getIconHeight();
125: 
126:         if (hitAbove(cx + cw/2, cy, iw, ih, r)) {
127:             h.index = 10;
128:             h.instructions = "Add a superclass";
129:         }
130:         else if (hitBelow(cx + cw/2, cy + ch, iw, ih, r)) {
131:             h.index = 11;
132:             h.instructions = "Add a subclass";
133:         }
134:         else if (hitLeft(cx + cw, cy + ch/2, aw, ah, r)) {
135:             h.index = 12;
136:             h.instructions = "Add an associated class";
137:         }
138:         else if (hitRight(cx, cy + ch/2, aw, ah, r)) {
139:             h.index = 13;
140:             h.instructions = "Add an associated class";
141:         }
142:         else if (hitRight(cx, cy + ch - 10, saw, sah, r)) {
143:             h.index = 14;
144:             h.instructions = "Add a self association";
145:         }
146:         else {
147:             h.index = -1;
148:             h.instructions = "Move object(s)";
149:         }
