183:     public void dragHandle(int mX, int mY, int anX, int anY, Handle hand) {
184:         if (hand.index < 10) {
185:             _paintButtons = false;
186:             super.dragHandle(mX, mY, anX, anY, hand);
187:             return;
188:         }
189:         int cx = _content.getX(), cy = _content.getY();
190:         int cw = _content.getWidth(), ch = _content.getHeight();
191:         int newX = cx, newY = cy, newW = cw, newH = ch;
192:         Dimension minSize = _content.getMinimumSize();
193:         int minWidth = minSize.width, minHeight = minSize.height;
194:         Class edgeClass = null;
195:         Class nodeClass = ru.novosoft.uml.foundation.core.MClassImpl.class;
196:         int bx = mX, by = mY;
197:         boolean reverse = false;
198:         switch (hand.index) {
199:         case 10: //add superclass
200:             edgeClass = ru.novosoft.uml.foundation.core.MGeneralization.class;
201:             by = cy;
202:             bx = cx + cw/2;
203:             break;
204:         case 11: //add subclass
205:             edgeClass = ru.novosoft.uml.foundation.core.MGeneralization.class;
206:             reverse = true;
207:             by = cy + ch;
208:             bx = cx + cw/2;
209:             break;
210:         case 12: //add assoc
211:             edgeClass = ru.novosoft.uml.foundation.core.MAssociation.class;
212:             by = cy + ch/2;
213:             bx = cx + cw;
214:             break;
215:         case 13: // add assoc
216:             edgeClass = ru.novosoft.uml.foundation.core.MAssociation.class;
217:             reverse = true;
218:             by = cy + ch/2;
219:             bx = cx;
220:             break;
221:         case 14: // selfassociation
222:             // do not want to drag this
223:             break;
224:         default:
225:             cat.warn("invalid handle number");
226:             break;
227:         }
228:         if (edgeClass != null && nodeClass != null) {
229:             Editor ce = Globals.curEditor();
230:             ModeCreateEdgeAndNode m = new
231:                 ModeCreateEdgeAndNode(ce, edgeClass, nodeClass, _useComposite);
232:             m.setup((FigNode)_content, _content.getOwner(), bx, by, reverse);
233:             ce.mode(m);
234:         }
235: 
236:     }
