232:   public void buttonClicked(int buttonCode) {
233:     super.buttonClicked(buttonCode);
234:     MActionState newNode =  UmlFactory.getFactory().getActivityGraphs().createActionState();
235: 
236:     FigStateVertex fc = (FigStateVertex) _content;
237:     MStateVertex cls = (MStateVertex) fc.getOwner();
238: 
239:     Editor ce = Globals.curEditor();
240:     GraphModel gm = ce.getGraphModel();
241:     if (!(gm instanceof MutableGraphModel)) return;
242:     MutableGraphModel mgm = (MutableGraphModel) gm;
243: 
244:     if (!mgm.canAddNode(newNode)) return;
245:     GraphNodeRenderer renderer = ce.getGraphNodeRenderer();
246:     LayerPerspective lay = (LayerPerspective)
247:       ce.getLayerManager().getActiveLayer();
248:     Fig newFC = renderer.getFigNodeFor(gm, lay, newNode);
249: 
250:     Rectangle outputRect = new Rectangle(Math.max(0, fc.getX() - 200),
251: 					 Math.max(0, fc.getY() - 200),
252: 					 fc.getWidth() + 400,
253: 					 fc.getHeight() + 400);
254:     if (buttonCode >=10 && buttonCode <= 13) {
255:             int x = 0;
256:             int y = 0; 
257:             if (buttonCode == 10) {
258:                 // superclass
259:                 x = fc.getX();
260:                 y = Math.max(0, fc.getY() - 200);
261:             }
262:             else if (buttonCode == 11) {
263:                 x = fc.getX();
264:                 y = fc.getY() + fc.getHeight() + 100;
265:             }
266:             else if (buttonCode == 12) {
267:                 x = fc.getX() + fc.getWidth() + 100;
268:                 y = fc.getY();
269:             }
270:             else if (buttonCode == 13) {
271:                 x = Math.max(0, fc.getX() - 200);
272:                 y = fc.getY();
273:                 
274:             }        
275:             // place the fig if it is not a selfassociation       
276:             if (!placeFig(newFC, lay, x, y, outputRect)) return;
277:         }
278:   
279:     ce.add(newFC);
280:     mgm.addNode(newNode);
281: 
282:     FigPoly edgeShape = new FigPoly();
283:     Point fcCenter = fc.center();
284:     edgeShape.addPoint(fcCenter.x, fcCenter.y);
285:     Point newFCCenter = newFC.center();
286:     edgeShape.addPoint(newFCCenter.x, newFCCenter.y);
287:     Object newEdge = null;
288:     if (buttonCode == 12) newEdge = addOutgoingTrans(mgm, cls, newNode);
289:     else if (buttonCode == 13) newEdge = addIncomingTrans(mgm, cls, newNode);
290:     else if (buttonCode == 14) newEdge = addIncomingTrans(mgm, cls, newNode);
291:     else if (buttonCode == 15) newEdge = addOutgoingTrans(mgm, cls, newNode);
292: 
293:     FigEdge fe = (FigEdge) lay.presentationFor(newEdge);
294:     edgeShape.setLineColor(Color.black);
295:     edgeShape.setFilled(false);
296:     edgeShape._isComplete = true;
297:     fe.setFig(edgeShape);
298:     ce.getSelectionManager().select(fc);
299:   }
