275:     public void setTarget(Object t) {
276:         LOG.debug("setTarget called with " + t + " as parameter (not target!)");
277:         t = (t instanceof Fig) ? ((Fig) t).getOwner() : t;
278: 
279:         // If the target has changed notify the third party listener if it
280:         // exists and dispatch a new element event listener to
281:         // ourself. Otherwise dispatch a target reasserted to ourself.
282:         Runnable dispatch = null;
283:         if (t != target) {
284: 
285:             // Set up the target and its model element variant.
286: 
287:             target = t;
288:             modelElement = null;
289:             if (listenerList == null) {
290:                 listenerList = registrateTargetListeners(this);
291:             }
292: 
293:             if (Model.getFacade().isAModelElement(target)) {
294:                 modelElement = target;
295:             }
296: 
297:             // This will add a new ModelElement event listener
298:             // after update is complete
299: 
300:             dispatch = new UMLChangeDispatch(this,
301:                     UMLChangeDispatch.TARGET_CHANGED_ADD);
302: 
303:         } else {
304:             dispatch = new UMLChangeDispatch(this,
305:                     UMLChangeDispatch.TARGET_REASSERTED);
306: 
307:         }
308:         SwingUtilities.invokeLater(dispatch);
309: 
310:         // update the titleLabel
311:         // MVW: This overrules the icon set initiallly... Why do we need this?
312:         if (titleLabel != null) {
313:             Icon icon = null;
314:             if (t != null) { 
315:                 icon = ResourceLoaderWrapper.getInstance().lookupIcon(t);
316:             }
317:             if (icon != null) {
318:                 titleLabel.setIcon(icon);
319:             }
320:         }
321:     }
