32: /**
33:  * A searchable combobox. Searchable means that the user has only to type the
34:  * starting of a modelelement name to select that modelelement. The first
35:  * modelelement that conforms to the typed text is selected.
36:  * @author jaap.branderhorst@xs4all.nl	
37:  * @since Jan 5, 2003
38:  */
39: public class UMLSearchableComboBox extends UMLEditableComboBox {
40: 
41:     /**
42:      * Constructor for UMLSearchableComboBox.
43:      * @param model
44:      * @param selectAction
45:      * @param showIcon
46:      */
47:     public UMLSearchableComboBox(UMLComboBoxModel2 model, UMLAction selectAction, boolean showIcon) {
48:         super(model, selectAction, showIcon);
49:     }
50: 
51:     /**
52:      * Constructor for UMLSearchableComboBox.
53:      * @param arg0
54:      * @param selectAction
55:      */
56:     public UMLSearchableComboBox(UMLComboBoxModel2 arg0, UMLAction selectAction) {
57:         this(arg0, selectAction, false);
58:     }
59: 
60:     /**
61:      * Searches amongst the modelelements (the elements in the listmodel) for an
62:      * item that conforms to the parameter item. If such an element is a
63:      * MModelelement, the name should start with the item (which is a String).
64:      * Otherwise the text that is shown in the combobox should start with the
65:      * text. As the element is found, this is made to the selected item.
66:      * @see org.argouml.uml.ui.UMLEditableComboBox#doIt(java.lang.Object)
67:      */
68:     protected void doIt(Object item) {
69:         String text = (String) item;
70:         ComboBoxModel model = getModel();
71:         for (int i = 0; i < model.getSize(); i++) {
72:             Object element = model.getElementAt(i);
73:             if (element instanceof MBase) {
74:                 if (getRenderer() instanceof UMLListCellRenderer2) {
75:                     String labelText = ((UMLListCellRenderer2) getRenderer()).makeText((MBase) element);
76:                     if (labelText != null && labelText.startsWith(text)) {
77:                         model.setSelectedItem(element);
78:                         break;
79:                     }
80:                 }
81:                 if (element instanceof MModelElement) {
82:                     MModelElement elem = (MModelElement) element;
83:                     String name = elem.getName();
84:                     if (name != null && name.startsWith(text)) {
85:                         model.setSelectedItem(element);
86:                         break;
87:                     }
88:                 }
89:             }
90: 
91:         }
92: 
93:     }
94: 
95: }
