42: /**
43:  * The fig for a link in a sequence diagram.
44:  *
45:  * @author jaap.branderhorst@xs4all.nl
46:  */
47: public abstract class FigMessage
48:     extends FigEdgeModelElement {
49: 
50:     private FigTextGroup textGroup;
51: 
52:     /**
53:      * Contructs a new figlink and sets the owner of the figlink.
54:      *
55:      * @param owner is the owner.
56:      */
57:     public FigMessage(Object owner) {
58:         super();
59:         textGroup = new FigTextGroup();
60:         textGroup.addFig(getNameFig());
61:         textGroup.addFig(getStereotypeFig());
62:         addPathItem(textGroup, new PathConvPercent(this, 50, 10));
63:         setOwner(owner);
64:     }
65: 
66:     /**
67:      * Constructor here for saving and loading purposes.
68:      *
69:      */
70:     public FigMessage() {
71:         this(null);
72:     }
73: 
74:     /**
75:      * Build a collection of menu items relevant for a right-click
76:      * popup menu on a message.
77:      *
78:      * @param     me     a mouse event
79:      * @return           a collection of menu items
80:      *
81:      * @see org.tigris.gef.ui.PopupGenerator#getPopUpActions(java.awt.event.MouseEvent)
82:      */
83:     public Vector getPopUpActions(MouseEvent me) {
84:         Vector popUpActions = super.getPopUpActions(me);
85: 
86:         // the menu item for RE a sequence into the diagram is offered always,
87:         // becauase some check (does a operation with a body exist) would be
88:         // too expensive
89:         popUpActions.insertElementAt(new ActionRESequenceDiagram(this),
90:                 popUpActions.size() - getPopupAddOffset());
91: 
92:         return popUpActions;
93:     }
94: 
95:     /**
96:      * Returns the action attached to this link if any.<p>
97:      *
98:      * @return the action attached to this link or null if there isn't any.
99:      */
100:     public Object getAction() {
101:         Object owner = getOwner();
102:         if (owner != null && Model.getFacade().isAMessage(owner)) {
103:             return Model.getFacade().getAction(owner);
104:         }
105:         return null;
106:     }
107: 
108:     /**
109:      * @see org.tigris.gef.presentation.FigEdge#getSourcePortFig()
110:      */
111:     public Fig getSourcePortFig() {
112:         Fig result = super.getSourcePortFig();
113:         if (result instanceof FigClassifierRole.TempFig
114:                 && getOwner() != null) {
115:             result =
116:                 getSourceFigClassifierRole().createFigMessagePort(getOwner(),
117:                         (FigClassifierRole.TempFig)result);
118:             setSourcePortFig(result);
119:         }
120:         return result;
121:     }
122: 
123:     /**
124:      * @see org.tigris.gef.presentation.FigEdge#getDestPortFig()
125:      */
126:     public Fig getDestPortFig() {
127:         Fig result = super.getDestPortFig();
128:         if (result instanceof FigClassifierRole.TempFig
129:                 && getOwner() != null) {
130:             result =
131:                 getDestFigClassifierRole().createFigMessagePort(getOwner(),
132:             						(FigClassifierRole.TempFig)result);
133:             setDestPortFig(result);
134:         }
135:         return result;
136:     }
137: 
138:     /**
139:      * Computes the route of this {@link FigMessage} and computes the
140:      * connectionpoints of the figlink to the ports.  This depends on
141:      * the action attached to the owner of the {@link FigMessage}.  Also
142:      * adds FigActivations etc or moves the {@link FigClassifierRole}s
143:      * if necessary.<p>
144:      *
145:      * @see org.tigris.gef.presentation.FigEdge#computeRoute()
146:      */
147:     public void computeRouteImpl() {
148:         Fig sourceFig = getSourcePortFig();
149:         Fig destFig = getDestPortFig();
150:         if (sourceFig instanceof FigMessagePort
151:                 && destFig instanceof FigMessagePort) {
152:             FigMessagePort srcMP = (FigMessagePort) sourceFig;
153:             FigMessagePort destMP = (FigMessagePort) destFig;
154:             Point startPoint = sourceFig.connectionPoint(destMP.getCenter());
155:             Point endPoint = destFig.connectionPoint(srcMP.getCenter());
156:             // If it is a self-message
157:             if (isSelfMessage()) {
158:                 if (startPoint.x < sourceFig.getCenter().x) {
159:                     startPoint.x += sourceFig.getWidth();
160:                 }
161:                 endPoint.x = startPoint.x;
162:                 setEndPoints(startPoint, endPoint);
163:                 // If this is the first time it is laid out, will only
164:                 // have 2 points, add the middle point
165:                 if (getNumPoints() <= 2) {
166:                     insertPoint(0, startPoint.x
167:                             + SequenceDiagramLayer.OBJECT_DISTANCE / 3,
168:                                 (startPoint.y + endPoint.y) / 2);
169:                 } else {
170:                     // Otherwise, move the middle point
171:                     int middleX =
172:                         startPoint.x
173:                         + SequenceDiagramLayer.OBJECT_DISTANCE / 3;
174:                     int middleY = (startPoint.y + endPoint.y) / 2;
175:                     Point p = getPoint(1);
176:                     if (p.x != middleX || p.y != middleY) {
177:                         setPoint(new Handle(1), middleX, middleY);
178:                     }
179:                 }
180:             } else {
181:                 setEndPoints(startPoint, endPoint);
182:             }
183:             calcBounds();
184:             layoutEdge();
185:         }
186:     }
187:     
188:     private boolean isSelfMessage() {
189:         FigMessagePort srcMP = (FigMessagePort) getSourcePortFig();
190:         FigMessagePort destMP = (FigMessagePort) getDestPortFig();
191:         return (srcMP.getNode().getFigClassifierRole()
192:                 == destMP.getNode().getFigClassifierRole());
193:     }
194: 
195:     /**
196:      * @return the node for the source port fig
197:      */
198:     public MessageNode getSourceMessageNode() {
199:         return ((FigMessagePort) getSourcePortFig()).getNode();
200:     }
201: 
202:     /**
203:      * @return the node for the destination port fig
204:      */
205:     public MessageNode getDestMessageNode() {
206:         return ((FigMessagePort) getDestPortFig()).getNode();
207:     }
208: 
209:     /**
210:      * Returns the message belonging to this link if there is one
211:      * (otherwise null).<p>
212:      *
213:      * @return the message.
214:      */
215:     public Object getMessage() {
216:     	return getOwner();
217:     }
218: 
219:     /**
220:      * @see org.tigris.gef.presentation.FigEdgePoly#layoutEdge()
221:      */
222:     protected void layoutEdge() {
223:         if (getSourcePortFig() instanceof FigMessagePort
224:                 && getDestPortFig() instanceof FigMessagePort
225:                 && ((FigMessagePort) getSourcePortFig()).getNode() != null
226:                 && ((FigMessagePort) getDestPortFig()).getNode() != null) {
227:             ((SequenceDiagramLayer) getLayer()).updateActivations();
228:             Globals.curEditor().damageAll();
229:         }
230:     }
231: 
232:     /**
233:      * @see org.argouml.uml.diagram.ui.FigEdgeModelElement#getSource()
234:      */
235:     protected Object getSource() {
236:         Object owner = getOwner();
237:         if (owner == null) {
238:             return null;
239: 	}
240:         return Model.getFacade().getSender(owner);
241:     }
242: 
243:     /**
244:      * @see org.argouml.uml.diagram.ui.FigEdgeModelElement#getDestination()
245:      */
246:     protected Object getDestination() {
247:         Object owner = getOwner();
248:         if (owner == null) {
249:             return null;
250: 	}
251: 
252:         return Model.getFacade().getReceiver(owner);
253:     }
254: 
255:     /**
256:      * Call superclass to update text then recalculate group bounds
257:      * 
258:      * @see org.argouml.uml.diagram.ui.FigEdgeModelElement#updateNameText()
259:      */
260:     protected void updateNameText() {
261:         super.updateNameText();
262:         textGroup.calcBounds();
263:     }
264:     
265:     /**
266:      * Call superclass to update text then recalculate group bounds
267:      * 
268:      * @see org.argouml.uml.diagram.ui.FigEdgeModelElement#updateStereotypeText()
269:      */
270:     protected void updateStereotypeText() {
271:         super.updateStereotypeText();
272:         textGroup.calcBounds();
273:     }
274: 
275:     /**
276:      * @return the source figobject
277:      */
278:     public FigClassifierRole getSourceFigClassifierRole() {
279:         return (FigClassifierRole) getSourceFigNode();
280:     }
281: 
282:     /**
283:      * @return the destination fig object
284:      */
285:     public FigClassifierRole getDestFigClassifierRole() {
286:         return (FigClassifierRole) getDestFigNode();
287:     }
288: 
289:     /**
290:      * This won't work, so this implementation does nothing.
291:      *
292:      * @see org.argouml.uml.diagram.ui.FigEdgeModelElement#updateClassifiers()
293:      */
294:     protected boolean updateClassifiers() {
295:         return true;
296:     }
297: 
298:     /**
299:      * @see org.tigris.gef.presentation.Fig#makeSelection()
300:      */
301:     public Selection makeSelection() {
302:         return new SelectionMessage(this);
303:     }
304: }
