112:     public FigFinalState(GraphModel gm, Object node) {
113: 	this();
114: 	setOwner(node);
115:     }
116: 
117:     public Object clone() {
118: 	FigFinalState figClone = (FigFinalState) super.clone();
119: 	Iterator it = figClone.getFigs(null).iterator();
120: 	figClone._bigPort = (FigRect) it.next();
121: 	figClone._outCircle = (FigCircle) it.next();
122: 	figClone._inCircle = (FigCircle) it.next();
123: 	return figClone;
