199: 	_y = y;
200: 	_bigPort.setX(x);
201: 	_bigPort.setY(y);
202: 	_outCircle.setX(x);
203: 	_outCircle.setY(y);
204: 	_inCircle.setX(x + 5);
205: 	_inCircle.setY(y + 5);
206: 	// _bigPort.setBounds(x, y, w, h);
207: 	// _outCircle.setBounds(x, y, w, h);
