217: 
218:     /**
219:      * Makes sure that edges stick to the outer circle and not to the name or
220:      * stereobox.
221:      * @see org.tigris.gef.presentation.Fig#getGravityPoints()
222:      */
223:     public Vector getGravityPoints() {
224: 	Vector ret = new Vector();
225: 	int cx = _outCircle.center().x;
226: 	int cy = _outCircle.center().y;
227: 	int radius = Math.round(_outCircle.getWidth() / 2) + 1;
228: 	int MAXPOINTS = 20;
229: 	Point point = null;
230: 	for (int i = 0; i < MAXPOINTS; i++) {
231: 	    point =
232: 		new Point((int)
233: 			  (cx
234: 			   + Math.cos(2 * Math.PI / MAXPOINTS * i) * radius),
235: 			  (int)
236: 			  (cy
237: 			   + Math.sin(2 * Math.PI / MAXPOINTS * i) * radius));
238: 	    ret.add(point);
239: 	}
240: 	return ret;
241: 		
242:     }
