265:         }
266:         if (_westPane != null) {
267:             detailsPanesByCompassPoint.put(BorderSplitPane.WEST, _westPane);
268:         }
269:         if (_southWestPane != null) {
270:             detailsPanesByCompassPoint.put(BorderSplitPane.SOUTHWEST,
271: 					   _southWestPane);
272:         }
273: 
274:         // The workarea is all the visible space except the menu,
275:         // toolbar and status bar.  Workarea is layed out as a
276:         // BorderSplitPane where the various components that make up
277:         // the argo application can be positioned.
278:         workAreaPane = new BorderSplitPane();
279:         // create the todopane
280:         if (doSplash) {
281: 	    splashScreen.getStatusBar().showStatus(Translator.localize(
282: 		    "statusmsg.bar.making-project-browser-to-do-pane"));
283:             splashScreen.getStatusBar().incProgress(5);
284:         }
285:         todoPane = new ToDoPane(doSplash);
286:         restorePanelSizes();
287: 
288:         // There are various details panes all of which could hold
289:         // different tabs pages according to users settings.
290:         // Place each pane in the required border area.
291:         Iterator it = detailsPanesByCompassPoint.entrySet().iterator();
292:         while (it.hasNext()) {
293:             Map.Entry entry = (Map.Entry) it.next();
294:             String position = (String) entry.getKey();
295:             if (entry.getValue() instanceof DetailsPane) {
296:                 DetailsPane detailsPane = (DetailsPane) entry.getValue();
297:                 TargetManager.getInstance().addTargetListener(detailsPane);
298:             }
299:             workAreaPane.add((Component) entry.getValue(), position);
300:         }
301:         workAreaPane.add(explorerPane, BorderSplitPane.WEST);
302:         
303:         getTab(TabToDo.class); // TODO: If this doesn't have side effects, 
304:                                //       it can be removed alltogether.
305:         //todo.setTree(_todoPane);
306:         workAreaPane.add(todoPane, BorderSplitPane.SOUTHWEST);
307:         workAreaPane.add(_editorPane);
308:         // Toolbar boundry is the area between the menu and the status
309:         // bar. It contains the workarea at centre and the toolbar
310:         // position north, south, east or west.
311:         JPanel toolbarBoundry = new JPanel();
312:         toolbarBoundry.setLayout(new DockBorderLayout());
313:         // TODO: - should save and restore the last positions of the toolbars
314:         toolbarBoundry.add(menuBar.getFileToolbar(), BorderLayout.NORTH);
315:         toolbarBoundry.add(menuBar.getEditToolbar(), BorderLayout.NORTH);
316:         toolbarBoundry.add(menuBar.getViewToolbar(), BorderLayout.NORTH);
317:         toolbarBoundry.add(menuBar.getCreateDiagramToolbar(),
318: 			   BorderLayout.NORTH);
319:         toolbarBoundry.add(workAreaPane, BorderLayout.CENTER);
320: 
321:         return toolbarBoundry;
