50: /**
51:  * Class to display graphics for a UML ObjectFlowState in a diagram.<p>
52:  *
53:  * The Fig of this modelelement may either represent the following UMLelements:
54:  * <p> 
55:  * (1) an ObjectFlowState with a Classifier as type, or <p> 
56:  * (2) an ObjectFlowState with a ClassifierInState as type. <p>
57:  * 
58:  * In both cases (1) and (2), the Fig shows the underlined name of the Classifier,
59:  * and in the latter case (2), it shows also the names of the states 
60:  * of the ClassifierInState. <p>
61:  * 
62:  * In the examples in the UML standard, this is written like<pre>
63:  *      PurchaseOrder
64:  *       [approved]
65:  * </pre>
66:  * i.e. in 2 lines. The first line is underlined,
67:  * to indicate that it is an instance (object).<p>
68:  *
69:  * The fact that the first line is underlined, and the 2nd not, is the
70:  * reason to implement them in 2 seperate Figs.<p>
71:  *
72:  * TODO: Allow stereotypes to be shown.
73:  *
74:  * @author mvw
75:  */
76: public class FigObjectFlowState extends FigNodeModelElement {
77: 
78:     private static final int PADDING = 8;
79:     private static final int OFFSET = 10;
80:     private static final int WIDTH = 70;
81:     private static final int HEIGHT = 40;
82: 
83:     private FigRect cover;
84:     private FigText state;      // the state name
85: 
86:     ////////////////////////////////////////////////////////////////
87:     // constructors
88: 
89:     /**
90:      * Main Constructor FigObjectFlowState (called from file loading).
91:      */
92:     public FigObjectFlowState() {
93:         setBigPort(new FigRect(OFFSET, OFFSET, WIDTH, HEIGHT,
94:                 Color.cyan, Color.cyan));
95:         cover =
96:             new FigRect(OFFSET, OFFSET, WIDTH, HEIGHT,
97:                     Color.black, Color.white);
98: 
99:         getNameFig().setUnderline(true);
100:         getNameFig().setLineWidth(0);
101: 
102:         state = new FigSingleLineText(OFFSET, OFFSET, WIDTH, 21, true);
103: 
104:         // add Figs to the FigNode in back-to-front order
105:         addFig(getBigPort());
106:         addFig(cover);
107:         addFig(getNameFig());
108:         addFig(state);
109: 
110:         enableSizeChecking(false);
111:         setReadyToEdit(false);
112:         Rectangle r = getBounds();
113:         setBounds(r.x, r.y, r.width, r.height);
114: 
115:         ArgoEventPump.addListener(ArgoEvent.ANY_NOTATION_EVENT, this);
116:     }
117: 
118:     /**
119:      * Constructor FigObjectFlowState that hooks the Fig into
120:      * an existing UML model element.
121:      *
122:      * @param gm ignored!
123:      * @param node owner, i.e. the UML element
124:      */
125:     public FigObjectFlowState(GraphModel gm, Object node) {
126:         this();
127:         setOwner(node);
128:         enableSizeChecking(true);
129:     }
130: 
131:     /**
132:      * @see org.argouml.uml.diagram.ui.FigNodeModelElement#initNotationProviders(java.lang.Object)
133:      */
134:     protected void initNotationProviders(Object own) {
135:         super.initNotationProviders(own);
136:     }
137: 
138:     /**
139:      * @see org.argouml.uml.diagram.ui.FigNodeModelElement#modelChanged(java.beans.PropertyChangeEvent)
140:      */
141:     protected void modelChanged(PropertyChangeEvent mee) {
142:         super.modelChanged(mee);
143:         renderingChanged();
144:         updateListeners(getOwner());
145:     }
146: 
147:     /**
148:      * @see org.argouml.uml.diagram.ui.FigNodeModelElement#updateListeners(java.lang.Object)
149:      */
150:     protected void updateListeners(Object newOwner) {
151:         /* Let's NOT do this: super.updateListeners(newOwner); 
152:          * We only need to listen to its "type". */
153:         Object oldOwner = getOwner();
154:         if (oldOwner != null) {
155:             Model.getPump().removeModelEventListener(this, oldOwner, "type");
156:             // lets remove all registered listeners for the type
157:             Object type = Model.getFacade().getType(oldOwner);
158:             if (Model.getFacade().isAClassifier(type)) {
159:                 if (Model.getFacade().isAClassifierInState(type)) {
160:                     Object classifier = Model.getFacade().getType(type);
161:                     Model.getPump().removeModelEventListener(this, classifier, "name");
162:                     Model.getPump().removeModelEventListener(this, type, "inState");
163:                     Collection states = Model.getFacade().getInStates(type);
164:                     Iterator i = states.iterator();
165:                     while (i.hasNext()) {
166:                         Model.getPump().removeModelEventListener(this, i.next(), 
167:                                 "name");
168:                     }
169:                 } else {
170:                     Model.getPump().removeModelEventListener(this, type, "name");    
171:                 }
172:             }
173:         }
174:         if (newOwner != null) {
175:             Model.getPump().addModelEventListener(this, newOwner, "type");
176:             // register for events from the type
177:             Object type = Model.getFacade().getType(newOwner);
178:             if (Model.getFacade().isAClassifier(type)) {
179:                 if (Model.getFacade().isAClassifierInState(type)) {
180:                     Object classifier = Model.getFacade().getType(type);
181:                     Model.getPump().addModelEventListener(this, classifier, "name");
182:                     Model.getPump().addModelEventListener(this, type, "inState");
183:                     Collection states = Model.getFacade().getInStates(type);
184:                     Iterator i = states.iterator();
185:                     while (i.hasNext()) {
186:                         Model.getPump().addModelEventListener(this, i.next(), 
187:                                 "name");
188:                     }
189:                 } else {
190:                     Model.getPump().addModelEventListener(this, type, "name");    
191:                 }
192:             }
193:         }
194:     }
195: 
196:     /**
197:      * @see org.argouml.uml.diagram.ui.FigNodeModelElement#placeString()
198:      */
199:     public String placeString() {
200:         return "new ObjectFlowState";
201:     }
202: 
203:     /**
204:      * @see java.lang.Object#clone()
205:      */
206:     public Object clone() {
207:         FigObjectFlowState figClone = (FigObjectFlowState) super.clone();
208:         Iterator it = figClone.getFigs().iterator();
209:         figClone.setBigPort((FigRect) it.next());
210:         figClone.cover = (FigRect) it.next();
211:         figClone.setNameFig((FigText) it.next());
212:         figClone.state = (FigText) it.next();
213:         return figClone;
214:     }
215: 
216:     /**
217:      * Get the minimum size.
218:      * The space between the 2 text figs is: PADDING.
219:      * @see org.tigris.gef.presentation.Fig#getMinimumSize()
220:      */
221:     public Dimension getMinimumSize() {
222:         Dimension tempDim = getNameFig().getMinimumSize();
223:         int w = tempDim.width + PADDING * 2;
224:         int h = tempDim.height + PADDING;
225:         tempDim = state.getMinimumSize();
226:         w = Math.max(w, tempDim.width + PADDING * 2);
227:         h = h + PADDING + tempDim.height + PADDING;
228: 
229:         return new Dimension(Math.max(w, WIDTH / 2), Math.max(h, HEIGHT / 2));
230:     }
231: 
232:     /**
233:      * Override setBounds to keep shapes looking right.
234:      * The classifier and state Figs are nicely centered vertically,
235:      * and stretched out over the full width,
236:      * to allow easy selection with the mouse.
237:      * The Fig can only be shrinked to half its original size - so that
238:      * it is not reduceable to a few pixels only.
239:      *
240:      * @see org.tigris.gef.presentation.Fig#setBoundsImpl(int, int, int, int)
241:      */
242:     protected void setBoundsImpl(int x, int y, int w, int h) {
243:         //if (getNameFig() == null) return;
244:         Rectangle oldBounds = getBounds();
245: 
246:         Dimension classDim = getNameFig().getMinimumSize();
247:         Dimension stateDim = state.getMinimumSize();
248:         /* the height of the blank space above and below the text figs: */
249:         int blank = (h - PADDING - classDim.height - stateDim.height) / 2;
250:         getNameFig().setBounds(x + PADDING,
251:                 y + blank,
252:                 w - PADDING * 2,
253:                 classDim.height);
254:         state.setBounds(x + PADDING,
255:                 y + blank + classDim.height + PADDING,
256:                 w - PADDING * 2,
257:                 stateDim.height);
258: 
259:         getBigPort().setBounds(x, y, w, h);
260:         cover.setBounds(x, y, w, h);
261: 
262:         calcBounds();
263:         updateEdges();
264:         firePropChange("bounds", oldBounds, getBounds());
265:     }
266: 
267:     /**
268:      * @see org.argouml.uml.diagram.ui.FigNodeModelElement#renderingChanged()
269:      */
270:     public void renderingChanged() {
271:         updateClassifierText();
272:         updateStateText();
273:         updateBounds();
274:         damage();
275:     }
276: 
277:     /**
278:      * Updates the text of the classifier FigText.
279:      */
280:     private void updateClassifierText() {
281:         if (isReadyToEdit()) {
282:             if (getOwner() == null) {
283:                 return;
