41: /**
42:  * A critic to detect when a class in a deployment-diagram
43:  * is not inside a component
44:  **/
45: public class CrClassWithoutComponent extends CrUML {
46: 
47:     public CrClassWithoutComponent() {
48: 	setHeadline("Classes normally are inside components");
49: 	addSupportedDecision(CrUML.decPATTERNS);
50:     }
51: 
52:     public boolean predicate2(Object dm, Designer dsgr) {
53: 	if (!(dm instanceof UMLDeploymentDiagram)) return NO_PROBLEM;
54: 	UMLDeploymentDiagram dd = (UMLDeploymentDiagram) dm;
55: 	VectorSet offs = computeOffenders(dd);
56: 	if (offs == null) return NO_PROBLEM;
57: 	return PROBLEM_FOUND;
58:     }
59: 
60:     public ToDoItem toDoItem(Object dm, Designer dsgr) {
61: 	UMLDeploymentDiagram dd = (UMLDeploymentDiagram) dm;
62: 	VectorSet offs = computeOffenders(dd);
63: 	return new UMLToDoItem(this, offs, dsgr);
64:     }
65: 
66:     public boolean stillValid(ToDoItem i, Designer dsgr) {
67: 	if (!isActive()) return false;
68: 	VectorSet offs = i.getOffenders();
69: 	UMLDeploymentDiagram dd = (UMLDeploymentDiagram) offs.firstElement();
70: 	//if (!predicate(dm, dsgr)) return false;
71: 	VectorSet newOffs = computeOffenders(dd);
72: 	boolean res = offs.equals(newOffs);
73: 	return res;
74:     }
75: 
76:     /**
77:      * If there are classes that are not inside a component
78:      * the returned vector-set is not null. Then in the vector-set
79:      * are the UMLDeploymentDiagram and all FigClasses with no
80:      * enclosing FigComponent
81:      **/
82:     public VectorSet computeOffenders(UMLDeploymentDiagram dd) { 
83: 	Vector figs = dd.getLayer().getContents();
84: 	VectorSet offs = null;
85: 	int size = figs.size();
86: 	for (int i = 0; i < size; i++) {
87: 	    Object obj = figs.elementAt(i);
88: 	    if (!(obj instanceof FigClass)) continue;
89: 	    FigClass fc = (FigClass) obj;
90: 	    if (fc.getEnclosingFig() == null
91: 		|| (!(ModelFacade.isAComponent(fc.getEnclosingFig().getOwner()))))
92: 	    {
93: 		if (offs == null) {
94: 		    offs = new VectorSet();
95: 		    offs.addElement(dd);
96: 		}
97: 		offs.addElement(fc);
98: 	    }
99: 	}
100: 	return offs;
101:     }  
102: 
103: } /* end class CrClassWithoutComponent.java */
