408:     /**
409:      * Utility function for managing several overlayed models, eg a user
410:      * model to which elements from some profile models is imported when
411:      * needed. This version of the function will only copy objects if
412:      * canCreate is true, but may then also copy other missing elements.
413:      *
414:      * This function may fail and return null eg if the required object
415:      * doesn't exist in the target model and canCreate is false or some
416:      * required object doesn't exist in the target model and cannot be
417:      * copied.
418:      *
419:      * @param elem is some element.
420:      * @param model is the model the returned object shall belong to.
421:      * @param canCreate determines if objects can be copied into model.
422:      * @return An element of the same type and at the same position in the
423:      *  model as elem, or if that would turn out impossible then null.
424:      */
425:     public Object getCorrespondingElement(Object elem,
426:                      Object model, boolean canCreate) {
427:         if (elem == null || model == null || !(elem instanceof MModelElement)) {
428:             throw new NullPointerException();
429:         }
430: 
431:         // Trivial case
432:         if (((MModelElement) elem).getModel() == model) {
433:             return elem;
434:         }
435: 
436:         // Base case
437:         if (elem instanceof MModel) {
438:             return model;
439:         }
440: 
441:         // The cast is actually safe
442:         MNamespace ns =
443:             (MNamespace) getCorrespondingElement(
444:                     ((MModelElement) elem).getNamespace(), model, canCreate);
445:         if (ns == null) {
446:             return null;
447:         }
448: 
449:         Iterator it = ns.getOwnedElements().iterator();
450:         while (it.hasNext()) {
451:             MModelElement e = (MModelElement) it.next();
452:             if (e.getClass() == ((MModelElement) elem).getClass()
453:                 && ((((MModelElement) elem).getName() == null
454:                      && e.getName() == null)
455:                     || (((MModelElement) elem).getName() != null
456:                         && ((MModelElement) elem).getName().equals(
457:                                 e.getName())))) {
458:                 return e;
459:             }
460:         }
461: 
462:         if (!canCreate) {
463:             return null;
464:         }
465: 
466:         return nsmodel.getCopyHelper().copy(elem, ns);
467:     }
