510:     /**
511:      * Checks if a child for some ownershiprelationship (as in a
512:      * namespace A is owned by a namespace B) is allready in the
513:      * ownerhship relation.
514:      *
515:      * @param parent The current leaf for the ownership relation
516:      * @param child The child that should be owned by the parent
517:      * @return true if the child is allready in the ownership relationship
518:      */
519:     public boolean isCyclicOwnership(Object parent, Object child) {
520:         return (getOwnerShipPath(parent).contains(child) || parent == child);
521:     }
