323:     /**
324:      * Get the modelelement a given path below a given root-namespace.
325:      *
326:      * @param path the given path
327:      * @param theRootNamespace the given namespace to start from
328:      * @return the modelelement looked for, or null if not found
329:      */
330:     public Object getElement(Vector path, Object theRootNamespace) {
331:         MModelElement root = (MModelElement) theRootNamespace;
332:         Object name;
333:         int i;
334: 
335:         for (i = 0; i < path.size(); i++) {
336:             if (root == null || !(root instanceof MNamespace)) {
337:                 return null;
338:             }
339: 
340:             name = path.get(i);
341:             Iterator it = ((MNamespace) root).getOwnedElements().iterator();
342:             root = null;
343:             while (it.hasNext()) {
344:                 MModelElement me = (MModelElement) it.next();
345:                 if (i < path.size() - 1
346: 		    && !(me instanceof MNamespace)) {
347: 
348: 		    continue;
349: 
350: 		}
351:                 if (name.equals(me.getName())) {
352:                     root = me;
353:                     break;
354:                 }
355:             }
356:         }
357:         return root;
358:     }
