469:     /**
470:      * Tests if two objects are of the same type, have the same name and the
471:      * same relative position in the model.
472:      *
473:      * Same relative position implies either:
474:      * * their owners correspond to eachother.
475:      * * they are both owned by model objects.
476:      *
477:      * @param obj1 is an object.
478:      * @param obj2 is another object.
479:      * @return true if obj1 corresponds to obj2, false otherwise.
480:      */
481:     public boolean corresponds(Object obj1, Object obj2) {
482:         if (!(obj1 instanceof MModelElement)) {
483:             throw new IllegalArgumentException("obj1");
484:         }
485:         if (!(obj2 instanceof MModelElement)) {
486:             throw new IllegalArgumentException("obj2");
487:         }
488: 
489:         if (obj1 instanceof MModel && obj2 instanceof MModel) {
490:             return true;
491:         }
492:         if (obj1.getClass() != obj2.getClass()) {
493:             return false;
494:         }
495: 
496:         MModelElement modelElement1 = (MModelElement) obj1;
497:         MModelElement modelElement2 = (MModelElement) obj2;
498:         if ((modelElement1.getName() == null
499:              && modelElement2.getName() != null)
500: 	    || (modelElement1.getName() != null
501: 	        && !modelElement1.getName().equals(modelElement2.getName()))) {
502: 
503:             return false;
504: 
505: 	}
506:         return corresponds(modelElement1.getNamespace(),
507:                 	   modelElement2.getNamespace());
508:     }
509: 
510:     /**
511:      * Checks if a child for some ownershiprelationship (as in a
512:      * namespace A is owned by a namespace B) is allready in the
513:      * ownerhship relation.
514:      *
515:      * @param parent The current leaf for the ownership relation
516:      * @param child The child that should be owned by the parent
517:      * @return true if the child is allready in the ownership relationship
518:      */
519:     public boolean isCyclicOwnership(Object parent, Object child) {
520:         return (getOwnerShipPath(parent).contains(child) || parent == child);
521:     }
522: 
523: 
524:     private List getOwnerShipPath(Object elem) {
525:         if (ModelFacade.isABase(elem)) {
526:             List ownershipPath = new ArrayList();
527:             Object parent = ModelFacade.getModelElementContainer(elem);
528:             while (parent != null) {
529:                 ownershipPath.add(parent);
530:                 parent = ModelFacade.getModelElementContainer(parent);
531:             }
532:             return ownershipPath;
533:         }
534:         throw new IllegalArgumentException("Not a base");
535:     }
536: }
