41: /**
42:  * The UMLButtonGroup is the buttongroup behind radio buttons that depict some 
43:  * attribute of a modelelement like visibility.  The radio buttons are controlled
44:  * by the buttongroup. The UMLButtonGroup can be compared to the UMLComboBoxModel
45:  * where the items in the model are the radionbuttons in the buttongroup.
46:  * @since Oct 12, 2002
47:  * @author jaap.branderhorst@xs4all.nl
48:  */
49: public abstract class UMLButtonGroup
50:     extends ButtonGroup
51:     implements UMLUserInterfaceComponent, ActionListener {
52: 
53:     /**
54:      * This map contains the radiobuttons as key and the action that should
55:      * be performed when the button is pressed as value. We don't use 
56:      * the functionallity provided by JDK 1.3 to link an action to a button.
57:      */
58:     private Map _actions = new HashMap();
59:     
60:     private Object _target = null;
61:     
62:     private UMLUserInterfaceContainer _container = null;
63:     
64:     /**
65:      * Constructor for UMLButtonGroup.
66:      */
67:     public UMLButtonGroup(UMLUserInterfaceContainer container) {
68:         super();
69:         setContainer(container);
70:     }
71:     
72:     /**
73:      * Adds a button and an action to the group. When the button is selected,
74:      * the action is fired. If the action is null, no action is done.
75:      * @param button
76:      * @param action
77:      */
78:     public void add(AbstractButton button, Action action) {
79:         _actions.put(button, action);
80:         super.add(button);
81:         button.addActionListener(this);
82:     }
83: 
84:     /**
85:      * When the target changes, the buttonmodel must be updated. Since the 
86:      * API of targetChanged does not have a parameter describing the old and new 
87:      * target, the target is retrieved via the container.
88:      * @see org.argouml.uml.ui.UMLUserInterfaceComponent#targetChanged()
89:      */
90:     public void targetChanged() {
91:         if (getContainer() != null && getContainer().getTarget() != null) {
92:             setTarget(getContainer().getTarget());
93:       
94:         }
95:     }
96: 
97:     /**
98:      * @see org.argouml.uml.ui.UMLUserInterfaceComponent#targetReasserted()
99:      */
100:     public void targetReasserted() {
101:         if (getContainer() != null && getContainer().getTarget() != null) {
102:             setTarget(getContainer().getTarget());
103:       
104:         }
105:     }
106: 
107:     /**
108:      * @see ru.novosoft.uml.MElementListener#propertySet(ru.novosoft.uml.MElementEvent)
109:      */
110:     public void propertySet(MElementEvent e) {
111:         if (e.getSource() == getTarget()) {
112:             buildModel();
113:         }
114:     }
115: 
116:     /**
117:      * Adding roles does not have any influence on the buttongroup (unless you
118:      * want to add a button...)
119:      * @see ru.novosoft.uml.MElementListener#roleAdded(ru.novosoft.uml.MElementEvent)
120:      */
121:     public void roleAdded(MElementEvent e) {
122:     }
123: 
124:     /**
125:      * Removing roles does not have any influence on the buttongroup (unless you
126:      * want to remove a button...)
127:      * @see ru.novosoft.uml.MElementListener#roleRemoved(ru.novosoft.uml.MElementEvent)
128:      */
129:     public void roleRemoved(MElementEvent e) {
130:     }
131: 
132:     /**
133:      * @see ru.novosoft.uml.MElementListener#listRoleItemSet(ru.novosoft.uml.MElementEvent)
134:      */
135:     public void listRoleItemSet(MElementEvent e) {
136:     }
137: 
138:     /**
139:      * Removing elements does not have any influence on a buttongroup
140:      * @see ru.novosoft.uml.MElementListener#removed(ru.novosoft.uml.MElementEvent)
141:      */
142:     public void removed(MElementEvent e) {
143:     }
144: 
145:     /**
146:      * @see ru.novosoft.uml.MElementListener#recovered(ru.novosoft.uml.MElementEvent)
147:      */
148:     public void recovered(MElementEvent e) {
149:     }
150: 
151:     /**
152:      * @see java.awt.event.ActionListener#actionPerformed(java.awt.event.ActionEvent)
153:      */
154:     public void actionPerformed(ActionEvent e) {
155:         Object o = e.getSource();
156:         Action action = (Action) _actions.get(o);
157:         if (action != null) {
158:             // e.setSource(this);
159:             action.actionPerformed(e);
160:         }
161:     }    
162: 
163:     /**
164:      * Returns the container.
165:      * @return UMLUserInterfaceContainer
166:      */
167:     public UMLUserInterfaceContainer getContainer() {
168:         return _container;
169:     }
170: 
171:     /**
172:      * Returns the target. The target is directly asked from the _target attribute
173:      * and not from the _container attribute to make the move to a new targeting
174:      * system as easy as possible.
175:      * @return Object
176:      */
177:     public Object getTarget() {
178:         return _target;
179:     }
180: 
181:     /**
182:      * Sets the container.
183:      * @param container The container to set
184:      */
185:     public void setContainer(UMLUserInterfaceContainer container) {
186:         _container = container;
187:         if (container != null) {
188:             setTarget(container.getTarget());
189:         }
190:     }
191: 
192:     /**
193:      * Sets the target. This method will not be used untill the target does
194:      * not come via the container.
195:      * @param target The target to set
196:      */
197:     public void setTarget(Object target) {
198:         if (target == null || !ModelFacade.isAModelElement(target) || _target == target) return;
199:         _target = target;
200:         buildModel();
201:     }
202:     
203:     /**
204:      * Builds the model. That is: it selects the correct button. The name of this
205:      * method is choosen to be compliant with for example UMLModelElementListModel2
206:      */
207:     abstract public void buildModel();
208: 
209: }
