1031:     /**
1032:      * Try to save the project.
1033:      * @param overwrite if true, then we overwrite without asking
1034:      * @param file the File to save to
1035:      * @return true if successful
1036:      */
1037:     public boolean trySave(boolean overwrite, File file) {
1038:         LOG.info("Saving the project");
1039:         Project project = ProjectManager.getManager().getCurrentProject();
1040:         PersistenceManager pm = PersistenceManager.getInstance();
1041: 
1042:         try {
1043:             if (!PersistenceManager.getInstance()
1044:                     .confirmOverwrite(overwrite, file)) {
1045:                 return false;
1046:             }
1047: 
1048:             String sStatus =
1049:                 MessageFormat.format(Translator.localize(
1050:                     "label.save-project-status-writing"),
1051:                          new Object[] {file});
1052:             this.showStatus (sStatus);
1053: 
1054:             ProjectFilePersister persister =
1055:                     pm.getPersisterFromFileName(file.getName());
1056:             if (persister == null) {
1057:                 throw new IllegalStateException("Filename " + project.getName()
1058:                             + " is not of a known file type");
1059:             }
1060: 
1061:             project.preSave();
1062:             persister.save(project, file);
1063:             project.postSave();
1064: 
1065:             sStatus =
1066:                 MessageFormat.format(Translator.localize(
1067:                     "label.save-project-status-wrote"),
1068:                          new Object[] {project.getURL()});
1069:             showStatus(sStatus);
1070:             LOG.debug ("setting most recent project file to "
1071:                    + file.getCanonicalPath());
1072: 
1073:             /*
1074:              * notification of menu bar
1075:              */
1076:             GenericArgoMenuBar menu = (GenericArgoMenuBar) getJMenuBar();
1077:             menu.addFileSaved(file.getCanonicalPath());
1078: 
1079:             Configuration.setString(Argo.KEY_MOST_RECENT_PROJECT_FILE,
1080:                         file.getCanonicalPath());
1081: 
1082:             return true;
1083:         } catch (FileNotFoundException fnfe) {
1084:             String sMessage =
1085:                 MessageFormat.format(Translator.localize(
1086:                     "optionpane.save-project-file-not-found"),
1087:                          new Object[] {fnfe.getMessage()});
1088: 
1089:             JOptionPane.showMessageDialog(this, sMessage,
1090:                     Translator.localize(
1091:                     "optionpane.save-project-file-not-found-title"),
1092:                           JOptionPane.ERROR_MESSAGE);
1093: 
1094:             LOG.error(sMessage, fnfe);
1095:         } catch (Exception ex) {
1096:             String sMessage =
1097:                 MessageFormat.format(Translator.localize(
1098:                     "optionpane.save-project-general-exception"),
1099:                          new Object[] {ex.getMessage()});
1100: 
1101:             JOptionPane.showMessageDialog(this, sMessage,
1102:                     Translator.localize(
1103:                     "optionpane.save-project-general-exception-title"),
1104:                           JOptionPane.ERROR_MESSAGE);
1105: 
1106:             reportError("save a project.",
1107:                     "Could not save the project "
1108:                     + file.getName()
1109:                     + " some error was found.\n"
1110:                     + "Please report the exception below to the ArgoUML"
1111:                     + "development team at http://argouml.tigris.org.",
1112:                     true, ex);
1113: 
1114:             LOG.error(sMessage, ex);
1115:         }
1116: 
1117:         return false;
1118:     }
