1163:     /**
1164:      * Loads the project file and opens all kinds of error message windows
1165:      * if it doesn't work for some reason. In those cases it preserves
1166:      * the old project.
1167:      *
1168:      * @param file the file to open.
1169:      * @return true if the file was successfully opened
1170:      * @param showUI true if an error message may be shown to the user,
1171:      *               false if run in commandline mode
1172:      */
1173:     public boolean loadProject(File file, boolean showUI) {
1174:         LOG.info("Loading project.");
1175:         PersistenceManager pm = PersistenceManager.getInstance();
1176:         Project oldProject = ProjectManager.getManager().getCurrentProject();
1177:         boolean success = true;
1178: 
1179:         // TODO:
1180:         // This is actually a hack! Some diagram types
1181:         // (like the statechart diagrams) access the current
1182:         // diagram to get some info. This might cause
1183:         // problems if there's another statechart diagram
1184:         // active, so I remove the current project, before
1185:         // loading the new one.
1186: 
1187:         Designer.disableCritiquing();
1188:         Designer.clearCritiquing();
1189:         clearDialogs();
1190:         Project p = null;
1191: 
1192:         if (!(file.canRead())) {
1193:             reportError("File not found " + file + ".", showUI);
1194:             Designer.enableCritiquing();
1195:             success = false;
1196:         } else {
1197:             try {
1198:                 ProjectFilePersister persister =
1199:                     pm.getPersisterFromFileName(file.getName());
1200:                 if (persister == null) {
1201:                     success = false;
1202:                     throw new IllegalStateException("Filename "
1203:                             + file.getName()
1204:                             + " is not of a known file type");
1205:                 }
1206: 
1207:                 DiagramFactory.getInstance().getDiagram().clear();
1208: 
1209:                 p = persister.doLoad(file);
1210: 
1211:                 if (Model.getDiagramInterchangeModel() != null) {
1212:                     Collection diagrams =
1213:                         DiagramFactory.getInstance().getDiagram();
1214:                     Iterator diag = diagrams.iterator();
1215:                     while (diag.hasNext()) {
1216:                         p.addMember(diag.next());
1217:                     }
1218:                     if (!diagrams.isEmpty()) {
1219:                         p.setActiveDiagram((ArgoDiagram) diagrams.iterator()
1220:                                 .next());
1221:                     }
1222:                 }
1223: 
1224:                 ProjectBrowser.getInstance().showStatus(
1225:                     MessageFormat.format(Translator.localize(
1226:                         "label.open-project-status-read"),
1227:                         new Object[] {
1228:                             file.getName(),
1229:                         }));
1230:             } catch (VersionException ex) {
1231:                 success = false;
1232:                 reportError(ex.getMessage(), showUI);
1233:                 p = oldProject;
1234:             } catch (OutOfMemoryError ex) {
1235:                 p = oldProject;
1236:                 LOG.error("Out of memory while loading project", ex);
1237:                 success = false;
1238:                 reportError(
1239:                     "Could not load the project "
1240:                     + file.getName()
1241:                     + " because the JVM ran out of memory.\n"
1242:                     + "Rerun ArgoUML with the heap size increased.",
1243:                     showUI);
1244:             } catch (Exception ex) {
1245:                 LOG.error("Exception while loading project", ex);
1246:                 success = false;
1247:                 reportError(
1248:                     "load a project.",
1249:                     "Could not load the project "
1250:                     + file.getName()
1251:                     + " some error was found.\n"
1252:                     + "Please try loading with the latest version of ArgoUML "
1253:                     + "which you can download from http://argouml.tigris.org\n"
1254:                     + "If you have no further success then please report the "
1255:                     + "exception below.",
1256:                     showUI, ex);
1257:                 p = oldProject;
1258:             } finally {
1259:                 if (!LastLoadInfo.getInstance().getLastLoadStatus()) {
1260:                     p = oldProject;
1261:                     success = false;
1262:                     // TODO: This seems entirely redundant
1263:                     // for now I've made the message more generic, but it
1264:                     // should be removed at a convenient time - tfm
1265:                     reportError(
1266:                             "Problem loading the project "
1267:                             + file.getName()
1268:                             + "\n"
1269:                             + "Error message:\n"
1270:                             + LastLoadInfo.getInstance().getLastLoadMessage()
1271:                             + "\n"
1272:                             + "Some (or all) information may be missing "
1273:                             + "from the project.\n"
1274:                             + "Please report this problem at "
1275:                             + "http://argouml.tigris.org\n",
1276:                             showUI);
1277:                 } else if (oldProject != null) {
1278:                     // if p equals oldProject there was an exception and we do
1279:                     // not have to gc (garbage collect) the old project
1280:                     if (p != null && !p.equals(oldProject)) {
1281:                         //prepare the old project for gc
1282:                         LOG.info("There are " + oldProject.getMembers().size()
1283:                                 + " members in the old project");
1284:                         LOG.info("There are " + p.getMembers().size()
1285:                                 + " members in the new project");
1286:                         ProjectManager.getManager().removeProject(oldProject);
1287:                     }
1288:                 }
1289:                 ProjectManager.getManager().setCurrentProject(p);
1290:                 if (p == null) {
1291:                     LOG.info("The current project is null");
1292:                 } else {
1293:                     LOG.info("There are " + p.getMembers().size()
1294:                             + " members in the current project");
1295:                 }
1296:                 UndoManager.getInstance().empty();
1297:                 Designer.enableCritiquing();
1298:             }
1299:         }
1300:         return success;
1301:     }
