1406:     /**
1407:      * @return the File to save to
1408:      */
1409:     protected File getNewFile() {
1410:         ProjectBrowser pb = ProjectBrowser.getInstance();
1411:         Project p = ProjectManager.getManager().getCurrentProject();
1412: 
1413:         JFileChooser chooser = null;
1414:         URL url = p.getURL();
1415:         if ((url != null) && (url.getFile().length() > 0)) {
1416:             chooser = new JFileChooser(url.getFile());
1417:         }
1418:         if (chooser == null) {
1419:             chooser = new JFileChooser();
1420:         }
1421: 
1422:         if (url != null) {
1423:             chooser.setSelectedFile(new File(url.getFile()));
1424:         }
1425: 
1426:         String sChooserTitle =
1427:         Translator.localize("filechooser.save-as-project");
1428:         chooser.setDialogTitle(sChooserTitle + " " + p.getName());
1429: 
1430:         chooser.setAcceptAllFileFilterUsed(false);
1431:         PersistenceManager.getInstance().setSaveFileChooserFilters(chooser);
1432: 
1433:         String fn = Configuration.getString(
1434:                 PersistenceManager.KEY_PROJECT_NAME_PATH);
1435:         if (fn.length() > 0) {
1436:             fn = PersistenceManager.getInstance().getBaseName(fn);
1437:             chooser.setSelectedFile(new File(fn));
1438:         }
1439: 
1440:         int retval = chooser.showSaveDialog(pb);
1441:         if (retval == JFileChooser.APPROVE_OPTION) {
1442:             File theFile = chooser.getSelectedFile();
1443:             AbstractFilePersister filter =
1444:                 (AbstractFilePersister) chooser.getFileFilter();
1445:             if (theFile != null) {
1446:                 Configuration.setString(
1447:                         PersistenceManager.KEY_PROJECT_NAME_PATH,
1448:                         PersistenceManager.getInstance().getBaseName(
1449:                                 theFile.getPath()));
1450:                 String name = theFile.getName();
1451:                 if (!name.endsWith("." + filter.getExtension())) {
1452:                     theFile =
1453:                         new File(
1454:                             theFile.getParent(),
1455:                             name + "." + filter.getExtension());
1456:                 }
1457:             }
1458:             return theFile;
1459:         }
1460:         return null;
1461:     }
