258:         // Add a listener to focus changes.
259:         // Rationale: reset the undo manager to start a new chain.
260:         KeyboardFocusManager kfm =
261:             KeyboardFocusManager.getCurrentKeyboardFocusManager();
262:         kfm.addPropertyChangeListener(new PropertyChangeListener() {
263:             private Object obj;
264: 
265:             /**
266:              * @see java.beans.PropertyChangeListener#propertyChange(java.beans.PropertyChangeEvent)
267:              */
268:             public void propertyChange(PropertyChangeEvent evt) {
269:                 if ("focusOwner".equals(evt.getPropertyName())
270:                         && (evt.getNewValue() != null)
271:                         /* We get many many events (why?), so let's filter: */
272:                         && (obj != evt.getNewValue())) {
273:                     obj = evt.getNewValue();
274:                     UndoManager.getInstance().startChain();
275:                     /* This next line is ideal for debugging the taborder
276:                      * (focus traversal), see e.g. issue 1849.
277:                      */
278: //                  System.out.println("Focus changed " + obj);
279:                 }
280:             }
281:         });
282:     }
