193:      */
194:     private synchronized void executeAddClassModelEventListener(
195: 	    MElementListener listener,
196: 	    Class modelClass,
197: 	    String eventName) {
198:         // first register the listener for all elements allready in
199:         // the model modelClass = formatClass(modelClass);
200:         Collection col =
201:             ModelManagementHelper.getHelper()
202: 	        .getAllModelElementsOfKind(modelClass);
