231:     /**
232:      * Retrieves the  implementation class belonging to some given class. For 
233:      * example, retrieves ClassImpl.class if the input was Class.class or 
234:      * ClassImpl.class.
235:      * @param inputClass An interface or implementation class from NSUML
236:      * @return The implementation class from NSUML
237:      */
238:     private Class formatClass(Class inputClass) {
239:         String name = inputClass.getName();
240:         if (name.endsWith("Impl")) {
241:             return inputClass;
242:         } else {
243:             try {
244:                 Class returnClass = Class.forName(name + "Impl");
245:                 return returnClass;
246:             } catch (ClassNotFoundException ignorable) {
247:                 // cannot happen
248:             }
249:         }
250:         return null;
