930: /**
931:  * A wrapped object array that contains triples of eventtype,
932:  * eventname, interested listener. I used an Object array for this
933:  * purpose since it performs fast. Copied a lot of the code from
934:  * javax.swing.EventListenerList.
935:  * @author jaap.branderhorst@xs4all.nl
936:  */
937: class EventListenerList {
938:     /**
939:      * A null array to be shared by all empty listener lists.
940:      */
941:     private static final Object[] NULL_ARRAY = new Object[0];
942:     /**
943:      *  The list of EventKey - Listener pairs. It's visibility is default since
944:      * it's used in AbstractUmlModelFactory in a performant but quite awkward
945:      * way from an encapsulation point of view. 
946:      */
947:     private Object[] listenerList = NULL_ARRAY;
948: 
949:     /**
950:      * Returns an array of listeners that are interested in an event
951:      * that is typed by the given EventKey. If the name is null of the
952:      * EventKey, all listeners are returned that have the
953:      * corresponding name filled or null. Same is true for the type.
954:      *
955:      * @param key
956:      * @return An array of listeners that are interested in the event typed by
957:      * the given EventKey
958:      */
959:     public synchronized MElementListener[] getListeners(EventKey key) {
960:         Object[] lList = listenerList;
961:         int n = getListenerCount(lList, key);
962:         MElementListener[] result =
963:             (MElementListener[]) Array.newInstance(MElementListener.class, n);
964:         int j = 0;
965:         // if the event name is not set we should return all listeners
966:         // interested
967:         if (key.getType().intValue() == 0) {
968:             Integer type = key.getType();
969:             for (int i = lList.length - 3; i >= 0; i -= 3) {
970:                 if (type.equals(lList[i])) {
971:                     result[j++] = (MElementListener) lList[i + 2];
972:                 }
973:             }
974:         } else if (key.getName() != null && key.getType() != null) {
975:             Integer type = key.getType();
976:             String name = key.getName();
977:             for (int i = lList.length - 3; i >= 0; i -= 3) {
978:                 if (name.equals(lList[i + 1]) && type.equals(lList[i])) {
979:                     result[j++] = (MElementListener) lList[i + 2];
980:                 }
981:             }
982:         } else {
983:             throw new IllegalArgumentException("Illegal eventkey!");
984:         }
985:         return result;
986:     }
987: 
988:     /**
989:      * Registers the given listeners for the event typed by
990:      * EventKey. If the name is null (of the EventKey), the listener
991:      * is registred for all events that have a type corresponding to
992:      * the type in the given key, no matter what the name of the event
993:      * is. Vice versa for the type.<p>
994:      *
995:      * <strong>A listener that has been added twice will get the
996:      * events for which it registred twice. Be careful with
997:      * registring listeners!</strong>
998:      *
999:      * @param key
1000:      * @param listener
1001:      */
1002:     public synchronized void add(EventKey key, MElementListener listener) {
1003:         if (listener == null || key == null) {
1004:             throw new IllegalArgumentException("Null key or null listener");
1005:         }
1006:         // check if there allready is a listener
1007:         // if (!Arrays.asList(getListeners(key)).contains(listener)) {
1008: 
1009:         if (listenerList == NULL_ARRAY) {
1010:             // if this is the first listener added, 
1011:             // initialize the lists
1012:             listenerList =
1013:                 new Object[] {
1014: 		    key.getType(), key.getName(), listener,
1015: 		};
1016:         } else {
1017:             if (!contains(key, listener)) {
1018:                 // Otherwise copy the array and add the new listener
1019:                 int i = listenerList.length;
1020:                 Object[] tmp = new Object[i + 3];
1021:                 System.arraycopy(listenerList, 0, tmp, 0, i);
1022:                 
1023:                 tmp[i] = key.getType();
1024:                 tmp[i + 1] = key.getName();
1025:                 tmp[i + 2] = listener;            
1026:                 
1027:                 listenerList = tmp;
1028:             }
1029:         }
1030:     }
