1415: /**
1416:  * Class containing the definitions of all events in NSUML. The file
1417:  * eventtree.xml is loaded by this class and converted to a hashmap
1418:  * containing the classes firing events as keys and (hashmaps
1419:  * containing eventnames as keys and eventtypes as values) as values.
1420:  * @author jaap.branderhorst@xs4all.nl
1421:  */
1422: class EventTreeDefinition {
1423:     private static final Logger LOG = 
1424:         Logger.getLogger(EventTreeDefinition.class);
1425:     private static final String FILE_NAME = "org/argouml/eventtree.xml";
1426:     private Map definition = new HashMap();
1427: 
1428:     /**
1429:      * Create an instance of EventTreeDefinition, reading
1430:      * org/argouml/eventtree.xml to obtain the initial configuration.
1431:      */
1432:     public EventTreeDefinition() {
1433:         Document doc = loadDocument();
1434:         synchronized (doc) { // TODO: Why is this synchronized??
1435:             addSourcesFromDocument (doc);
1436:         }
1437:     }
1438: 
1439:     /**
1440:      * <p>Add all event sources described by the given document.
1441:      * The document must match  the pattern given by the following example:
1442:      * 
1443:      * <pre>
1444:      * &lt;eventtree&gt;
1445:      *   &lt;source classname="classname of a model element"&gt;
1446:      *     &lt;eventtype name="event fired by this model element"&gt;
1447:      *       &lt;type&gt;1&lt;/type&gt;
1448:      *     &lt;/eventtype&gt;
1449:      *   &lt;/source&gt;
1450:      * &lt;/eventtree&gt;
1451:      * </pre>
1452:      *
1453:      * The classname is fully qualified.<p>
1454:      * 
1455:      * <p>The type is one of the numbers defined in {@link MElementEvent}. Each 
1456:      * of the elements can be used multiple times.
1457:      * 
1458:      * @param doc the document, the contents of which should be added to this 
1459:      *            event tree definition. This must be preparsed.
1460:      */
1461:     synchronized void addSourcesFromDocument (final Document doc) {
1462:         NodeList sources = doc.getChildNodes().item(0).getChildNodes();
1463:         for (int i = 0; i < sources.getLength(); i++) {
1464:             Element source = (Element) sources.item(i);
1465:             String className = source.getAttribute("classname");
1466:             Class sourceClass = null;
1467:             try {
1468:                 sourceClass = Class.forName(className);
1469:             } catch (ClassNotFoundException e) {
1470:                 LOG.error(e);
1471:             }
1472:             Map nameMap = new HashMap();
1473:             NodeList eventTypes = source.getChildNodes();
1474:             for (int j = 0; j < eventTypes.getLength(); j++) {
1475:                 Element eventType = (Element) eventTypes.item(j);
1476:                 String name = eventType.getAttribute("name");
1477:                 NodeList typeNodes = eventType.getChildNodes();
1478:                 int typeLength = typeNodes.getLength();
1479:                 int[] types = new int[typeLength];
1480:                 for (int k = 0; k < typeLength; k++) {
1481:                     Element typeNode = (Element) typeNodes.item(k);
1482:                     types[k] =
1483:                         Integer.parseInt(
1484:                             typeNode.getFirstChild().getNodeValue());
1485:                 }
1486:                 nameMap.put(name, types);
1487:             }
1488:             // remove case
1489:             nameMap.put(UmlModelEventPump.REMOVE, new int[] {
1490:                 0,
1491:             });
1492:             addSource (sourceClass, nameMap);
1493:         }
1494:     }
1495: 
1496:     /**
1497:      * Add event types for a single source to this event tree.
1498:      * 
1499:      * @param cSource the source class for which to add event types.
1500:      * 
1501:      * @param mpNameMap a map of the event types to add for the source class.
1502:      *                  The keys are Strings indicating the names of events, 
1503:      *                  while the values are int[] which contain all the event
1504:      *                  types the indicated event represents. The specific int 
1505:      *                  values used can be found in {@link MElementEvent}.
1506:      */
1507:     synchronized void addSource (Class cSource, Map mpNameMap) {
1508:         definition.put (cSource, mpNameMap);
1509:     }
1510: 
1511:     /**
1512:      * Returns all eventkeys that an instance of the given modelClass
1513:      * could possibly fire.
1514:      * @param modelClass
1515:      * @return The event keys.
1516:      */
1517:     public synchronized EventKey[] getEventTypes(Class modelClass) {
1518:         modelClass = formatClass(modelClass);
1519:         Map nameMap = (Map) definition.get(modelClass);
1520:         Iterator it = nameMap.keySet().iterator();
1521:         int size = 0;
1522:         while (it.hasNext()) {
1523:             size += ((int[]) nameMap.get(it.next())).length;
1524:         }
1525:         EventKey[] result = new EventKey[size + 1];
1526:         int counter = 0;
1527:         it = nameMap.keySet().iterator();
1528:         while (it.hasNext()) {
1529:             String name = (String) it.next();
1530:             int[] types = (int[]) nameMap.get(name);
1531:             EventKey[] keys = new EventKey[types.length];
1532:             for (int i = 0; i < types.length; i++) {
1533:                 keys[i] = new EventKey(types[i], name);
1534:             }
1535:             System.arraycopy(keys, 0, result, counter, keys.length);
1536:             counter += keys.length;
1537:         }
1538:         // remove event
1539:         System.arraycopy(new EventKey[] {
1540: 	    new EventKey(0, null),
1541: 	},
1542: 			 0,
1543: 			 result,
1544: 			 counter,
1545: 			 1);
1546:         return result;
1547:     }
1548: 
1549:     /**
1550:      * Returns all EventKeys (eventdefinitions) with the given eventName 
1551:      * that the given modelClass can fire.
1552:      * @param modelClass
1553:      * @param name
1554:      * @return All event keys.
1555:      */
1556:     public synchronized EventKey[] getEventTypes(Class modelClass,
1557:                                                  String name) {
1558:         modelClass = formatClass(modelClass);
1559:         Map nameMap = (Map) definition.get(modelClass);
1560:         if (nameMap != null) {
1561:             int[] types = (int[]) nameMap.get(name);
1562:             if (types != null) {
1563: 
1564:                 EventKey[] keys = new EventKey[types.length];
1565:                 for (int i = 0; i < types.length; i++) {
1566:                     keys[i] = new EventKey(types[i], name);
1567:                 }
1568:                 return keys;
1569:             }
1570:         }
1571:         return new EventKey[0];
1572:     }
1573: 
1574:     private synchronized Document loadDocument() {
1575:         DocumentBuilderFactory factory = DocumentBuilderFactory.newInstance();
1576:         try {
1577:             DocumentBuilder builder = factory.newDocumentBuilder();
1578:             Document eventNamesDoc =
1579:                 builder.parse(
1580:                     getClass().getClassLoader().getResourceAsStream(FILE_NAME));
1581:             return eventNamesDoc;
1582:         } catch (ParserConfigurationException e) {
1583:             LOG.fatal(e);
1584:             System.exit(-1);
1585:         } catch (SAXException e) {
1586:             LOG.fatal(e);
1587:             System.exit(-1);
1588:         } catch (IOException e) {
1589:             LOG.fatal(e);
1590:             System.exit(-1);
1591:         }
1592:         return null;
1593:     }
1594: 
1595:     private Class formatClass(Class inputClass) {
1596:         String name = inputClass.getName();
1597:         if (name.endsWith("Impl")) {
1598:             return inputClass;
1599:         } else {
1600:             try {
1601:                 Class returnClass = Class.forName(name + "Impl");
1602:                 return returnClass;
1603:             } catch (ClassNotFoundException ignorable) {
1604:                 // cannot happen
1605:             }
1606:         }
1607:         return null;
1608:     }
1609: }
