165:      * @param modelClass The listener should listen to instances of this class
166:      * @param eventName The name of the event the listener wants to listen 
167:      * too.
168:      */
169:     public void addClassModelEventListener(
170: 					   MElementListener listener,
171: 					   Class modelClass,
172: 					   String eventName) {
173:         // We don't support non-NSUML modeleventlisteners yet, 
174:         // so we return without addition.
175:         if (!MBase.class.isAssignableFrom(modelClass)) {
176:             return;
177:         }
178:         if (listener == null
179:             || modelClass == null
180:             || eventName == null
181:             || eventName.equals("")) {
182:             throw new IllegalArgumentException();
183:         }
184:         executeAddClassModelEventListener(listener, modelClass, eventName);
185:     }
