187:     /**
188:      * Does the actual adding.
189:      *
190:      * @param listener The listener to add
191:      * @param modelClass The listener should listen to instances of this class
192:      * @param eventName The name of the event the listener wants to listen 
193:      */
194:     private synchronized void executeAddClassModelEventListener(
195: 	    MElementListener listener,
196: 	    Class modelClass,
197: 	    String eventName) {
198:         // first register the listener for all elements allready in
199:         // the model modelClass = formatClass(modelClass);
200:         Collection col =
201:             ModelManagementHelper.getHelper()
202: 	        .getAllModelElementsOfKind(modelClass);
203:         
204:         if (col == Collections.EMPTY_LIST) {
205:             col = new ArrayList();
206:         }
207:         
208:         /*
209:         if (modelClass.isAssignableFrom(MModel.class)) {
210:             Object root =
211:                 ProjectManager.getManager().getCurrentProject().getRoot();
212:             if (root != null)
213:                 col.add(root);
214:         }
215:         */
216:         modelClass = formatClass(modelClass);
217:         EventKey[] keys = definition.getEventTypes(modelClass, eventName);
218:         Iterator it = col.iterator();
219:         while (it.hasNext()) {
220:             MBase base = (MBase) it.next();
221:             for (int i = 0; i < keys.length; i++) {
222:                 listenerMap.put(base, keys[i], listener);
223:             }
224:         }
225:         // add the class to the 'interested classes list' so the listener is 
226:         // added on creation of a modelelement
227:         for (int i = 0; i < keys.length; i++) {
228:             classListenerMap.put(modelClass, keys[i], listener);
229:         }
230:     }
231:     /**
232:      * Retrieves the  implementation class belonging to some given class. For 
233:      * example, retrieves ClassImpl.class if the input was Class.class or 
234:      * ClassImpl.class.
235:      * @param inputClass An interface or implementation class from NSUML
236:      * @return The implementation class from NSUML
237:      */
238:     private Class formatClass(Class inputClass) {
239:         String name = inputClass.getName();
240:         if (name.endsWith("Impl")) {
241:             return inputClass;
242:         } else {
243:             try {
244:                 Class returnClass = Class.forName(name + "Impl");
245:                 return returnClass;
246:             } catch (ClassNotFoundException ignorable) {
247:                 // cannot happen
248:             }
249:         }
250:         return null;
251: 
252:     }
