1209:      * @param key
1210:      * @param listener
1211:      */
1212:     public synchronized void put(
1213:         MBase element,
1214:         EventKey key,
1215:         MElementListener listener) {     
1216:         EventListenerList list = (EventListenerList) listenerMap.get(element);
1217:         if (list == null) {
1218:             list = new EventListenerList();
