1229:      */
1230:     public synchronized void remove(
1231:         MBase element,
1232:         EventKey key,
1233:         MElementListener listener) {    
1234:         EventListenerList list = (EventListenerList) listenerMap.get(element);
1235:         if (list != null) {
1236:             list.remove(key, listener);
1237:         }
1238:     }
