194:     private synchronized void executeAddClassModelEventListener(
195: 	    MElementListener listener,
196: 	    Class metaType,
197: 	    String eventName) {
198:         // first register the listener for all elements allready in
199:         // the model modelClass = formatClass(modelClass);
200:         Collection col =
201:             ModelManagementHelper.getHelper()
202: 	        .getAllModelElementsOfKind(metaType);
203:         
204:         if (col == Collections.EMPTY_LIST) {
205:             col = new ArrayList();
206:         }
207:         
208:         /*
209:         if (modelClass.isAssignableFrom(MModel.class)) {
210:             Object root =
211:                 ProjectManager.getManager().getCurrentProject().getRoot();
212:             if (root != null)
213:                 col.add(root);
214:         }
215:         */
216:         metaType = formatClass(metaType);
217:         EventKey[] keys = definition.getEventTypes(metaType, eventName);
218:         Iterator it = col.iterator();
219:         while (it.hasNext()) {
220:             MBase base = (MBase) it.next();
221:             for (int i = 0; i < keys.length; i++) {
222:                 listenerMap.put(base, keys[i], listener);
