127:     if (coi.getClassifiers() != null) { 
128:       String base = ""; 
129:       Collection classifiers = coi.getClassifiers(); 
130:       Iterator it = classifiers.iterator(); 
131:       while (it.hasNext()) { 
132:         Object o = it.next(); 
133:         if (o != null && (o instanceof MClassifier)) { 
134:           MClassifier cls = (MClassifier) o; 
135:           if (cls != null) { 
136:             base = cls.getName(); 
137:           } 
138:         } 
