154:     MComponent classifier = new MComponentImpl();  
155:     String base = _baseField.getText(); 
156:     Collection col = coi.getClassifiers(); 
157:     if ((col != null) && (col.size()>0)) {  
158:       Iterator itcol = col.iterator();  
159:       while (itcol.hasNext()) {  
160:         MClassifier cls = (MClassifier) itcol.next();  
161:         coi.removeClassifier(cls);  
162:       }  
163:     }  
