178:       Vector nodes = model.getNodes(); 
179:       int s = nodes.size(); 
180:       for (int j=0; j<s; j++) { 
181:         MModelElement node = (MModelElement) nodes.elementAt(j); 
182:         if (node != null && (node instanceof MComponentImpl)) { 
183:           MComponent mcomp = (MComponent) node; 
184:           if (mcomp.getNamespace() != coi.getNamespace()) continue;
185:           String comp_name = mcomp.getName(); 
186:           if (comp_name != null && (comp_name.equals(base))) { 
187:             v.addElement(mcomp); 
188:             coi.setClassifiers(v); 
189:             return;  
190:           }       
191:         } 
192:       } 
193:     } 
