42: /**
43:  * The file persister for the diagram members.
44:  * @author Bob Tarling
45:  */
46: class DiagramMemberFilePersister extends MemberFilePersister {
47:     /**
48:      * The tee file for persistence.
49:      */
50:     private static final String PGML_TEE = "/org/argouml/persistence/PGML.tee";
51: 
52:     /*
53:      * @see org.argouml.persistence.MemberFilePersister#load(org.argouml.kernel.Project,
54:      *      java.io.InputStream)
55:      */
56:     public void load(Project project, InputStream inputStream)
57:         throws OpenException {
58: 
59:         // If the model repository doesn't manage a DI model
60:         // then we must generate our Figs by inspecting PGML
61:         try {
62:             // Give the parser a map of model elements
63:             // keyed by their UUID. This is used to allocate
64:             // figs to their owner using the "href" attribute
65:             // in PGML.
66:             PGMLStackParser parser = new PGMLStackParser(project.getUUIDRefs());
67:             Diagram d = parser.readDiagram(inputStream, false);
68:             inputStream.close();
69:             project.addMember(d);
70:         } catch (Exception e) {
71:             if (e instanceof OpenException) {
72:                 throw (OpenException) e;
73:             }
74:             throw new OpenException(e);
75:         }
76:     }
77: 
78:     /*
79:      * @see org.argouml.persistence.MemberFilePersister#getMainTag()
80:      */
81:     public String getMainTag() {
82:         return "pgml";
83:     }
84: 
85:     /**
86:      * Write the diagram to the given writer.
87:      *
88:      * @see org.argouml.persistence.MemberFilePersister#save(
89:      *         org.argouml.kernel.ProjectMember, java.io.Writer,
90:      *         java.lang.Integer)
91:      */
92:     public void save(ProjectMember member, Writer writer, Integer indent)
93:     	throws SaveException {
94: 
95:         ProjectMemberDiagram diagramMember = (ProjectMemberDiagram) member;
96:         OCLExpander expander;
97:         try {
98:             expander =
99:                 new OCLExpander(TemplateReader.getInstance().read(PGML_TEE));
100:         } catch (ExpansionException e) {
101:             throw new SaveException(e);
102:         }
103:         if (indent == null) {
104:             try {
105:                 expander.expand(writer, diagramMember.getDiagram());
106:             } catch (ExpansionException e) {
107:                 throw new SaveException(e);
108:             }
109:         } else {
110:             try {
111:                 File tempFile = File.createTempFile("pgml", null);
112:                 tempFile.deleteOnExit();
113:                 FileWriter w = new FileWriter(tempFile);
114:                 expander.expand(w, diagramMember.getDiagram());
115:                 w.close();
116:                 addXmlFileToWriter(
117:                         (PrintWriter) writer,
118:                         tempFile,
119:                         indent.intValue());
120:             } catch (ExpansionException e) {
121:                 throw new SaveException(e);
122:             } catch (IOException e) {
123:                 throw new SaveException(e);
124:             }
125:         }
126:     }
127: 
128: }
