1028:     Vector sels = ce.getSelectionManager().getFigs();
1029:     java.util.Enumeration enum = sels.elements();
1030:     boolean foundOne = false;
1031:     while (enum.hasMoreElements()) {
1032:       Fig f = (Fig) enum.nextElement();
1033:       Object owner = f.getOwner();
1034:       if (!(owner instanceof MMClass) && !(owner instanceof Interface))
