37: /**
38:  * The action to send an email to an expert.
39:  *
40:  */
41: public class ActionEmailExpert extends ToDoItemAction {
42: 
43:     /**
44:      * The constructor.
45:      */
46:     public ActionEmailExpert() {
47:         super("action.send-email-to-expert", HAS_ICON);
48:     }
49: 
50:     /**
51:      * @see java.awt.event.ActionListener#actionPerformed(java.awt.event.ActionEvent)
52:      */
53:     public void actionPerformed(ActionEvent ae) {
54:         if (OsUtil.isWin32()) {
55:             ToDoItem target = (ToDoItem) getRememberedTarget();
56:             Poster p = target.getPoster();
57:             String to = p.getExpertEmail();
58:             String subject = target.getHeadline().trim();
59:             /* The replaceAll function is only supported in Java 1.4 and up.
60:              * Once we stop supporting Java 1.3,
61:              * we can reintroduce this clean solution!
62:              * subject = subject.replaceAll("\\s", "%20");
63:              */
64:             int i;
65:             while ((i = subject.indexOf(" ")) >= 0) {
66:                 StringBuffer s = new StringBuffer(subject);
67:                 subject = s.replace(i, i + 1, "%20").toString();
68:             }
69: 
70:             Designer dsgr = Designer.theDesigner();
71:             try {
72:                 //MVW: This works under MSWindows only, I guess.
73:                 Runtime.getRuntime().exec(
74:                     "cmd /c start mailto:" + to
75:                     + "?subject=" + subject
76:                     + "&body=" + dsgr);
77:             } catch (Exception ex) {
78:                 /*ignore for now*/
79:             }
80:         } else {
81:             EmailExpertDialog dialog = new EmailExpertDialog();
82:             dialog.setTarget(getRememberedTarget());
83:             dialog.setVisible(true);
84:         }
85:     }
