1116:      */
1117:     public Object buildOperation(Object classifier, Object model,
1118:             Object voidType, Collection propertyChangeListeners) {
1119:         if (!(classifier instanceof Classifier)) {
1120:             throw new IllegalArgumentException("Handle is not a classifier");
1121:         }
1122:         Classifier cls = (Classifier) classifier;
1123:         Operation oper = (Operation) createOperation();
1124:         oper.setName("newOperation");
1125:         oper.getStereotype().clear();
1126:         oper.setOwner(cls);
1127:         oper.setVisibility(VisibilityKindEnum.VK_PUBLIC);
1128:         oper.setAbstract(false);
1129:         oper.setLeaf(false);
1130:         oper.setRoot(false);
1131:         oper.setQuery(false);
1132:         oper.setOwnerScope(ScopeKindEnum.SK_INSTANCE);
1133:         // Jaap Branderhorst 6-4-2003 commented out next line since an
1134:         // operation cannot have two owners. the owner must be the
1135:         // owning classifier which must be set via the setOwner
1136:         // method, not via the namespace.
1137:         //
1138:         // oper.setNamespace(cls);
1139:         oper.setConcurrency(CallConcurrencyKindEnum.CCK_SEQUENTIAL);
1140: 
1141:         Parameter returnParameter = (Parameter) buildParameter(oper, model,
1142:                 voidType, propertyChangeListeners);
1143:         returnParameter.setKind(ParameterDirectionKindEnum.PDK_RETURN);
1144:         returnParameter.setName("return");
1145:         // we set the listeners to the figs here too it would be
1146:         // better to do that in the figs themselves the
1147:         // elementlistener for the parameter is allready set in
1148:         // buildparameter(oper)
1149:         // TODO: this is a huge kludge - is it still used? - tfm - 20051106
1150:         Iterator it = propertyChangeListeners.iterator();
1151:         while (it.hasNext()) {
1152:             PropertyChangeListener listener = (PropertyChangeListener) it.
1153:                     next();
1154:             eventPump.addModelEventListener(listener, oper);
1155:         }
1156:         return oper;
1157:     }
