1189:      *      java.lang.Object, java.lang.Object, java.util.Collection)
1190:      */
1191:     public Object buildParameter(Object o, Object model, Object voidType,
1192:             Collection propertyChangeListeners) {
1193:         if (o instanceof Event) {
1194:             Event event = (Event) o;
1195:             Parameter res = (Parameter) buildParameter((Model) model,
1196:                     (Classifier) voidType);
1197:             res.setKind(ParameterDirectionKindEnum.PDK_IN);
1198:             // removing this next line solves issue 2209
1199:             // res.setNamespace(event.getNamespace());
1200:             event.getParameter().add(res);
1201:             return res;
1202:         } else if (o instanceof BehavioralFeature) {
1203:             BehavioralFeature oper = (BehavioralFeature) o;
1204:             if (oper == null || oper.getOwner() == null) {
1205:                 throw new IllegalArgumentException(
1206:                         "operation is null or does not have an owner");
1207:             }
1208:             Parameter res = (Parameter) buildParameter((Model) model,
1209:                     (Classifier) voidType);
1210:             String name = "arg";
1211:             int counter = 1;
1212: 
1213:             oper.getParameter().add(res);
1214:             Iterator it = oper.getParameter().iterator();
1215:             while (it.hasNext()) {
1216:                 Parameter para = (Parameter) it.next();
1217:                 if ((name + counter).equals(para.getName())) {
1218:                     counter++;
1219:                 }
1220:             }
1221: 
1222:             res.setName(name + counter);
1223: 
1224:             // we set the listeners to the figs here too
1225:             // it would be better to do that in the figs themselves
1226:             it = propertyChangeListeners.iterator();
1227:             while (it.hasNext()) {
1228:                 PropertyChangeListener listener = (PropertyChangeListener) it.
1229:                         next();
1230:                 eventPump.addModelEventListener(listener, res);
1231:             }
1232:             return res;
1233:         } else {
1234:             throw new IllegalArgumentException("Unsupported object type");
1235:         }
1236:     }
