797:         //assoc.setParticipants(cl.getParticipants());
798:         //assoc.setPartitions1(cl.getPartitions1());
799:         //assoc.setPresentations(cl.getPresentations());
800:         //assoc.setStructuralFeatures(cl.getStructuralFeatures());
801: 
802:         buildAssociationEnd(assoc, null, end1, null, null, true, null, null,
