733:     /**
734:      * Builds an association class from a class and two classifiers that should
735:      * be associated. Both ends of the associationclass are navigable.
736:      * <p>
737:      * 
738:      * @param cl
739:      *            the class
740:      * @param end1
741:      *            the first classifier
742:      * @param end2
743:      *            the second classifier
744:      * @return MAssociationClass
745:      */
746:     private AssociationClass buildAssociationClass(UmlClass cl,
747:             Classifier end1, Classifier end2) {
748:         if (end1 == null || end2 == null || cl == null) {
749:             throw new IllegalArgumentException(
750:                     "one of the arguments was null");
751:         }
752:         AssociationClass assoc = (AssociationClass) createAssociationClass();
753:         
754:         // Copy attributes from our template class
755:         assoc.setNamespace(cl.getNamespace());
756:         assoc.setName(cl.getName());
757:         assoc.setAbstract(cl.isAbstract());
758:         assoc.setActive(cl.isActive());
759:         assoc.setLeaf(cl.isLeaf());
760:         assoc.setRoot(cl.isRoot());
761:         assoc.setSpecification(cl.isSpecification());
762:         assoc.getStereotype().addAll(cl.getStereotype());
763:         assoc.setVisibility(cl.getVisibility());
764:         
765:         /*
766:          * Normally we will be called with a newly created default class as our
767:          * template so only the above attribute copying is needed. The rest of
768:          * this is just in case someone wants it to be more general in the
769:          * future.
770:          * TODO: This is untested and just copies what was done in the NSUML
771:          * implementation (which is also untested for the same reason as above).
772:          */
773:         assoc.getClientDependency().addAll(cl.getClientDependency());
774:         assoc.getComment().addAll(cl.getComment());
775:         assoc.getConstraint().addAll(cl.getConstraint());        
776:         assoc.getFeature().addAll(cl.getFeature());
777:         assoc.getGeneralization().addAll(cl.getGeneralization());
778:         assoc.getPowertypeRange().addAll(cl.getPowertypeRange());
779:         assoc.getSourceFlow().addAll(cl.getSourceFlow());
780:         assoc.getTaggedValue().addAll(cl.getTaggedValue());
781:         assoc.getTargetFlow().addAll(cl.getTargetFlow());
782:         assoc.getTemplateParameter().addAll(cl.getTemplateParameter());
783: 
784:         // Other things copied in the NSUML implementation 
785:         // which have no direct analog here
786:         
787:         //assoc.setAssociationEnds(facade.getAssociationEnds(cl));
788:         //assoc.setClassifierRoles(cl.getClassifierRole());
789:         //assoc.setClassifierRoles1(cl.getClassifierRoles1());
790:         //assoc.setClassifiersInState(cl.getClassifiersInState());
791:         //assoc.setCollaborations(cl.getCollaborations());
792:         //assoc.setCollaborations1(cl.getCollaborations1());
793:         //assoc.setCreateActions(cl.getCreateActions());
794:         //assoc.setExtensions(cl.getExtensions());
795:         //assoc.setInstances(cl.getInstances());
796:         //assoc.setObjectFlowStates(cl.getObjectFlowStates());
797:         //assoc.setParticipants(cl.getParticipants());
798:         //assoc.setPartitions1(cl.getPartitions1());
799:         //assoc.setPresentations(cl.getPresentations());
800:         //assoc.setStructuralFeatures(cl.getStructuralFeatures());
801: 
802:         buildAssociationEnd(assoc, null, end1, null, null, true, null, null,
803:                 null, null, null);
804:         buildAssociationEnd(assoc, null, end2, null, null, true, null, null,
805:                 null, null, null);
806:         return assoc;
807:     }
