451:     /**
452:      * Builds a default binary association with two default association ends.
453:      * 
454:      * @param c1
455:      *            The first classifier to connect to
456:      * @param nav1
457:      *            The navigability of the Associaton end
458:      * @param agg1
459:      *            The aggregation type of the second Associaton end
460:      * @param c2
461:      *            The second classifier to connect to
462:      * @param nav2
463:      *            The navigability of the second Associaton end
464:      * @param agg2
465:      *            The aggregation type of the second Associaton end
466:      * @return MAssociation
467:      * @throws IllegalArgumentException
468:      *             if either Classifier is null
469:      */
470:     private UmlAssociation buildAssociation(Classifier c1, boolean nav1,
471:             AggregationKind agg1, Classifier c2, boolean nav2,
472:             AggregationKind agg2) {
473:         if (c1 == null || c2 == null) {
474:             throw new IllegalArgumentException("one of "
475:                     + "the classifiers to be " + "connected is null");
476:         }
477:         Namespace ns1 = c1.getNamespace();
478:         Namespace ns2 = c2.getNamespace();
479:         if (ns1 == null || ns2 == null) {
480:             throw new IllegalArgumentException("one of "
481:                     + "the classifiers does not " + "belong to a namespace");
482:         }
483:         UmlAssociation assoc = (UmlAssociation) createAssociation();
484:         assoc.setName("");
485:         assoc.setNamespace((Namespace) nsmodel.getCoreHelper().
486:                 getFirstSharedNamespace(ns1, ns2));
487:         buildAssociationEnd(assoc, null, c1, null, null,
488:                 nav1, null, agg1, null, null, null);
489:         buildAssociationEnd(assoc, null, c2, null, null, 
490:                 nav2, null, agg2, null, null, null);
491:         return assoc;
492:     }
493: 
494:     /**
495:      * @see org.argouml.model.CoreFactory#buildAssociation(java.lang.Object,
496:      *      java.lang.Object, java.lang.Object, java.lang.Object,
497:      *      java.lang.Boolean)
498:      */
499:     public Object buildAssociation(Object fromClassifier,
500:             Object aggregationKind1, Object toClassifier,
501:             Object aggregationKind2, Boolean unidirectional) {
502:         if (fromClassifier == null || toClassifier == null) {
503:             throw new IllegalArgumentException("one of "
504:                     + "the classifiers to be " + "connected is null");
505:         }
506:         Classifier from = (Classifier) fromClassifier;
507:         Classifier to = (Classifier) toClassifier;
508:         AggregationKind agg1 = (AggregationKind) aggregationKind1;
509:         AggregationKind agg2 = (AggregationKind) aggregationKind2;
510: 
511:         Namespace ns1 = from.getNamespace();
512:         Namespace ns2 = to.getNamespace();
513:         if (ns1 == null || ns2 == null) {
514:             throw new IllegalArgumentException("one of "
515:                     + "the classifiers does not " + "belong to a namespace");
516:         }
517:         UmlAssociation assoc = (UmlAssociation) createAssociation();
518:         assoc.setName("");
519:         assoc.setNamespace((Namespace) nsmodel.getCoreHelper().
520:                 getFirstSharedNamespace(ns1, ns2));
521: 
522:         boolean nav1 = true;
523:         boolean nav2 = true;
524: 
525:         if (from instanceof Interface) {
526:             nav2 = false;
527:             agg2 = agg1;
528:             agg1 = null;
529:         } else if (to instanceof Interface) {
530:             nav1 = false;
531:         } else {
532:             nav1 = !Boolean.TRUE.equals(unidirectional);
533:             nav2 = true;
534:         }
535: 
536:         buildAssociationEnd(assoc, null, from, null, null, nav1, null, agg1,
537:                 null, null, null);
538:         buildAssociationEnd(assoc, null, to, null, null, nav2, null, agg2,
539:                 null, null, null);
540:         return assoc;
541:     }
