694:     /**
695:      * Get the maximum value of a multiplicity
696:      * 
697:      * @param m
698:      *            the Multiplicity
699:      * @return upper range
700:      */
701:     private int getMaxUpper(Multiplicity m) {
702:         int max = 0;
703:         for (Iterator i = m.getRange().iterator(); i.hasNext();) {
704:             int value = ((MultiplicityRange) i.next()).getUpper();
705:             if (value > max) {
706:                 max = value;
707:             }
708:         }
709:         return 0;
710:     }
