1242:     public Object buildRealization(Object clnt, Object spplr, Object model) {
1243:         ModelElement client = (ModelElement) clnt;
1244:         ModelElement supplier = (ModelElement) spplr;
1245:         if (client == null || supplier == null || client.getNamespace() == null
1246:                 || supplier.getNamespace() == null) {
1247:             throw new IllegalArgumentException("faulty arguments.");
1248:         }
1249:         Object realization = createAbstraction();
1250:         Namespace nsc = client.getNamespace();
1251:         Namespace nss = supplier.getNamespace();
1252:         Namespace ns = null;
1253:         if (nsc.equals(nss)) {
1254:             ns = nsc;
1255:         } else {
1256:             ns = (Namespace) model;
1257:         }
1258:         nsmodel.getExtensionMechanismsFactory().buildStereotype(realization,
1259:                 "realize", ns);
1260:         nsmodel.getCoreHelper().addClientDependency(client, realization);
1261:         nsmodel.getCoreHelper().addSupplierDependency(supplier, realization);
1262:         return realization;
1263:     }
