1060:     /**
1061:      * @see org.argouml.model.CoreFactory#buildGeneralization(java.lang.Object,
1062:      *      java.lang.Object)
1063:      */
1064:     public Object buildGeneralization(Object child1, Object parent1) {
1065:         if ((!(child1 instanceof GeneralizableElement) 
1066:                 || !(parent1 instanceof GeneralizableElement))
1067:                 && child1 != parent1) {
1068:             throw new IllegalArgumentException(
1069:                     "Both items must be different generalizable elements");
1070:         }
1071: 
1072:         GeneralizableElement child = (GeneralizableElement) child1;
1073:         GeneralizableElement parent = (GeneralizableElement) parent1;
1074: 
1075:         // Check that the two elements aren't already linked the opposite way
1076:         Iterator it = parent.getGeneralization().iterator();
1077:         while (it.hasNext()) {
1078:             Generalization gen = (Generalization) it.next();
1079:             if (gen.getParent().equals(child)) {
1080:                 throw new IllegalArgumentException("Generalization exists" 
1081:                         + " in opposite direction");
1082:             }
1083:         }
1084: 
1085:         if (parent.getNamespace() == null) {
1086:             throw new IllegalArgumentException("parent has no namespace");
1087:         }
1088:         if (parent.isLeaf()) {
1089:             throw new IllegalArgumentException("parent is leaf");
1090:         }
1091:         if (child.isRoot()) {
1092:             throw new IllegalArgumentException("child is root");
1093:         }
1094: 
1095:         Generalization gen = (Generalization) createGeneralization();
1096:         gen.setParent(parent);
1097:         gen.setChild(child);
1098:         gen.setNamespace(parent.getNamespace());
1099:         return gen;
1100:     }
