722: 	Model.getCoreHelper().setAbstract(mOperation,
723: 				(modifiers & JavaRecognizer.ACC_ABSTRACT) > 0);
724: 	Model.getCoreHelper().setLeaf(mOperation,
725: 			    (modifiers & JavaRecognizer.ACC_FINAL) > 0);
