865:     /**
866:      * Called from the parser when an attribute is found.
867:      *
868:      * @param modifiers A sequence of attribute modifiers.
869:      * @param typeSpec The attribute's type.
870:      * @param name The name of the attribute.
871:      * @param initializer The initial value of the attribute.
872:      * @param javadoc The javadoc comment. null or "" if no comment available.
873:      */
874:     public void addAttribute (short modifiers,
875:                               String typeSpec,
876:                               String name,
877:                               String initializer,
878:                               String javadoc) {
879: 	String multiplicity = null;
880: 
881: 	if (!arraysAsDatatype && typeSpec.indexOf('[') != -1) {
882: 	    typeSpec = typeSpec.substring(0, typeSpec.indexOf('['));
883: 	    multiplicity = "1_N";
884: 	} else {
885: 	    multiplicity = "1_1";
886: 	}
887: 
888: 	// the attribute type
889: 	Object mClassifier = null;
890: 	try {
891: 	    // get the attribute type
892: 	    mClassifier = getContext(typeSpec).get(getClassifierName(typeSpec));
893: 	} catch (ClassifierNotFoundException e) {
894: 	    // Currently if a classifier cannot be found in the
895: 	    // model/classpath then information will be lost from
896: 	    // source files, because the classifier cannot be
897: 	    // created on the fly.
898: 	    LOG.warn("Modeller.java: a classifier that was in the source "
899: 		     + "file could not be generated in the model "
900: 		     + "(for generating an attribute)- information lost",
901: 		     e);
902: 
903: 	    // if we can't find the attribute type then
904: 	    // we can't add the attribute.
905: 	    return;
906: 	}
907: 
908: 	// if we want to create a UML attribute:
909: 	if (noAssociations
910: 	    || Model.getFacade().isADataType(mClassifier)
911: 	    || (Model.getFacade().getNamespace(mClassifier)
912: 		== getPackage("java.lang"))) {
913: 
914:             Object mAttribute = parseState.getAttribute(name);
915:             if (mAttribute == null) {
916:                 mAttribute = buildAttribute(parseState.getClassifier(), name);
917:             }            
918:             parseState.feature(mAttribute);
919: 
920:             setOwnerScope(mAttribute, modifiers);
921:             setVisibility(mAttribute, modifiers);
922:             Model.getCoreHelper().setMultiplicity(mAttribute, multiplicity);
923: 
924:             if (Model.getFacade().isAClassifier(mClassifier)) {
925:                 Model.getCoreHelper().setType(mAttribute, mClassifier);
926:             } else {
927:                 // the type resolution failed to find a valid classifier.
928:                 LOG.warn("Modeller.java: a valid type for a parameter "
929: 			 + "could not be resolved:\n "
930: 			 + "In file: " + fileName + ", for attribute: "
931: 			 + Model.getFacade().getName(mAttribute));
932:             }
933: 
934:             // Set the initial value for the attribute.
935:             if (initializer != null) {
936: 
937:                 // we must remove line endings and tabs from the intializer
938:                 // strings, otherwise the classes will display horribly.
939:                 initializer = initializer.replace('\n', ' ');
940:                 initializer = initializer.replace('\t', ' ');
941:                 
942: 		Object newInitialValue =
943: 		    Model.getDataTypesFactory()
944: 		        .createExpression("Java",
945: 					  initializer);
946:                 Model.getCoreHelper().setInitialValue(
947:                         mAttribute,
948:                         newInitialValue);
949:             }
950: 
951:             if ((modifiers & JavaRecognizer.ACC_FINAL) > 0) {
952:                 Model.getCoreHelper().setChangeable(mAttribute, false);
953:             } else if (!Model.getFacade().isChangeable(mAttribute)) {
954:                 Model.getCoreHelper().setChangeable(mAttribute, true);
955:             }
956:             addDocumentationTag(mAttribute, javadoc);
957:         }
958:         // we want to create a UML association from the java attribute
959:         else {
960: 
961:             Object mAssociationEnd = getAssociationEnd(name, mClassifier);
962:             setTargetScope(mAssociationEnd, modifiers);
963:             setVisibility(mAssociationEnd, modifiers);
964:             Model.getCoreHelper().setMultiplicity(
965:                     mAssociationEnd,
966:                     multiplicity);
967:             Model.getCoreHelper().setType(mAssociationEnd, mClassifier);
968:             Model.getCoreHelper().setName(mAssociationEnd, name);
969:             if ((modifiers & JavaRecognizer.ACC_FINAL) > 0) {
970:                 Model.getCoreHelper().setChangeable(mAssociationEnd, false);
971:             }
972:             Model.getCoreHelper().setNavigable(mAssociationEnd, true);
973:             addDocumentationTag(mAssociationEnd, javadoc);
974: 	}
975:     }
