1531:     /**
1532:      * Add the javadocs as a tagged value 'documentation' to the model
1533:      * element. All comment delimiters are removed prior to adding the
1534:      * comment.
1535:      *
1536:      * Added 2001-10-05 STEFFEN ZSCHALER.
1537:      *
1538:      * @param modelElement the model element to which to add the documentation
1539:      * @param sJavaDocs the documentation comment to add ("" or null
1540:      * if no java docs)
1541:      */
1542:     private void addDocumentationTag(Object modelElement, String sJavaDocs) {
1543: 	if ((sJavaDocs != null)
1544: 	    && (sJavaDocs.trim().length() >= 5)) {
1545: 	    StringBuffer sbPureDocs = new StringBuffer(80);
1546: 	    String sCurrentTagName = null;
1547: 	    String sCurrentTagData = null;
1548: 	    int nStartPos = 3; // skip the leading /**
1549: 	    boolean fHadAsterisk = true;
1550: 
1551: 	    while (nStartPos < sJavaDocs.length()) {
1552: 		switch (sJavaDocs.charAt (nStartPos)) {
1553: 		case '*':
1554: 		    fHadAsterisk = true;
1555: 		    nStartPos++;
1556: 		    break;
1557: 		case ' ':   // all white space, hope I didn't miss any ;-)
1558: 		case '\t':
1559: 		    // ignore white space before the first asterisk
1560: 		    if (!fHadAsterisk) {
1561: 			nStartPos++;
1562: 			break;
1563: 		    }
1564: 		default:
1565: 		    // normal comment text or standard tag
1566: 		    // check ahead for tag
1567: 		    int j = nStartPos;
1568: 		    while ((j < sJavaDocs.length())
1569: 			   && ((sJavaDocs.charAt (j) == ' ')
1570: 			       || (sJavaDocs.charAt (j) == '\t'))) {
1571: 			j++;
1572: 		    }
1573: 		    if (j < sJavaDocs.length()) {
1574: 			if (sJavaDocs.charAt (j) == '@') {
1575: 			    // if the last javadoc is on the last line
1576: 			    // no new line will be found, causing an
1577: 			    // indexoutofboundexception.
1578: 			    int lineEndPos = 0;
1579: 			    if (sJavaDocs.indexOf('\n', j) < 0) {
1580: 				lineEndPos = sJavaDocs.length() - 2;
1581: 			    } else {
1582: 				lineEndPos = sJavaDocs.indexOf('\n', j) + 1;
1583: 			    }
1584: 			    sbPureDocs.append(sJavaDocs.substring(j,
1585: 								  lineEndPos));
1586: 			    // start standard tag potentially add
1587: 			    // current tag to set of tagged values...
1588: 			    if (sCurrentTagName != null) {
1589: 				addJavadocTagContents (modelElement,
1590: 						       sCurrentTagName,
1591: 						       sCurrentTagData);
1592: 			    }
1593: 			    // open new tag
1594: 			    int nTemp = sJavaDocs.indexOf (' ', j + 1);
1595: 			    if (nTemp == -1) {
1596: 				nTemp = sJavaDocs.length() - 1;
1597: 			    }
1598: 			    sCurrentTagName = sJavaDocs.substring(j + 1,
1599: 								  nTemp);
1600: 			    int nTemp1 = sJavaDocs.indexOf ('\n', ++nTemp);
1601: 			    if (nTemp1 == -1) {
1602: 				nTemp1 = sJavaDocs.length();
1603: 			    } else {
1604: 				nTemp1++;
1605: 			    }
1606: 			    sCurrentTagData =
1607: 				sJavaDocs.substring (nTemp, nTemp1);
1608: 			    nStartPos = nTemp1;
1609: 			} else {
1610: 			    // continue standard tag or comment text
1611: 			    int nTemp = sJavaDocs.indexOf ('\n', nStartPos);
1612: 			    if (nTemp == -1) {
1613: 				nTemp = sJavaDocs.length();
1614: 			    } else {
1615: 				nTemp++;
1616: 			    }
1617: 			    if (sCurrentTagName != null) {
1618: 				sbPureDocs.append(sJavaDocs.substring(nStartPos,
1619: 								      nTemp));
1620: 				sCurrentTagData +=
1621: 				    " "
1622: 				    + sJavaDocs.substring (nStartPos, nTemp);
1623: 			    } else {
1624: 				sbPureDocs.append(sJavaDocs.substring(nStartPos,
1625: 								      nTemp));
1626: 			    }
1627: 			    nStartPos = nTemp;
1628: 			}
1629: 		    }
1630: 		    fHadAsterisk = false;
1631: 		}
1632: 	    }
1633:             sJavaDocs = sbPureDocs.toString();
1634:             
1635:             /*
1636:              * After this, we have the documentation text, but there's still a
1637:              * trailing '/' left, either at the end of the actual comment text
1638:              * or at the end of the last tag.
1639:              */
1640:             sJavaDocs = removeTrailingSlash(sJavaDocs);
1641:             
1642:             // handle last tag, if any (strip trailing slash there too)
1643: 	    if (sCurrentTagName != null) {
1644: 		sCurrentTagData = removeTrailingSlash(sCurrentTagData);
1645: 		addJavadocTagContents (modelElement, sCurrentTagName,
1646: 				       sCurrentTagData);
1647: 	    }
1648: 
1649: 	    // Now store documentation text in a tagged value
1650: 	    Model.getExtensionMechanismsHelper().addTaggedValue(
1651:                     modelElement,
1652:                     Model.getExtensionMechanismsFactory().buildTaggedValue(
1653:                             "documentation", sJavaDocs));
1654: 	    addStereotypes(modelElement);
1655:         }
1656:     }
