1659:     /*
1660:      * Remove a trailing slash, including the entire line if it's the only thing
1661:      * on the line. 
1662:      */
1663:     private String removeTrailingSlash(String s) {
1664:         if (s.endsWith("\n/")) {
1665:             return s.substring(0, s.length() - 2);
1666:         } else  if (s.endsWith("/")) {
1667:             return s.substring(0, s.length() - 1);
1668:         } else {
1669:             return s;
1670:         }
1671:     }
