401:     /**
402:      * Called from the parser when a class declaration is found.
403:      *
404:      * @param name The name of the class.
405:      * @param modifiers A sequence of class modifiers.
406:      * @param superclassName Zero or one string with the name of the
407:      *        superclass. Can be fully qualified or
408:      *        just a simple class name.
409:      * @param interfaces Zero or more strings with the names of implemented
410:      *        interfaces. Can be fully qualified or just a
411:      *        simple interface name.
412:      * @param javadoc The javadoc comment. null or "" if no comment available.
413:      */
414:     public void addClass(String name,
415:                          short modifiers,
416:                          String superclassName,
417:                          Vector interfaces,
418:                          String javadoc) {
419:         Object mClass =
420: 	    addClassifier(Model.getCoreFactory().createClass(),
421: 			  name, modifiers, javadoc);
422: 
423:         Model.getCoreHelper().setAbstract(
424:                 mClass,
425:                 (modifiers & JavaRecognizer.ACC_ABSTRACT) > 0);
426:         Model.getCoreHelper().setLeaf(
427:                 mClass,
428:                 (modifiers & JavaRecognizer.ACC_FINAL) > 0);
429:         Model.getCoreHelper().setRoot(mClass, false);
430: 
431:         // only do generalizations and realizations on the 2nd pass.
432:         Object level = this.getAttribute("level");
433:         if (level != null) {
434:             if (level.equals(new Integer(0))) {
435:                 return;
436:             }
437:         }
438: 
439: 	if (superclassName != null) {
440: 	    try {
441: 		Object parentClass =
442: 		    getContext(superclassName)
443: 		        .get(getClassifierName(superclassName));
444: 		getGeneralization(currentPackage, parentClass, mClass);
445: 	    } catch (ClassifierNotFoundException e) {
446: 		// Currently if a classifier cannot be found in the
447: 		// model/classpath then information will be lost from
448: 		// source files, because the classifier cannot be
449: 		// created on the fly.
450: 		LOG.warn("Modeller.java: a classifier that was in the source"
451: 			 + " file could not be generated in the model "
452: 			 + "(to generate a generalization)- information lost",
453:                          e);
454: 	    }
455: 	}
456: 
457: 	if (interfaces != null) {
458: 	    for (Iterator i = interfaces.iterator(); i.hasNext();) {
459: 		String interfaceName = (String) i.next();
460: 		try {
461: 		    Object mInterface =
462: 			getContext(interfaceName)
463: 			    .getInterface(getClassifierName(interfaceName));
464: 		    Object mAbstraction =
465: 			getAbstraction(mInterface, mClass);
466: 		    if (Model.getFacade().getSuppliers(mAbstraction).size()
467: 		            == 0) {
468: 			Model.getCoreHelper().addSupplier(
469: 			        mAbstraction,
470: 			        mInterface);
471: 			Model.getCoreHelper().addClient(mAbstraction, mClass);
472: 		    }
473: 		    Model.getCoreHelper().setNamespace(
474: 		            mAbstraction,
475: 		            currentPackage);
476: 		    Model.getCoreHelper().addStereotype(
477: 		            mAbstraction,
478: 		            getStereotype("realize"));
479: 		} catch (ClassifierNotFoundException e) {
480: 		    // Currently if a classifier cannot be found in the
481: 		    // model/classpath then information will be lost from
482: 		    // source files, because the classifier cannot be
483: 		    // created on the fly.
484: 		    LOG.warn("Modeller.java: a classifier that was in "
485: 			     + "the source file could not be generated "
486: 			     + "in the model "
487: 			     + "(to generate a abstraction)- information lost",
488: 			     e);
489: 		}
490: 	    }
491: 	}
492:     }
