1686:                 while (st.hasMoreTokens()) {
1687:                     Model.getCoreHelper().addStereotype(modelElement,
1688:                             getStereotype(st.nextToken().trim()));
1689:                 }
1690:             }
1691:             Model.getExtensionMechanismsHelper().removeTaggedValue(
1692:                     modelElement, tv);
1693:         }
1694:     }
