1047:        @param name The name of the package.
1048:        @return The package found or created.
1049:     */
1050:     private Object getPackage(String name) {
1051: 	Object mPackage = searchPackageInModel(name);
1052: 	if (mPackage == null) {
1053: 	    mPackage =
1054: 		Model.getModelManagementFactory()
1055: 		    .buildPackage(getRelativePackageName(name), name);
1056: 	    Model.getCoreHelper().setNamespace(mPackage, model);
1057: 
1058: 	    // Find the owner for this package.
1059: 	    if ("".equals(getPackageName(name))) {
1060: 		Model.getCoreHelper().addOwnedElement(model, mPackage);
