53: /**
54:  * Generator2 subclass to generate C++ source code that is used in ArgoUML GUI
55:  * and text fields when the cpp notation is selected by the user. It also
56:  * implements FileGenerator and makes it possible for the user to generate
57:  * the source code files for model elements of his choice.
58:  */
59: public class GeneratorCpp extends Generator2
60:     implements PluggableNotation, FileGenerator {
61: 
62:     /**
63:      * The logger.
64:      */
65:     private static final Logger LOG = Logger.getLogger(GeneratorCpp.class);
66: 
67:     private boolean verboseDocs = false;
68:     private boolean lfBeforeCurly = false;
69:     /**
70:      * TODO: make it configurable.
71:      */
72:     private static final boolean VERBOSE_DOCS = false;
73: 
74:     private static final String ANY_RANGE = "0..*";
