86:     /**
87:      * Store extra include dependencies which are generated during
88:      * generation of multiplicity to get needed container type.
89:      *
90:      * @author Achim Spangler
91:      * @since 2002-12-12
92:      */
93:     private String extraIncludes = "";
94: 
95:     /**
96:      * System newline separator.
97:      */
98:     private static final String LINE_SEPARATOR =
99:         System.getProperty("line.separator");
100: 
101: 
102:     /**
103:      * C++ doesn't place visibility information for each class member
104:      * --> sort items during generation and store visibility state
105:      * of lastly generated member in central class variable, so that
106:      * the appropriate lines: "public:\n", "protected:\n", "private:\n"
107:      * can be created.
108:      *
109:      * @author Achim Spangler
110:      * @since 2002-11-28
111:      */
112:     private static final int PUBLIC_PART = 0;
113:     private static final int PROTECTED_PART = 1;
114:     private static final int PRIVATE_PART = 2;
115: 
116:     private static final int[] ALL_PARTS = {
117:         PUBLIC_PART,
118:         PROTECTED_PART,
119:         PRIVATE_PART,
120:     };
121: 
122:     private static final String[] PART_NAME = {
123:         "public", "protected", "private"
124:     };
125: 
126:     /**
127:      * C++ uses two files for each class: header (.h) with class definition
128:      * and source (.cpp) with methods implementation
129:      * --> two generation passes are needed.
130:      *
131:      * @author Achim Spangler
132:      * @since 2002-11-28
133:      */
134:     private static final int NONE_PASS = 1;
135:     private static final int HEADER_PASS = 2;
136:     private static final int SOURCE_PASS = 3;
137:     private static int generatorPass = NONE_PASS;
138: 
139:     /**
140:      * use Tag generation for generation of: doccomment, simple tags of
141:      * tags which are not used for doccomment or simple tags for all.
142:      *
143:      * @author Achim Spangler
144:      * @since 2002-12-05
145:      */
146:     private static final int DOC_COMMENT_TAGS = 1;
147:     private static final int ALL_BUT_DOC_TAGS = 2;
148:     private static final int ALL_TAGS = 3;
149: 
150:     /**
151:      * C++ developers need to specify for parameters whether they are
152:      * pointers or references (especially for class-types)
153:      * -> a general check function must get the searched tag.
154:      *
155:      * @author Achim Spangler
156:      * @since 2002-12-06
157:      */
158:     private static final int NORMAL_MOD = 0;
159:     private static final int REFERENCE_MOD = 1;
160:     private static final int POINTER_MOD = 2;
161: 
162:     private static final GeneratorCpp SINGLETON = new GeneratorCpp();
163: 
164:     /**
165:      * Prefix for names in the std namespace. Defaults to "std::",
166:      * but could be "" if a "using namsepace std;" directive is used.  
167:      */
168:     private String stdPrefix = "std::";
169:     
170:     /**
171:      * Get the instance.
172:      *
173:      * @return the singleton of the generator.
174:      */
175:     public static GeneratorCpp getInstance() { return SINGLETON; }
176: 
177:     /**
178:      * Constructor.
179:      */
180:     protected GeneratorCpp() {
181:         super (Notation.makeNotation("Cpp", null,
182:                                      Argo.lookupIconResource ("CppNotation")));
183:     }
184: 
185:     /**
186:      * @param o the object to be generated
187:      * @return the generated string
188:      */
189:     public static String cppGenerate(Object o) {
190:         return SINGLETON.generate(o);
191:     }
192: 
193:     /**
194:      * Generate the header code for the given object
195:      * @param o the object to be generated
196:      * @return the generated header as a string
197:      */
198:     public String generateH(Object o) {
199:         generatorPass = HEADER_PASS;
200:         String ret = generate(o);
201:         generatorPass = NONE_PASS;
202:         return ret;
203:     }
