417:     /** 2002-12-07 Achim Spangler
418:      * @return date
419:      */
420:     private String getDate() {
421:         GregorianCalendar cal = new GregorianCalendar();
422:         DateFormat df;
423:         df = DateFormat.getDateInstance(DateFormat.DEFAULT);
424:         return df.format(cal.getTime());
425:     }
426: 
427:     /** 2002-12-07 Achim Spangler
428:      * @return year
429:      */
430:     private String getYear() {
431:         GregorianCalendar cal = new GregorianCalendar();
432:         return Integer.toString(cal.get(Calendar.YEAR));
433:     }
