1693:      * But if the Tag "inline" exists, the method body shall be defined as
1694:      * as inline in header file
1695:      * @return true -> generate body in actual path
1696:      */
1697:     private boolean checkGenerateOperationBody(Object cls) {
1698:         boolean result = !((generatorPass == HEADER_PASS)
1699:             || (Model.getFacade().isAbstract(cls))
1700:             || Model.getFacade().isAInterface(Model.getFacade().getOwner(cls)));
1701: 
1702:         // if this operation has Tag "inline" the method shall be
1703:         // generated in header
1704:         if (Model.getFacade().getTaggedValue(cls, "inline") != null) {
1705:             result = generatorPass == HEADER_PASS;
1706:         }
1707:         return result;
1708:     }
