1754:     /** 2002-12-13 Achim Spangler
1755:      * generate a single get function for a given attribute and StringBuffer
1756:      */
1757:     private void generateSingleAttributeGet(Object attr, StringBuffer sb) {
1758:         if (Model.getFacade().getType(attr) == null) return;
1759:         // generate for attributes with class-type:
1760:         // "const <type>& get_<name>( void ) { return <name>; };"
1761:         // generate for other (small) data types
1762:         // "<type> get_<name>( void ) { return <name>; };"
1763:         // generate: "INDENT"
1764:         sb.append(LINE_SEPARATOR).append(INDENT);
1765:         sb.append("/** simple access function to get the attribute ");
1766:         sb.append(Model.getFacade().getName(attr));
1767:         sb.append(" by function */").append(LINE_SEPARATOR).append(INDENT);
1768:         String modifier = generateAttributeParameterModifier(attr);
1769:         if (modifier != null && modifier.length() > 0) {
1770:             // generate: "const <type><modifier>"
1771:             sb.append("const ");
1772:             sb.append(generateClassifierRef(Model.getFacade().getType(attr)));
1773:             sb.append(modifier);
1774:         } else if (Model.getFacade().isAClass(
1775:                 Model.getFacade().getType(attr))) {
1776:             // generate: "const <type>&"
1777:             sb.append("const ");
1778:             sb.append(generateClassifierRef(Model.getFacade().getType(attr)));
1779:             sb.append("&");
1780:         } else {
1781:             // generate: "<type>"
1782:             sb.append(generateClassifierRef(Model.getFacade().getType(attr)));
1783:         }
1784:         // generate: " get_<name>( void ) const { return <name>; };"
1785:         sb.append(" get_").append(Model.getFacade().getName(attr));
1786:         sb.append("( void ) const { return ")
1787:             .append(Model.getFacade().getName(attr));
1788:         sb.append("; };").append(LINE_SEPARATOR);
