1809:             accessTag = Model.getFacade().getTaggedValueValue(attr, "set");
1810:             if (accessTag != null && accessTag.length() > 0) {
1811:                 if (accessTag.indexOf("public") != -1) {
1812:                     generateSingleAttributeSet(attr, funcPublic);
1813:                 }
1814:                 if (accessTag.indexOf("protected") != -1) {
1815:                     generateSingleAttributeSet(attr, funcProtected);
