1842:     private void generateClassifierBodyOperations(Object cls,
1843:             StringBuffer sb) {
1844:         Collection behs = Model.getCoreHelper().getOperations(cls);
1845:         if (behs.isEmpty()) return;
1846:         sb.append(LINE_SEPARATOR);
1847:         if (verboseDocs) {
1848:             sb.append(INDENT).append("// Operations").append(LINE_SEPARATOR);
1849:         }
1850: 
1851:         // generate tag controlled access functions for attributes
1852:         StringBuffer[] funcs = new StringBuffer[3]; 
1853:         funcs[0] = new StringBuffer(80);
1854:         funcs[1] = new StringBuffer(80);
1855:         funcs[2] = new StringBuffer(80);
1856:         generateClassifierBodyTaggedAccess4Attributes(cls, funcs[PRIVATE_PART],
1857:                                                       funcs[PROTECTED_PART],
1858:                                                       funcs[PUBLIC_PART]);
1859: 
1860:         Iterator behEnum = behs.iterator();
1861:         while (behEnum.hasNext()) {
1862:             Object bf = behEnum.next();
1863:             StringBuffer tb = null;
1864: 
1865:             int p = getVisibilityPart(bf);
1866:             if (p < 0) continue;
1867:             tb = funcs[p];
1868:             tb.append(LINE_SEPARATOR).append(INDENT);
1869: 
1870:             boolean mustGenBody = checkGenerateOperationBody(bf);
1871:             if (tb != null 
1872:                 && ((generatorPass == HEADER_PASS) || mustGenBody))
1873:             {
1874:                 tb.append(generate(bf));
1875:                 
1876:                 // helper for tagged values
1877:                 String tv = generateTaggedValues(bf, ALL_BUT_DOC_TAGS);
1878:                 
1879:                 if (mustGenBody && (Model.getFacade().isAClass(cls))
1880:                         && (Model.getFacade().isAOperation(bf))
1881:                         && (!Model.getFacade().isAbstract(bf))) {
1882:                     // there is no ReturnType in behavioral feature (nsuml)
1883:                     tb.append(LINE_SEPARATOR).append(generateMethodBody(bf));
1884:                 } else {
1885:                     tb.append(";").append(LINE_SEPARATOR);
1886:                     if (tv.length() > 0) {
1887:                         tb.append(INDENT).append(tv).append(LINE_SEPARATOR);
1888:                     }
1889:                 }
1890:             }
1891:         } // end loop through all operations
1892: 
1893:         sb.append(generateAllParts(funcs));
