2005:     /**
2006:      * Generate the body of a method associated with the given
2007:      * operation.  This assumes there's at most one method associated!
2008:      *
2009:      * If no method is associated with the operation, a default method
2010:      * body will be generated.
2011:      */
2012:     private String generateMethodBody(Object op) {
2013:         if (op != null) {
2014:             StringBuffer sb = new StringBuffer(80);
2015:             Collection methods = Model.getFacade().getMethods(op);
2016:             Iterator i = methods.iterator();
2017:             Object method = null;
2018:             boolean methodFound = false;
2019:             String tv = generateTaggedValues(op, ALL_BUT_DOC_TAGS);
2020:             String operationIndent =
2021:                 (generatorPass == HEADER_PASS) ? INDENT : "";
2022: 
2023:             // append tags which are not Doc-Comments
2024:             if (tv.length() > 0) {
2025:                 sb.append(operationIndent).append(tv).append(LINE_SEPARATOR);
2026:             }
2027: 
2028:             // place the curley braces within the protected area, to
2029:             // allow placement of preserved contructor initialisers in
2030:             // this area otherwise all possible constructor-attribute
2031:             // initialisers would have to be autogenerated with an
2032:             // army of special tags
2033:             sb.append(generateSectionTop(op, operationIndent))
2034:                 .append(operationIndent).append("{").append(LINE_SEPARATOR);
2035: 
2036:             while (i != null && i.hasNext()) {
2037:                 method = i.next();
2038: 
2039:                 if (method != null) {
2040:                     if ((Model.getFacade().getBody(method) != null)
2041:                             && (!methodFound)) {
2042:                         Object body = Model.getFacade().getBody(method);
2043:                         sb.append(Model.getFacade().getBody(body));
2044:                         methodFound = true;
2045:                         break;
2046:                     }
2047:                 }
2048:             }
2049: 
2050:             if (!methodFound) {
2051:                 // pick out return type as default method body
2052:                 Object rp =
2053:                     Model.getCoreHelper().getReturnParameter(op);
2054:                 if (rp != null) {
2055:                     Object returnType = Model.getFacade().getType(rp);
2056:                     sb.append(generateDefaultReturnStatement(returnType));
2057:                 }
2058:             }
2059:             sb.append(operationIndent).append("}").append(LINE_SEPARATOR)
2060:                 .append(generateSectionBottom(op, operationIndent));
2061:             return sb.toString();
2062:         }
2063:         return generateDefaultReturnStatement (null);
2064:     }
