2684:     private String generateMultiplicity(Object item, String name,
2685:             Object m, String modifier) {
2686:         String type = null;
2687:         String containerType = null;
2688:         Object typeCls = null;
2689:         if (Model.getFacade().isAAssociationEnd(item)) {
2690:             // take into account association classes
2691:             Object assoc = Model.getFacade().getAssociation(item);
2692:             if (Model.getFacade().isAAssociationClass(assoc)) {
2693:                 typeCls = assoc;
2694:                 name += "Assoc";
2695:             }
2696:             else
2697:                 typeCls = Model.getFacade().getType(item);
2698:         } else if (Model.getFacade().isAAttribute(item)) {
2699:             typeCls = Model.getFacade().getType(item);
2700:         } else if (Model.getFacade().isAClassifier(item)) {
2701:             type = Model.getFacade().getName(item);
2702:         } else {
2703:             type = "";
2704:         }
2705:         if (typeCls != null) {
2706:             type = generateNameWithPkgSelection(typeCls);
2707:         }
2708:         if (m == null) {
2709:             return (type + " " + modifier + name);
2710:         }
2711:         StringBuffer sb = new StringBuffer(80);
2712:         int countUpper = Model.getFacade().getUpper(m);
2713:         int countLower = Model.getFacade().getLower(m);
2714: 
2715:         if (countUpper == 1 && countLower == 1) {
2716:             // simple generate identifier for default 1:1 multiplicity
2717:             sb.append(type).append(' ').append(modifier).append(name);
2718:         } else if (countUpper == 1 && countLower == 0) {
2719:             // use a simple pointer for 0:1 multiplicity
2720:             // TODO: use an auto_ptr in case of attributes or compositions
2721:             sb.append(type).append(' ').append(modifier)
2722:                 .append("* ").append(name);
2723:         } else if (countUpper == countLower) {
2724:             // fixed array -> <type> <name>[<count>];
2725:             sb.append(type).append(' ').append(modifier).append(name)
2726:                 .append("[ " + countUpper + "]");
2727:         } else {
2728:             // variable association -> if no tag found use vector
2729:             // else search for tag:
2730:             // <MultipliciyType> : vector|list|slist|map|stack|stringmap
2731:             String multType =
2732:                 Model.getFacade().getTaggedValueValue(item, "MultiplicityType");
2733:             if (multType != null && multType.length() > 0) {
2734:                 if (multType.equals("vector")) {
2735:                     containerType = "vector";
2736:                 } else if (multType.equals("list")) {
2737:                     containerType = "list";
2738:                 } else if (multType.equals("slist")) {
2739:                     containerType = "slist";
2740:                 } else if (multType.equals("map")) {
2741:                     // FIXME: map does not work this way, needs a index type
2742:                     containerType = "map";
2743:                 } else if (multType.equals("stack")) {
2744:                     containerType = "stack";
2745:                 } else if (multType.equals("stringmap")) {
2746:                     if (extraIncludes.indexOf("#include <map>") == -1) {
2747:                         extraIncludes += "#include <map>" + LINE_SEPARATOR;
2748:                     }
2749:                     if (extraIncludes.indexOf("#include <string>") == -1) {
2750:                         extraIncludes += "#include <string>" + LINE_SEPARATOR;
2751:                     }
2752:                     sb.append(stdPrefix + "map<" + stdPrefix + "string, ");
2753:                     if (modifier.indexOf('&') != -1) {
2754:                         LOG.warn("cannot generate STL container "
2755:                                 + "with references, using pointers");
2756:                         modifier = "*";
2757:                     }
2758:                     sb.append(type).append(modifier);
2759:                     sb.append(" > ").append(name);
2760:                 } else {
2761:                     LOG.warn("unknown MultiplicityType \"" + multType
2762:                             + "\", using default");
2763:                     containerType = "vector";
2764:                 }
2765:             } else {
2766:                 containerType = "vector";
2767:             }
2768: 
2769:             if (containerType != null) {
2770:                 // these container are declared the same except the name
2771:                 String includeLine = "#include <" + containerType + ">";
2772:                 if (extraIncludes.indexOf(includeLine) == -1) {
2773:                     extraIncludes += includeLine + LINE_SEPARATOR;
2774:                 }
2775:                 sb.append(stdPrefix).append(containerType).append("< ");
2776:                 if (modifier.indexOf('&') != -1) {
2777:                     LOG.warn("cannot generate STL container "
2778:                             + "with references, using pointers");
2779:                     modifier = "*";
2780:                 }
2781:                 sb.append(type).append(modifier);
2782:                 sb.append(" > ").append(name);
2783:             }
2784:         }
2785:         return sb.toString();
2786:     }
