289:      * It works only for classes and interfaces, everything else is ignored.
290:      *
291:      * Param node is the node.
292:      * Param path is the base path for the source.
293:      * Returns the full path name of the the generated file, or null if 'o'
294:      * is not a class or a interface.
295:      *
296:      * @see org.argouml.uml.generator.FileGenerator#generateFile2(
297:      * java.lang.Object, java.lang.String)
298:      */
299:     public String generateFile2(Object o, String path) {
300:         if (!Model.getFacade().isAClass(o)
301:                && !Model.getFacade().isAInterface(o)) {
302:             // TODO: is returning null a correct behaviour here?
303:             return null;
304:         }
305:         String packagePath =
306:             Model.getFacade().getName(Model.getFacade().getNamespace(o));
307:         String pathname = null;
308: 
309:         // use unique section for both passes -> allow move of
310:         // normal function body to inline and vice versa
311:         sect = new Section();
312: 
313:         /*
314:          * 2002-11-28 Achim Spangler
315:          * first read header and source file into global/unique section
316:          */
317:         for (generatorPass = HEADER_PASS;
318:              generatorPass <= SOURCE_PASS;
319:              generatorPass++) {
320:             pathname = generateDirectoriesPathname(o, path);
321:             //String pathname = path + filename;
322:             // TODO: package, project basepath, tagged values to configure
323:             File f = new File(pathname);
324:             if (f.exists()) {
325:                 LOG.info("Generating (updated) " + f.getPath());
326:                 sect.read(pathname);
327:             } else {
328:                 LOG.info("Generating (new) " + f.getPath());
329:             }
330:         }
331: 
332:         /**
333:          * 2002-11-28 Achim Spangler
334:          * run basic generation function two times for header and implementation
335:          */
336:         for (generatorPass = HEADER_PASS;
337:              generatorPass <= SOURCE_PASS;
338:              generatorPass++) {
339:             pathname = generateDirectoriesPathname(o, path);
340:             //String pathname = path + filename;
341:             // TODO: package, project basepath, tagged values to configure
342:             File f = new File(pathname);
343:             if (generatorPass == SOURCE_PASS 
344:                     && Model.getFacade().isAInterface(o))
345:                 break; // don't generate the .cpp, it's useless.
346: 
347:             String headerTop = generateHeaderTop(pathname);
348:             String header = generateHeader(o, packagePath);
349:             String src = generate(o);
350:             BufferedWriter fos = null;
351:             try {
352:                 fos = new BufferedWriter (new FileWriter (f));
353:                 if (generatorPass == HEADER_PASS) {
354:                     String name = Model.getFacade().getName(o);
355:                     String guard = generateRelativeDirPath(o) + '_' 
356:                         + name + getFileExtension();
357:                     guard = guard.replace('/', '_').replace('.', '_');
358:                     fos.write("#ifndef " + guard + LINE_SEPARATOR 
359:                             + "#define " + guard 
360:                             + LINE_SEPARATOR + LINE_SEPARATOR);
361:                 }
362:                 writeTemplate(o, path, fos);
363:                 fos.write(headerTop);
364:                 fos.write(extraIncludes);
365:                 fos.write(header);
366:                 fos.write(src);
367:                 if (generatorPass == HEADER_PASS) {
368:                     fos.write("#endif");
369:                     fos.write(LINE_SEPARATOR);
370:                 }
371:             }
372:             catch (IOException exp) { }
373:             finally {
374:                 try {
375:                     if (fos != null) fos.close();
376:                 }
377:                 catch (IOException exp) {
378:                     LOG.error("FAILED: " + f.getPath());
379:                 }
380:             }
381: 
382:             // clear extra includes after usage for each pass
383:             extraIncludes = "";
384: 
385:             // output lost sections only in the second path
386:             // -> sections which are moved from header(inline) to source
387:             // file are prevented to be outputted in header pass
388:             if (generatorPass == HEADER_PASS)   {
389:                 sect.write(pathname, INDENT, false);
390:             }
391:             else sect.write(pathname, INDENT, true);
392: 
393:             LOG.info("written: " + pathname);
394: 
395:             File f1 = new File(pathname + ".bak");
396:             if (f1.exists()) {
397:                 f1.delete();
398:             }
399: 
400:             File f2 = new File(pathname);
401:             if (f2.exists()) {
402:                 f2.renameTo(new File(pathname + ".bak"));
403:             }
404: 
405:             File f3 = new File(pathname + ".out");
406:             if (f3.exists()) {
407:                 f3.renameTo(new File(pathname));
408:             }
409: 
410:             LOG.info("----- end updating -----");
411:         }
412:         // reset generator pass to NONE for the notation to be correct
413:         generatorPass = NONE_PASS;
414:         return pathname;
415:     }
