559:         }
560: 
561:         // if class depends on a list of other classes, all inheritance
562:         // elements are seperated by Tokens ", " -> use StringTokenizer
563:         // to access the single elements
564:         StringTokenizer st = new StringTokenizer(packagePath, ", ");
565:         while (st.hasMoreTokens()) {
566:             sb.append("#include <").append(st.nextToken()).append(".h>")
567:                 .append(LINE_SEPARATOR);
568:         }
569:         return sb.toString();
570:     }
