832:     private String generateNameWithPkgSelection(Object item, Object localPkg) {
833:         if (item == null) {
834:             return "void ";
835:         }
836:         Object pkg = null;
837:         if (Model.getFacade().isADataType(item)) {
838:             return generateName(Model.getFacade().getName(item));
839:         } else if (Model.getFacade().isAParameter(item)
840:                    || Model.getFacade().isAAttribute(item)
841:                    || Model.getFacade().isAAssociationEnd(item)
842:                    || Model.getFacade().isAClassifier(item)) {
843:             pkg = getNamespaceWithoutModel(item);
844:         }
845: 
846:         if (pkg == null) {
847:             return generateName(Model.getFacade().getName(item));
848:         }
849:         if (localPkg == null) {
850:             LOG.info("LOCAL NAMESPACE IS NULL");
851:         }
852: 
853:         String localPkgName = generatePackageAbsoluteName(localPkg);
854:         String targetPkgName = generatePackageAbsoluteName(pkg);
855: 
856:         int localPkgNameLen = localPkgName.length();
857:         int targetPkgNameLen = targetPkgName.length();
858:         if (localPkgName.equals(targetPkgName)) {
859:             return generateName(Model.getFacade().getName(item));
860:         }
861:         if (targetPkgName.indexOf(localPkgName) != -1) {
862:             if (targetPkgName.substring(localPkgNameLen, localPkgNameLen + 2)
863:                 .equals("::")) {
864:                 // target is in Sub-Package of local class
865:                 return (targetPkgName.substring(localPkgNameLen + 2,
866:                                 targetPkgNameLen)
867:                     + "::"
868:                     + generateName(Model.getFacade().getName(item)));
869:             }
870:         }
871:         return (targetPkgName + "::" 
872:                 + generateName(Model.getFacade().getName(item)));
873:     }
