1010:     /** 2002-11-28 Achim Spangler
1011:      * seperate generation of Operation Prefix from generateOperation
1012:      * so that generateOperation is language independent
1013:      */
1014:     private String generateOperationPrefix(Object op) {
1015:         StringBuffer sb = new StringBuffer(80);
1016:         // c++ doesn't have any builtin construct for concurrency
1017:         //sb.append(generateConcurrency(op));
1018:         if (generatorPass != SOURCE_PASS) {
1019:             // make all operations to virtual - as long as they are not "leaf"
1020:             Object scope = Model.getFacade().getOwnerScope(op);
1021:             if (Model.getFacade().isLeaf(op)
1022: 		    && !Model.getFacade().isRoot(op)) {
1023:                 // there's no way to make a leaf method that it's not root in
1024:                 // c++, so warn the user and ignore the 'root' attribute
1025:                 // (or it may be better to ignore the 'leaf' attribute?)
1026:                 LOG.warn(op + " is leaf but not root: "
1027: 			 + "C++ can't handle this properly");
1028: 		LOG.warn("    Ignoring the 'root' attribute");
1029:             }
1030:             // generate a function as virtual, if it can be overriden
1031:             // or override another function AND if this function is
1032:             // not marked as static, which disallows "virtual"
1033:             // alternatively every abstract function is defined as
1034:             // virtual
1035:             if ((!Model.getFacade().isLeaf(op)
1036:                     && !Model.getFacade().isConstructor(op)
1037:                     && (!(Model.getScopeKind().getClassifier().equals(scope))))
1038:                     || (Model.getFacade().isAbstract(op))) {
1039:                 sb.append("virtual ");
1040:             }
1041:             sb.append(generateOwnerScope(op));
1042:         }
1043:         return sb.toString();
1044:     }
