1164:     /** 2002-12-06 Achim Spangler
1165:      * check if a parameter is tagged as pointer or reference (not
1166:      * part of UML - as far as author knows - but important for C++
1167:      * developers)
1168:      * @param elem element to check
1169:      * @return one of NORMAL_MOD, REFERENCE_MOD, POINTER_MOD, or -1 if
1170:      *         no specific tag is found
1171:      */
1172:     private int getAttributeModifierType(Object elem) {
1173:         // first check whether the parameter shall be a pointer of reference
1174:         Iterator iter = Model.getFacade().getTaggedValues(elem);
1175:         while (iter.hasNext()) {
1176:             Object tv = iter.next();
1177:             String tag = Model.getFacade().getTagOfTag(tv);
1178:             String val = Model.getFacade().getValueOfTag(tv);
1179:             if (tag.indexOf("ref") != -1 || tag.equals("&")) {
1180:                 return val.equals("false") ? NORMAL_MOD
1181:                                            : REFERENCE_MOD;
1182:             } else if (tag.indexOf("pointer") != -1 || tag.equals("*")) {
1183:                 return val.equals("false") ? NORMAL_MOD
1184:                                            : POINTER_MOD;
1185:             }
1186:         }
1187:         return -1; /* no tag found */
