1713:     private void generateSingleAttributeSet(Object attr, StringBuffer sb) {
1714:         if (Model.getFacade().getType(attr) == null) {
1715:             return;
1716:         }
1717:         // generate for attributes with class-type:
1718:         // "INDENT void set_<name>( const <type> &value ) { <name> = value; };"
1719:         // generate for other (small) data types:
1720:         // "INDENT void set_<name>( <type> value ) { <name> = value; };"
1721:         // generate: "INDENT void set_<name>( "
1722:         sb.append(LINE_SEPARATOR).append(INDENT);
1723:         sb.append("/** simple access function to set the attribute ");
1724:         sb.append(Model.getFacade().getName(attr));
1725:         sb.append(" by function").append(LINE_SEPARATOR).append(INDENT);
1726:         sb.append("  * @param value value to set for the attribute ");
1727:         sb.append(Model.getFacade().getName(attr)).append(LINE_SEPARATOR);
1728:         sb.append(INDENT).append("  */").append(LINE_SEPARATOR);
1729:         sb.append(INDENT);
1730:         sb.append("void set_").append(Model.getFacade().getName(attr))
1731:             .append("( ");
1732:         String modifier = generateAttributeParameterModifier(attr);
1733:         if (modifier != null && modifier.length() > 0) {
1734:             // generate: "const <type> <modifier>value"
1735:             if (modifier.equals("&")) sb.append("const ");
1736:             sb.append(generateClassifierRef(Model.getFacade().getType(attr)))
1737:                 .append(' ').append(modifier).append("value");
1738:         } else if (Model.getFacade().isAClass(
1739:                 Model.getFacade().getType(attr))) {
1740:             // generate: "const <type> &value"
1741:             sb.append("const ");
1742:             sb.append(generateClassifierRef(Model.getFacade().getType(attr)));
1743:             sb.append(" &value");
