2312:      * @param me the model element for which the documentation comment is needed
2313:      * @param ae the association end which is represented by the model element
2314:      * @return the documentation comment for the specified model element, either
2315:      * enhanced or completely generated
2316:      */
2317:     public String generateConstraintEnrichedDocComment(Object me, Object ae) {
2318:         // list tagged values for documentation
2319:         String s = generateTaggedValues (me, DOC_COMMENT_TAGS);
2320: 
2321:         Object multiplicity = Model.getFacade().getMultiplicity(ae);
2322:         if (!(Model.getMultiplicities().get11().equals(multiplicity)
2323:                 || Model.getMultiplicities().get01().equals (multiplicity))) {
2324:             // Multiplicity greater 1, that means we will generate some sort of
2325:             // collection, so we need to specify the element type tag
2326:             StringBuffer sDocComment = new StringBuffer(80);
2327: 
2328:             // Prepare doccomment
2329:             if (!(s == null || "".equals(s))) {
2330:                 // Just remove closing "*/"
2331:                 sDocComment.append(INDENT)
2332:                     .append(s.substring(0, s.indexOf("*/") + 1));
2333:             }
2334:             else {
2335:                 sDocComment.append(INDENT).append("/**").append(LINE_SEPARATOR);
2336:                 sDocComment.append(INDENT).append(" *");
2337:             }
2338: 
2339:             // Build doccomment
2340:             Object type = Model.getFacade().getType(ae);
2341:             if (type != null) {
2342:                 sDocComment.append(" @element-type ");
2343:                 sDocComment.append(Model.getFacade().getName(type));
2344:             }
2345:             sDocComment.append(LINE_SEPARATOR).append(INDENT)
2346:                 .append(" */").append(LINE_SEPARATOR);
2347:             return sDocComment.toString();
2348:         }
2349:         return (s != null) ? s : "";
2350:     }
