2788:     private String generateMultiplicityRange(Object mr) {
2789:         Integer lower = new Integer(Model.getFacade().getLower(mr));
2790:         Integer upper = new Integer(Model.getFacade().getUpper(mr));
2791:         if (lower == null && upper == null) {
2792:             return ANY_RANGE;
2793:         }
2794:         if (lower == null) {
2795:             return "*.." + upper.toString();
2796:         }
2797:         if (upper == null) {
2798:             return lower.toString() + "..*";
2799:         }
2800:         if (lower.intValue() == upper.intValue()) {
2801:             return lower.toString();
2802:         }
2803:         return lower.toString() + ".." + upper.toString();
2804:     }
