651:     /**
652:      * Builds a fully configurable association end. All variables for
653:      * an associationend can be given as parameter.
654:      * @param assoc The associaton this end will be part of
655:      * @param name The name of the association end
656:      * @param type The type (classifier) the end will connect. The end
657:      * is a connection piece between an association and a classifier
658:      * @param multi The multiplicity
659:      * @param stereo The stereotype
660:      * @param navigable The navigability. True if this association end
661:      *                  can be 'passed' from the other classifier.
662:      * @param order Ordering of the association
663:      * @param aggregation the aggregationkind
664:      * @param scope the scope kind
665:      * @param changeable the changeablekind
666:      * @param visibility the visibilitykind
667:      * @return MAssociationEnd
668:      */
669:     public MAssociationEnd buildAssociationEnd(
670: 					       MAssociation assoc,
671: 					       String name,
672: 					       MClassifier type,
673: 					       MMultiplicity multi,
674: 					       MStereotype stereo,
675: 					       boolean navigable,
676: 					       MOrderingKind order,
677: 					       MAggregationKind aggregation,
678: 					       MScopeKind scope,
679: 					       MChangeableKind changeable,
680: 					       MVisibilityKind visibility) {
681:         // wellformednessrules and preconditions
682:         if (assoc == null || type == null) {
683:             throw new IllegalArgumentException("either type or association "
684: 					       + "are null");
685:         }
686:         if (type instanceof MDataType || type instanceof MInterface) {
687:             if (!navigable) {
688:                 throw new IllegalArgumentException(
689:                         "Wellformedness rule 2.5.3.3 [1] is broken. "
690:                         + "The Classifier of an AssociationEnd cannot be an "
691:                         + "Interface or a DataType if the association is "
692:                         + "navigable away from that end.");
693:             }
694:             List ends = new ArrayList();
695:             ends.addAll(assoc.getConnections());
696:             Iterator it = ends.iterator();
697:             while (it.hasNext()) {
698:                 MAssociationEnd end = (MAssociationEnd) it.next();
699:                 if (end.isNavigable()) {
700:                     throw new IllegalArgumentException("type is either "
701: 						       + "datatype or "
702: 						       + "interface and is "
703: 						       + "navigable to");
704:                 }
705:             }
706:         }
707:         if (aggregation != null
708:                 && aggregation.equals(MAggregationKind.COMPOSITE)
709:                 && multi != null
710:                 && multi.getUpper() > 1) {
711:             throw new IllegalArgumentException("aggregation is composite "
712: 					   + "and multiplicity > 1");
713:         }
714: 
715:         MAssociationEnd end =
716:             Model.getUmlFactory().getCore().createAssociationEnd();
717:         end.setAssociation(assoc);
718:         end.setType(type);
719:         end.setName(name);
720:         if (multi != null) {
721:             end.setMultiplicity(multi);
722:         } else {
723:             end.setMultiplicity(MMultiplicity.M1_1);
724:         }
725:         if (stereo != null) {
726:             end.setStereotype(stereo);
727:         }
728:         end.setNavigable(navigable);
729:         if (order != null) {
730:             end.setOrdering(order);
731:         } else {
732:             end.setOrdering(MOrderingKind.UNORDERED);
733:         }
734:         if (aggregation != null) {
735:             end.setAggregation(aggregation);
736:         } else {
737:             end.setAggregation(MAggregationKind.NONE);
738:         }
739:         if (scope != null) {
740:             end.setTargetScope(scope);
741:         } else {
742:             end.setTargetScope(MScopeKind.INSTANCE);
743:         }
744:         if (changeable != null) {
745:             end.setChangeability(changeable);
746:         } else {
747:             end.setChangeability(MChangeableKind.CHANGEABLE);
748:         }
749:         if (visibility != null) {
750:             end.setVisibility(visibility);
751:         } else {
752:             end.setVisibility(MVisibilityKind.PUBLIC);
753:         }
754:         return end;
755:     }
