1353:     /**
1354:      * Adds a parameter initialized to default values to a given event
1355:      * or behavioral feature.
1356:      *
1357:      * @param o an event or behavioral feature
1358:      * @param model the model to which the event or behavioral feature belongs
1359:      * @param voidType the type of the return parameter
1360:      * @param propertyChangeListeners the listeners
1361:      * @return the parameter
1362:      */
1363:     public MParameter buildParameter(Object o, Object model, Object voidType,
1364:             Collection propertyChangeListeners) {
1365:         if (o instanceof MEvent) {
1366:             MEvent event = (MEvent) o;
1367:             MParameter res = (MParameter) buildParameter((MModel) model,
1368:                     (MClassifier) voidType);
1369:             res.setKind(MParameterDirectionKind.IN);
1370:             //    removing this next line solves issue 2209
1371:             //res.setNamespace(event.getNamespace());
1372:             event.addParameter(res);
1373:             return res;
1374:         } else if (o instanceof MBehavioralFeature) {
1375:             MBehavioralFeature oper = (MBehavioralFeature) o;
1376:             if (oper == null || oper.getOwner() == null) {
1377:                 throw new IllegalArgumentException(
1378:                         "operation is null or does not have an owner");
1379:             }
1380:             MParameter res = (MParameter) buildParameter((MModel) model,
1381:                     (MClassifier) voidType);
1382:             String name = "arg";
1383:             int counter = 1;
1384: 
1385:             oper.addParameter(res);
1386:             Iterator it = oper.getParameters().iterator();
1387:             while (it.hasNext()) {
1388:                 MParameter para = (MParameter) it.next();
1389:                 if ((name + counter).equals(para.getName())) {
1390:                     counter++;
1391:                 }
1392:             }
1393: 
1394:             res.setName(name + counter);
1395: 
1396:             // we set the listeners to the figs here too
1397:             // it would be better to do that in the figs themselves
1398:             it = propertyChangeListeners.iterator();
1399:             while (it.hasNext()) {
1400:                 PropertyChangeListener listener =
1401:                     (PropertyChangeListener) it.next();
1402:                 // Model.getPump().removeModelEventListener(listener, res);
1403:                 Model.getPump().addModelEventListener(listener, res);
1404:             }
1405:             return res;
1406:         } else {
1407:             return null;
1408:         }
1409:     }
