1411:     /**
1412:      * Builds a realization between some supplier (for example an
1413:      * interface in Java) and a client who implements the realization.
1414:      *
1415:      * @param clnt is the client
1416:      * @param spplr is the supplier
1417:      * @param model the namespace to use if client and
1418:      * supplier are of different namespace
1419:      * @return Object the created abstraction
1420:      */
1421:     public Object buildRealization(
1422:             Object clnt,
1423:             Object spplr,
1424:             Object model) {
1425:         MModelElement client = (MModelElement) clnt;
1426:         MModelElement supplier = (MModelElement) spplr;
1427: 	if (client == null
1428: 	    || supplier == null
1429: 	    || client.getNamespace() == null
1430: 	    || supplier.getNamespace() == null) {
1431: 	    throw new IllegalArgumentException("faulty arguments.");
1432: 	}
1433: 	Object realization =
1434: 	    Model.getUmlFactory().getCore().createAbstraction();
1435: 	MNamespace nsc = client.getNamespace();
1436: 	MNamespace nss = supplier.getNamespace();
1437: 	MNamespace ns = null;
1438: 	if (nsc.equals(nss)) {
1439: 	    ns = nsc;
1440: 	} else {
1441: 	    ns = (MModel) model;
1442: 	}
1443: 	Model.getExtensionMechanismsFactory().buildStereotype(realization,
1444: 								"realize", ns);
1445: 	ModelFacade.addClientDependency(client, realization);
1446: 	ModelFacade.addSupplierDependency(supplier, realization);
1447: 	return realization;
1448:     }
