1461: 	    throw new IllegalArgumentException("In buildUsage null arguments.");
1462: 	}
1463: 	if (client.getModel() != supplier.getModel()) {
1464: 	    throw new IllegalArgumentException("To construct a usage, the "
1465: 					       + "client and the supplier "
1466: 					       + "must be part of the same "
