1753:      * are deleted by the NSUML method remove. This method should not be called
1754:      * directly.<p>
1755:      *
1756:      * In the case of a modelelement these are the following elements:<ul>
1757:      * <li>Dependencies that have the modelelement as supplier or as a client
1758:      * and are binary. (that is, they only have one supplier and one client)
1759:      * </ul>
1760:      *
1761:      * @param elem
1762:      * @see UmlFactoryImpl#delete(Object)
1763:      */
1764:     public void deleteModelElement(MModelElement elem) {
1765: 	Collection supplierDep = elem.getSupplierDependencies();
1766: 	Collection clientDep = elem.getClientDependencies();
1767: 	Set deps = new HashSet();
1768: 	deps.addAll(supplierDep);
1769: 	deps.addAll(clientDep);
1770: 	Iterator it = deps.iterator();
1771: 	while (it.hasNext()) {
1772: 	    MDependency dep = (MDependency) it.next();
1773: 	    Collection clients = dep.getClients();
1774: 	    Collection suppliers = dep.getSuppliers();
1775: 	    if ((clients.size() + suppliers.size()) == 2) {
1776: 		Model.getUmlFactory().delete(dep);
1777: 	    }
1778: 	}
1779: 
1780: 	it = elem.getComments().iterator();
1781:         while (it.hasNext()) {
1782:             MComment comment = (MComment) it.next();
1783:             if (comment.getAnnotatedElements().size() == 1) {
1784:                 Model.getUmlFactory().delete(comment);
1785:             }
1786:         }
1787: 
1788:         List ownedBehaviors = new ArrayList();
1789:         ownedBehaviors.addAll(elem.getBehaviors());
1790:         it = ownedBehaviors.iterator();
1791:         while (it.hasNext()) {
1792:             Model.getUmlFactory().delete(it.next());
1793:         }
1794:     }
