467:             throw new IllegalArgumentException("one of "
468: 					       + "the classifiers does not "
469: 					       + "belong to a namespace");
470:         }
471:         MAssociation assoc =
472:             Model.getUmlFactory().getCore().createAssociation();
473:         assoc.setName("");
474:         assoc.setNamespace(Model.getCoreHelper().getFirstSharedNamespace(ns1,
475:         								  ns2));
476:         buildAssociationEnd(
477: 			    assoc,
478: 			    null,
479: 			    c1,
480: 			    null,
481: 			    null,
482: 			    nav1,
