1146:         if (child == null
1147: 	    || parent == null
1148: 	    || !(child instanceof MGeneralizableElement)
1149: 	    || !(parent instanceof MGeneralizableElement)) {
1150:             return null;
1151:         }
1152:         Object gen = buildGeneralization(child, parent);
1153:         if (gen != null) {
1154:             ((MGeneralization) gen).setName(name);
1155:         }
1156:         return gen;
