147:     /**
148:      * Adds a listener to events fired by metaClass modelClass. All events fired
149:      * by instances of modelClass or instances of its subclasses will be pumped
150:      * to the listener.
151:      *
152:      * <p><em>Note:</em> Due to the fact that ALL events are pumped for some
153:      * metaclass and it's children, this is a very powerfull method but also
154:      * one that can hog performance. Use this with care!</p>
155:      * @param listener
156:      * @param modelClass
157:      */
158:     public void addClassModelEventListener(MElementListener listener, Class modelClass) {
159:         if (listener == null || modelClass == null)
160:             throw new IllegalArgumentException("Tried to add null listener to null class");
161:         if (!MBase.class.isAssignableFrom(modelClass))
162:             throw new IllegalArgumentException("Tried to add illegal class modeleventlistener.");
163:         executeAddClassModelEventListener(listener, modelClass, null);
164:     }
