172:     private synchronized void executeAddClassModelEventListener(MElementListener listener, Class modelClass, String eventName) {
173:         // first register the listener for all elements allready in the model
174:         cat.debug("Registring listener " + listener + " to class " + modelClass.getName() + " and event " + eventName);
175:         Collection col = ModelManagementHelper.getHelper().getAllModelElementsOfKind(modelClass);
176:         MModel root = ProjectManager.getManager().getCurrentProject().getRoot();
177:         if (modelClass.isAssignableFrom(root.getClass())) {
178:             col.add(root);
