181:         while (listeners.hasNext()) {
182:             executeAddModelEventListener(listener, (MBase) listeners.next(), eventName);
183:         }
184:         // add the class to the 'interested classes list' so the listener is added on creation
185:         // of a modelelement
186:         Set listenerList = (Set) _listenerClassModelEventsMap.get(modelClass);
187:         if (listenerList == null) {
