199:     super.setTarget(t);
200:     Association asc = (Association) t;
201:     Vector conns = asc.getConnection();
202:     if (conns == null) return; //set fields to blanks?
203:     if (conns.size() != 2) return; //set fields to blanks?
204:     AssociationEnd endA = (AssociationEnd) conns.elementAt(0);
205:     AssociationEnd endB = (AssociationEnd) conns.elementAt(1);
206: 
207:     Name roleA = endA.getName();
208:     String roleAStr = "(anon)";
209:     if (roleA != null) roleAStr = roleA.getBody();
