276:   public void setMult() {
277:     if (_target == null) return;
278:     Multiplicity mA, mB;
279:     Object mAs = _multAField.getSelectedItem();
280:     Object mBs = _multBField.getSelectedItem();
281: 
282:     if (mAs == null || mBs == null) return;
283: 
284:     // will be a String if I allow editing, needs-more-work: implement
285:     // parsing of multiplicities
286:     if (mAs instanceof String)
287:       mAs = ParserDisplay.SINGLETON.parseMultiplicity((String)mAs);
288:     if (mBs instanceof String)
289:       mBs = ParserDisplay.SINGLETON.parseMultiplicity((String)mBs);
290: 
291:     if (mAs instanceof Multiplicity) mA = (Multiplicity) mAs;
292:     else mA = Multiplicity.ONE; // needs-more-work: parse
293: 
294:     if (mBs instanceof Multiplicity) mB = (Multiplicity) mBs;
295:     else mB = Multiplicity.ONE; // needs-more-work: parse
296: 
297:     Association asc = (Association) _target;
298:     Vector conns = asc.getConnection();
299:     if (conns == null || conns.size() != 2) return;
300:     AssociationEnd endA = (AssociationEnd) conns.elementAt(0);
301:     AssociationEnd endB = (AssociationEnd) conns.elementAt(1);
302:     try {
303:       endA.setMultiplicity(mA);
304:       endB.setMultiplicity(mB);
305:     }
306:     catch (PropertyVetoException pve) { }
307:   }
