162: 	super.calcBounds();
163: 	Collection figs = getFigs(null);
164: 	if (!figs.isEmpty()) {
165: 	    Fig last = null;
166: 	    Fig first = null;
167: 	    // _x = first.getX();
168: 	    // _y = first.getY();
169: 	    _w = 0;
170:             Iterator it = figs.iterator();
171:             int size = figs.size();
172: 	    for (int i = 0; i < size; i++) {
173:                 Fig fig = (Fig) it.next();
174:                 
175:                 if (i == 0) {
176:                     first = fig;
177:                 }
178:                 if (i == size - 1) {
179:                     last = fig;
180:                 }
181:                 
182: 		if (fig.getWidth() > _w) { 
183: 		    _w = fig.getWidth();
184: 		}
185: 	    }
186:             _h = last.getY() + last.getHeight() - first.getY();
187: 	} else {
188: 	    _w = 0;
189: 	    _h = 0;
190: 	}
191:     }
