48: /**
49:  * A Mode to interpret user input while creating a comment edge.
50:  * The comment can connect an existing comment node to any other existing
51:  * If the association is an n-ary association (diamond shape node) then
52:  * the edge is simply added.
53:  * If the association is a binary association edge then that edge is
54:  * transformed into a n-ary association.
55:  *
56:  * @author pepargouml@yahoo.es
57:  */
58: public class ModeCreateCommentEdge extends ModeCreatePolyEdge {
59:     
60:     private FigNode newFigNodeAssociation;
61:     private FigEdgeModelElement sourceEdge;
62:     private Object sourceModelElement;
63:     private Collection associationEnds;
