470:     /**
471:      * Get the minimum size for the note figure.
472:      *
473:      * @return The minimum size for the note figure.
474:      */
475:     public Dimension getMinimumSize() {
476: 
477:         // Get the size of the text field.
478:         Dimension aSize = text.getMinimumSize();
479: 
480:         // If we have a stereotype displayed, then allow some space for that
481:         // (width and height)
482: 
483:         if (getStereotypeFig().isVisible()) {
484:             Dimension stereoMin = getStereotypeFig().getMinimumSize();
485:             aSize.width =
486:                 Math.max(aSize.width,
487:                          stereoMin.width);
488:             if (SingleStereotypeEnabler.isEnabled()) {
489:                 aSize.height += STEREOHEIGHT;
490:             } else {
491:                 aSize.height += stereoMin.height;
492:             }
493:         }
494:         
495:         // And add the gaps around the textfield to get the minimum
496:         // size of the note.
497:         return new Dimension(aSize.width + 4 + dogear,
498: 			     aSize.height + 4);
