501:     /**
502:      * @see org.tigris.gef.presentation.Fig#setBounds(int, int, int, int)
503:      */
504:     protected void setBoundsImpl(int px, int py, int w, int h) {
505:         if (text == null) {
506:             return;
507:         }
508:         
509:         Dimension stereoMin = getStereotypeFig().getMinimumSize();
510:         
511:         int stereotypeHeight = 0;
512:         if (getStereotypeFig().isVisible()) {
513:             if (SingleStereotypeEnabler.isEnabled()) {
514:                 stereotypeHeight = STEREOHEIGHT;
515:             } else {
516:                 stereotypeHeight = stereoMin.height;
517:             }
518:         }
519:         
520:         Rectangle oldBounds = getBounds();
521: 
522:         // Resize the text figure
523:         text.setBounds(px + 2, py + 2 + stereotypeHeight, 
524:                 w - 4 - dogear, h - 4 - stereotypeHeight);
525: 
526:         if (SingleStereotypeEnabler.isEnabled()) {
527:             getStereotypeFig().setBounds(px + 2, py + 2,
528:                     w - 4 - dogear, STEREOHEIGHT);
529:         } else {
530:             getStereotypeFig().setBounds(px + 2, py + 2,
531:                     w - 4 - dogear, stereoMin.height);
532:         }
533:         
534:         // Resize the big port around the figure
535:         getBigPort().setBounds(px, py, w, h);
536: 
537:         // Since this is a complex polygon, there's no easy way to resize it.
538:         Polygon newPoly = new Polygon();
539:         newPoly.addPoint(px, py);
540:         newPoly.addPoint(px + w - 1 - dogear, py);
541:         newPoly.addPoint(px + w - 1, py + dogear);
542:         newPoly.addPoint(px + w - 1, py + h - 1);
543:         newPoly.addPoint(px, py + h - 1);
544:         newPoly.addPoint(px, py);
545:         body.setPolygon(newPoly);
546: 
547:         // Just move the corner to it's new position.
548:         urCorner.setBounds(px + w - 1 - dogear, py, dogear, dogear);
549: 
550:         calcBounds(); //_x = x; _y = y; _w = w; _h = h;
551:         firePropChange("bounds", oldBounds, getBounds());
552:     }
