117:         body.addPoint(x + width - 1, y + dogear);
118:         body.addPoint(x + width - 1, y + height - 1);
119:         body.addPoint(x, y + height - 1);
120:         body.addPoint(x, y);
121:         body.setFilled(true);
122:         body.setLineWidth(1);
123: 
124:         urCorner = new FigPoly(Color.black, Color.white);
125:         urCorner.addPoint(x + width - 1 - dogear, y);
126:         urCorner.addPoint(x + width - 1, y + dogear);
127:         urCorner.addPoint(x + width - 1 - dogear, y + dogear);
128:         urCorner.addPoint(x + width - 1 - dogear, y);
129:         urCorner.setFilled(true);
130:         Color col = body.getFillColor();
131:         urCorner.setFillColor(col.darker());
132:         urCorner.setLineWidth(1);
133: 
134:         if (SingleStereotypeEnabler.isEnabled()) {
135:             getStereotypeFig().setHeight(STEREOHEIGHT);
136:             getStereotypeFig().setVisible(false);
137:         }
138:         
139:         setBigPort(new FigRect(x, y, width, height, null, null));
140:         getBigPort().setFilled(false);
141:         getBigPort().setLineWidth(0);
142: 
143:         text = new FigMultiLineText(x + 2, y + 2, width - 2 - dogear, height - 4, true);
144: 
145:         // add Figs to the FigNode in back-to-front order
146:         addFig(getBigPort());
147:         addFig(body);
148:         addFig(urCorner);
149:         addFig(getStereotypeFig());
150:         addFig(text);
151: 
152:         setBlinkPorts(false); //make port invisble unless mouse enters
153:         Rectangle r = getBounds();
154:         setBounds(r.x, r.y, r.width, r.height);
155:         updateEdges();
156: 
157:         readyToEdit = false;
158:         // Mark this as newly created. This is to get round the problem with
159:         // creating figs for loaded comments that had stereotypes. They are
160:         // saved with their dimensions INCLUDING the stereotype, but since we
161:         // pretend the stereotype is not visible, we add height the first time
162:         // we render such a comment. This is a complete fudge, and really we
163:         // ought to address how comment objects with stereotypes are saved. But
164:         // that will be hard work.
165:         newlyCreated = true;
166:     }
