597:     /**
598:      * @see org.argouml.uml.diagram.ui.FigNodeModelElement#updateStereotypeText()
599:      */
600:     protected void updateStereotypeText() {
601:         if (SingleStereotypeEnabler.isEnabled()) {
602:             updateStereotypeTextSingleStereotype();
603:             return;
604:         }
605:         Object me = /*(MModelElement)*/ getOwner();
606: 
607:         if (me == null) {
608:             return;
609:         }
610: 
611:         Rectangle rect = getBounds();
612: 
613:         Dimension stereoMin = getStereotypeFig().getMinimumSize();
614:         
615:         if (Model.getFacade().getStereotypes(me).isEmpty()) {
616: 
617:             if (getStereotypeFig().isVisible()) {
618:                 getStereotypeFig().setVisible(false);
619:                 rect.y += stereoMin.height;
620:                 rect.height -= stereoMin.height;
621:                 setBounds(rect.x, rect.y, rect.width, rect.height);
622:                 calcBounds();
623:             }
624:         } else {
625:             getStereotypeFig().setOwner(getOwner());
626: 
627:             if (!getStereotypeFig().isVisible()) {
628:                 getStereotypeFig().setVisible(true);
629: 
630:                 // Only adjust the stereotype height if we are not newly
631:                 // created. This gets round the problem of loading classes with
632:                 // stereotypes defined, which have the height already including
633:                 // the stereotype.
634: 
635:                 if (!newlyCreated) {
636:                     rect.y -= stereoMin.height;
637:                     rect.height += stereoMin.height;
638:                     rect.width = 
639:                         Math.max(getMinimumSize().width, rect.width);
640:                     setBounds(rect.x, rect.y, rect.width, rect.height);
641:                     calcBounds();
642:                 }
643:             }
644:         }
645:         // Whatever happened we are no longer newly created, so clear the
646:         // flag. Then set the bounds for the rectangle we have defined.
647:         newlyCreated = false;
648:     }
649:     protected void updateStereotypeTextSingleStereotype() {
650:         Object me = /*(MModelElement)*/ getOwner();
651: 
652:         if (me == null) {
653:             return;
654:         }
655: 
656:         Rectangle rect = getBounds();
657:         Object stereo = CollectionUtil.getFirstItemOrNull(
658:                 Model.getFacade().getStereotypes(me));
659: 
660:         if ((stereo == null)
661:                 || (Model.getFacade().getName(stereo) == null)
662:                 || (Model.getFacade().getName(stereo).length() == 0))   {
663: 
664:             if (getStereotypeFig().isVisible()) {
665:                 getStereotypeFig().setVisible(false);
666:                 rect.y += STEREOHEIGHT;
667:                 rect.height -= STEREOHEIGHT;
668:                 setBounds(rect.x, rect.y, rect.width, rect.height);
669:                 calcBounds();
670:             }
671:         } else {
672:             getStereotypeFig().setOwner(getOwner());
673: 
674:             if (!getStereotypeFig().isVisible()) {
675:                 getStereotypeFig().setVisible(true);
676: 
677:                 // Only adjust the stereotype height if we are not newly
678:                 // created. This gets round the problem of loading classes with
679:                 // stereotypes defined, which have the height already including
680:                 // the stereotype.
681: 
682:                 if (!newlyCreated) {
683:                     rect.y -= STEREOHEIGHT;
684:                     rect.height += STEREOHEIGHT;
685:                     rect.width = 
686:                         Math.max(getMinimumSize().width, rect.width);
687:                     setBounds(rect.x, rect.y, rect.width, rect.height);
688:                     calcBounds();
689:                 }
690:             }
691:         }
692:         // Whatever happened we are no longer newly created, so clear the
693:         // flag. Then set the bounds for the rectangle we have defined.
694:         newlyCreated = false;
695:     }
