229:     public void mouseClicked(MouseEvent me) {
230:         if (!readyToEdit) {
231:             if (Model.getFacade().isAModelElement(getOwner())) {
232:                 readyToEdit = true;
233:             } else {
234:                 LOG.debug("not ready to edit note");
235:                 return;
236:             }
237:         }
238:         if (me.isConsumed()) {
239:             return;
240:         }
241:         if (me.getClickCount() >= 2
242: 	    && !(me.isPopupTrigger()
243: 		 || me.getModifiers() == InputEvent.BUTTON3_MASK)) {
244:             if (getOwner() == null) {
245:                 return;
246:             }
247:             Fig f = hitFig(new Rectangle(me.getX() - 2, me.getY() - 2, 4, 4));
248:             if (f instanceof MouseListener) {
249:                 ((MouseListener) f).mouseClicked(me);
250:             }
251:         }
252:         me.consume();
253:     }
