192:     /**
193:      * Clone this figure.
194:      *
195:      * @return The cloned figure.
196:      */
197:     public Object clone() {
198:         FigComment figClone = (FigComment) super.clone();
199:         Iterator thisIter = this.getFigs().iterator();
200:         while (thisIter.hasNext()) {
201:             Object thisFig = thisIter.next();
202:             if (thisFig == body) {
203:                 figClone.body = (FigPoly) thisFig;
204:             }
205:             if (thisFig == urCorner) {
206:                 figClone.urCorner = (FigPoly) thisFig;
207:             }
208:             if (thisFig == text) {
209:                 figClone.text = (FigText) thisFig;
210:             }
211:         }
212:         return figClone;
213:     }
