280:     /**
281:      * @see java.beans.PropertyChangeListener#propertyChange(java.beans.PropertyChangeEvent)
282:      */
283:     public void propertyChange(PropertyChangeEvent pve) {
284:         Object src = pve.getSource();
285:         String pName = pve.getPropertyName();
286:         if (pName.equals("editing")
287: 	    && Boolean.FALSE.equals(pve.getNewValue())) {
288:             //parse the text that was edited
289:             textEdited((FigText) src);
290:             // resize the FigNode to accomodate the new text
291:             Rectangle bbox = getBounds();
292:             Dimension minSize = getMinimumSize();
293:             bbox.width = Math.max(bbox.width, minSize.width);
294:             bbox.height = Math.max(bbox.height, minSize.height);
295:             setBounds(bbox.x, bbox.y, bbox.width, bbox.height);
296:             endTrans();
297:         } else {
298:             super.propertyChange(pve);
299:         }
300:     }
