697:     /**
698:      * @see org.tigris.gef.presentation.Fig#getClosestPoint(java.awt.Point)
699:      */
700:     public Point getClosestPoint(Point anotherPt) {
701:         Rectangle r = getBounds();
702:         int xs[] = {r.x, r.x + r.width - dogear, r.x + r.width, 
703:                     r.x + r.width,  r.x,            r.x};
704:         int ys[] = {r.y, r.y,                    r.y + dogear,
705:                     r.y + r.height, r.y + r.height, r.y};
706:         Point p = Geometry.ptClosestTo(
707:                 xs, 
708:                 ys,
709:                 6 , anotherPt);
710:         return p;
711:     }
