526:         if (SingleStereotypeEnabler.isEnabled()) {
527:             getStereotypeFig().setBounds(px + 2, py + 2,
528:                     w - 4 - dogear, STEREOHEIGHT);
529:         } else {
530:             getStereotypeFig().setBounds(px + 2, py + 2,
531:                     w - 4 - dogear, stereoMin.height);
532:         }
533:         
534:         // Resize the big port around the figure
535:         getBigPort().setBounds(px, py, w, h);
536: 
537:         // Since this is a complex polygon, there's no easy way to resize it.
538:         Polygon newPoly = new Polygon();
539:         newPoly.addPoint(px, py);
540:         newPoly.addPoint(px + w - 1 - dogear, py);
541:         newPoly.addPoint(px + w - 1, py + dogear);
542:         newPoly.addPoint(px + w - 1, py + h - 1);
543:         newPoly.addPoint(px, py + h - 1);
