686:                         Math.max(getMinimumSize().width, rect.width);
687:                     setBounds(rect.x, rect.y, rect.width, rect.height);
688:                     calcBounds();
689:                 }
690:             }
691:         }
692:         // Whatever happened we are no longer newly created, so clear the
693:         // flag. Then set the bounds for the rectangle we have defined.
694:         newlyCreated = false;
