600:     protected void updateStereotypeText() {
601:         if (SingleStereotypeEnabler.isEnabled()) {
602:             updateStereotypeTextSingleStereotype();
603:             return;
604:         }
605:         Object me = /*(MModelElement)*/ getOwner();
606: 
607:         if (me == null) {
608:             return;
609:         }
610: 
611:         Rectangle rect = getBounds();
612: 
613:         Dimension stereoMin = getStereotypeFig().getMinimumSize();
