99:     public boolean shouldBeEnabled() {
100:         
101:         Object target = ProjectBrowser.TheInstance.getTarget();
102:         if(target instanceof MNamespace)
103:             return isValidNamespace((MNamespace)target);
104:         else
105:             return false;
106:     }
