98:     public DefaultHandler getHandler(HandlerStack stack,
99:                                              Object container,
100:                                              String uri,
101:                                              String localname,
102:                                              String qname,
103:                                              Attributes attributes)
104:         throws SAXException {
105: 
106:         // Ignore non-private elements within FigNode groups
107:         if (container instanceof FigGroupHandler) {
