136:     protected final void setAttrs(Fig f, Attributes attrList)
137:         throws SAXException {
138:         
139:         if (f instanceof FigGroup) {
140:             FigGroup group = (FigGroup) f;
141:             String clsNameBounds = attrList.getValue("description");
142:             if (clsNameBounds != null) {
143:                 StringTokenizer st =
144:                     new StringTokenizer(clsNameBounds, ",;[] ");
145:                 // Discard class name, x y w h
146:                 if (st.hasMoreElements()) {
147:                     st.nextToken();
148:                 }
149:                 if (st.hasMoreElements()) {
150:                     st.nextToken();
151:                 }
152:                 if (st.hasMoreElements()) {
153:                     st.nextToken();
154:                 }
155:                 if (st.hasMoreElements()) {
156:                     st.nextToken();
157:                 }
158:                 if (st.hasMoreElements()) {
159:                     st.nextToken();
160:                 }
161: 
162:                 Map attributeMap = interpretStyle(st);
163:                 setStyleAttributes(group, attributeMap);
164:             }
165:         }
166: 
167:         // TODO: Attempt to move the following code to GEF
168: 
169:         String name = attrList.getValue("name");
170:         if (name != null && !name.equals("")) {
171:             registerFig(f, name);
172:         }
173: 
174:         setCommonAttrs(f, attrList);
175: 
176:         String href = attrList.getValue("href");
177:         if (href != null && !href.equals("")) {
178:             Object modelElement = findOwner(href);
179:             if (modelElement == null) {
180:                 LOG.error("Can't find href of " + href);
181:                 throw new SAXException("Found href of " + href
182: 				       + " with no matching element in model");
183:             }
184:             if (f.getOwner() != modelElement) {
185:                 // Assign nodes immediately but edges later. See issue 4310.
186:                 if (f instanceof FigEdge) {
187:                     modelElementsByFigEdge.put(f, modelElement);
