364:     private void depthFirst(Object node, Diagram lastDiagram) {
365: 	if (node instanceof Diagram) {
366: 	    lastDiagram = (Diagram) node;
367: 	    if (!pred.matchDiagram(lastDiagram))
368: 		return;
369: 	    // diagrams are not placed in search results
370: 	}
371: 	Enumeration elems = cg.gen(node);
372: 	while (elems.hasMoreElements()) {
373: 	    Object c = elems.nextElement();
374: 	    if (pred.predicate(c)) {
375: 		results.addElement(c);
376: 		diagrams.addElement(lastDiagram);
377: 	    }
378: 	    depthFirst(c, lastDiagram);
379: 	}
380:     }
