581:     /**
582:      * @see org.argouml.uml.diagram.ui.FigNodeModelElement#updateStereotypeText()
583:      */
584:     protected void updateStereotypeText() {
585:         Object me = /*(MModelElement)*/ getOwner();
586: 
587:         if (me == null) {
588:             return;
589:         }
590: 
591:         Rectangle rect = getBounds();
592: 
593:         Dimension stereoMin = getStereotypeFig().getMinimumSize();
594:         
595:         if (Model.getFacade().getStereotypes(me).isEmpty()) {
596: 
597:             if (getStereotypeFig().isVisible()) {
598:                 getStereotypeFig().setVisible(false);
599:                 rect.y += stereoMin.height;
600:                 rect.height -= stereoMin.height;
601:                 setBounds(rect.x, rect.y, rect.width, rect.height);
602:                 calcBounds();
603:             }
604:         } else {
605:             getStereotypeFig().setOwner(getOwner());
606: 
607:             if (!getStereotypeFig().isVisible()) {
608:                 getStereotypeFig().setVisible(true);
609: 
610:                 // Only adjust the stereotype height if we are not newly
611:                 // created. This gets round the problem of loading classes with
612:                 // stereotypes defined, which have the height already including
613:                 // the stereotype.
614: 
615:                 if (!newlyCreated) {
616:                     rect.y -= stereoMin.height;
617:                     rect.height += stereoMin.height;
618:                     rect.width = 
619:                         Math.max(getMinimumSize().width, rect.width);
620:                     setBounds(rect.x, rect.y, rect.width, rect.height);
621:                     calcBounds();
622:                 }
623:             }
624:         }
625:         // Whatever happened we are no longer newly created, so clear the
626:         // flag. Then set the bounds for the rectangle we have defined.
627:         newlyCreated = false;
628:     }
