1702:     if (_curModel != null) _curModel.addPublicOwnedElement(me);
1703:     else if (_proj != null && me instanceof Model) {
1704:       //System.out.println("Adding top-level model");
1705:       addTopModel(me);
1706:     }
1707:     else if (me instanceof Classifier) {
1708:       _proj.defineType((Classifier)me);
1709:     }
1710:     else {
1711:       System.out.println("trying to add to null model:" + me);
1712:       System.out.println("id:" + me.getId());
1713:     }
1714:   }
