710:     if (inTag("AssociationEnd") && _curAssociationEnd != null)
711:       _curAssociationEnd.setMultiplicity(m);
712:     else if (inTag("AssociationEndRole") && _curAssociationEndRole != null)
713:       _curAssociationEndRole.setMultiplicity(m);
714:     else if (inTag("Attribute") && _curAttribute != null)
715:       _curAttribute.setMultiplicity(m);
716:     else if (inTag("AssociationRole") && _curAssociationRole != null)
717:       _curAssociationRole.setMultiplicity(m);
718:     else if (inTag("ClassifierRole") && _curClassifierRole != null)
719:       _curClassifierRole.setMultiplicity(m);
720:     else System.out.println("unknown context for multiplicity: " + multStr);
721:   }
722:   /** Parse a string of the form: "range, ...", where range is of the
723:    *  form "lower..upper", or "integer" */
724:   public Multiplicity parseMultiplicity(String s) {
725:     s = s.trim();
726:     if (s.length() == 0) return Multiplicity.ONE;
727:     Multiplicity m = new Multiplicity();
728:     StringTokenizer st1 = new StringTokenizer(s, ",");
729:     while (st1.hasMoreElements()) {
730:       String range = st1.nextToken().trim();
731:       String lowStr = "", highStr = "";
732:       Integer low = null, high = null;
733:       int dotdot = range.indexOf("..");
734:       if (dotdot == -1) {
735: 	lowStr = range;
736: 	highStr = range;
737:       }
738:       else {
739: 	lowStr = range.substring(0, dotdot);
740: 	highStr = range.substring(dotdot + 2);
741:       }
742:       try {
743: 	if (lowStr.indexOf("*") == -1) low = Integer.valueOf(lowStr);
744: 	if (highStr.indexOf("*") == -1) high = Integer.valueOf(highStr);
745: 	MultiplicityRange mr = new MultiplicityRange(low, high);
746: 	m.addRange(mr);
747:       }
748:       catch (NumberFormatException nfe) { }
749:     }
750:     return m;
751:   }
