258:     /**
259:      * Loads a model (XMI only) from a .zargo file. BE ADVISED this
260:      * method has a side effect. It sets _UUIDREFS to the model.
261:      * 
262:      * If there is a problem with the xmi file, an error is set in the
263:      * ArgoParser.SINGLETON.getLastLoadStatus() field. This needs to be
264:      * examined by the calling function.
265:      *
266:      * @param url The url with the .zargo file
267:      * @return MModel The model loaded
268:      * @throws IOException Thrown if the model or the .zargo file is corrupted.
269:      * @throws SAXException If the parser template is syntactically incorrect. 
270:      * @throws ParserConfigurationException If the initialization of 
271:      *         the parser fails.
272:      */
273:     protected Object loadModelFromXMI(URL url)
274:         throws IOException, SAXException, ParserConfigurationException {
275:         ZipInputStream zis = new ZipInputStream(url.openStream());
276: 
277:         String name = zis.getNextEntry().getName();
278:         while (!name.endsWith(".xmi")) {
279:             name = zis.getNextEntry().getName();
280:         }
281:         
282:         if (LOG.isInfoEnabled()) {
283:             LOG.info("Loading Model from " + url);
284:         }
285:         // 2002-07-18
286:         // Jaap Branderhorst
287:         // changed the loading of the projectfiles to solve hanging 
288:         // of argouml if a project is corrupted. Issue 913
289:         // Created xmireader with method getErrors to check if parsing went well
290:         XMIReader xmiReader = null;
291:         try {
292:             xmiReader = new XMIReader();
293:         } catch (SAXException se) { // duh, this must be caught and handled
294:             LOG.error("SAXException caught", se);
295:             throw se;
296:         } catch (ParserConfigurationException pc) { 
297: 	        // duh, this must be caught and handled
298:             LOG.error("ParserConfigurationException caught", pc);
299:             throw pc;
300:         }
301:         Object mmodel = null;
302: 
303:         InputSource source = new InputSource(zis);
304:         source.setEncoding("UTF-8");
305:         mmodel = xmiReader.parseToModel(source);        
306:         if (xmiReader.getErrors()) {
307:             ArgoParser.SINGLETON.setLastLoadStatus(false);
308:             ArgoParser.SINGLETON.setLastLoadMessage("XMI file " + url
309: 						    + " could not be parsed.");
310:             LOG.error("XMI file " + url + " could not be parsed.");
311:             throw new SAXException("XMI file " + url + " could not be parsed.");
312:         }
313: 
314:         // This should probably be inside xmiReader.parse
315:         // but there is another place in this source
316:         // where XMIReader is used, but it appears to be
317:         // the NSUML XMIReader.  When Argo XMIReader is used
318:         // consistently, it can be responsible for loading
319:         // the listener.  Until then, do it here.
320:         UmlHelper.getHelper().addListenersToModel(mmodel);
321: 
322:         addMember(mmodel);
323: 
324:         uuidRefs = new HashMap(xmiReader.getXMIUUIDToObjectMap());
325:         return mmodel;
326:     }
