1095:     /**
1096:      * Removes some object from the project. Does not update GUI since
1097:      * this method only handles project management.
1098:      * @param obj
1099:      *
1100:      * <p>Attention: whole Trash mechanism should be rethought concerning nsuml
1101:      * 
1102:      * <p>Note that at present these are all if, not
1103:      * else-if. Rather than make a big change, I've just explicitly dealt with
1104:      * the case where we have a use case that is not classifier.
1105:      */
1106:     protected void trashInternal(Object obj) {
1107:         boolean needSave = false;
1108:         if (obj != null) {
1109:             TargetManager.getInstance().removeTarget(obj);
1110:             TargetManager.getInstance().removeHistoryElement(obj);
1111:             Trash.SINGLETON.addItemFrom(obj, null);
1112:         }
1113:         if (ModelFacade.isABase(obj)) { // an object that can be represented
1114:             ProjectBrowser.getInstance().getEditorPane()
1115:         		.removePresentationFor(obj, getDiagrams());
1116:             // UmlModelEventPump.getPump().stopPumpingEvents();
1117:             UmlFactory.getFactory().delete(obj);
1118:             // UmlModelEventPump.getPump().startPumpingEvents();
1119:             if (members.contains(obj)) {
1120:                 members.remove(obj);
1121:             }
1122:             if (_models.contains(obj)) {
1123:                 _models.remove(obj);
1124:             }           
1125:             needSave = true;
1126:         } else {
1127:             if (obj instanceof ArgoDiagram) {
1128:                 removeProjectMemberDiagram((ArgoDiagram) obj);
1129:                 needSave = true;
1130:                 // only need to manually delete diagrams because they
1131:                 // don't have a decent event system set up.
1132:                 ExplorerEventAdaptor.getInstance().modelElementRemoved(obj);
1133:             }
1134:             if (obj instanceof Fig) {
1135:                 ((Fig) obj).dispose();
1136:                 needSave = true;
1137:                 // for explorer deletion:
1138:                 obj = ((Fig) obj).getOwner();
1139:             }
1140:         }        
1141:         setNeedsSave(needSave);
1142:     }
