318:     /**
319:      * Sets the selection state for a given set of targets.
320:      */
321:     private void setSelection(Object[] targets) {
322:         updatingSelectionViaTreeSelection = true;
323: 
324:         this.clearSelection();
325:         int rows = getRowCount();
326:         for (int i = 0; i < targets.length; i++) {
327:             Object target = targets[i];
328:             target =
329: 		target instanceof Fig ? ((Fig) target).getOwner() : target;
330:             for (int j = 0; j < rows; j++) {
331:                 Object rowItem =
332: 		    ((DefaultMutableTreeNode) getPathForRow(j)
333: 		            .getLastPathComponent()).getUserObject();
334:                 if (rowItem == target) {
335:                     this.addSelectionRow(j);
336:                 }
337:             }
338:         }
339:         updatingSelectionViaTreeSelection = false;
340:         
341:         if (this.getSelectionCount() > 0) {
342:             scrollRowToVisible(this.getSelectionRows()[0]);
343:         }
344:     }
