322:         updatingSelectionViaTreeSelection = true;
323: 
324:         this.clearSelection();
325:         int rows = getRowCount();
326:         for (int i = 0; i < targets.length; i++) {
327:             Object target = targets[i];
328:             target =
329: 		target instanceof Fig ? ((Fig) target).getOwner() : target;
