346:     /**
347:      * Manages selecting the item to show in Argo's other
348:      * views based on the highlighted row.
349:      */
350:     class NavigationTreeSelectionListener implements TreeSelectionListener {
351: 
352:         /**
353:          * Change in nav tree selection -> set target in target manager.
354:          */
355:         public void valueChanged(TreeSelectionEvent e) {
356: 
357:             if (!updatingSelectionViaTreeSelection) {
358:                 updatingSelectionViaTreeSelection = true;
359: 
360:                 // get the elements
361:                 TreePath[] addedOrRemovedPaths = e.getPaths();
362:                 TreePath[] selectedPaths = getSelectionPaths();
363:                 List elementsAsList = new ArrayList();
364:                 for (int i = 0;
365:                     selectedPaths != null && i < selectedPaths.length; i++) {
366:                     Object element = ((DefaultMutableTreeNode) selectedPaths[i]
367:                                    .getLastPathComponent()).getUserObject();
368:                     elementsAsList.add(element);
369: //                  // scan the visible rows for duplicates of
370:                     // this elem and select them
371:                     int rows = getRowCount();
372:                     for (int row = 0; row < rows; row++) {
373:                         Object rowItem =
374: 			    ((DefaultMutableTreeNode) getPathForRow(row)
375: 			            .getLastPathComponent())
376: 			            .getUserObject();
377:                         if (rowItem == element
378: 			    && !(isRowSelected(row))) {
379:                             addSelectionRow(row);
380:                         }
381:                     }
382:                 }
383: 
384:                 // check which targetmanager method to call
385: 
386: 
387:                 boolean callSetTarget = true;
388:                 List addedElements = new ArrayList();
389:                 for (int i = 0; i < addedOrRemovedPaths.length; i++) {
390:                     Object element = ((DefaultMutableTreeNode)
391:                             addedOrRemovedPaths[i].getLastPathComponent())
392:                             .getUserObject();
393:                     if (!e.isAddedPath(i)) {
394:                         callSetTarget = false;
395:                         break;
396:                     }
397:                     addedElements.add(element);
398:                 }
399: 
400:                 if (callSetTarget && addedElements.size()
401:                         == elementsAsList.size()
402:                         && elementsAsList.containsAll(addedElements)) {
403:                     TargetManager.getInstance().setTargets(elementsAsList);
404:                 } else {
405:                     // we must call the correct method on targetmanager
406:                     // for each added or removed target
407:                     List removedTargets = new ArrayList();
408:                     List addedTargets = new ArrayList();
409:                     for (int i = 0; i < addedOrRemovedPaths.length; i++) {
410:                         Object element = ((DefaultMutableTreeNode)
411:                                 addedOrRemovedPaths[i]
412:                              .getLastPathComponent()).getUserObject();
413:                         if (e.isAddedPath(i)) {
414:                             addedTargets.add(element);
415:                         } else {
416:                             removedTargets.add(element);
417:                         }
418:                     }
419:                     // we can't remove the targets one by one, we have to
420:                     // do it in one go.
421:                     if (!removedTargets.isEmpty()) {
422:                         Iterator it = removedTargets.iterator();
423:                         while (it.hasNext()) {
424:                             TargetManager.getInstance().removeTarget(it.next());
425:                         }
426:                     }
427:                     if (!addedTargets.isEmpty()) {
428:                         Iterator it = addedTargets.iterator();
429:                         while (it.hasNext()) {
430:                             TargetManager.getInstance().addTarget(it.next());
431:                         }
432:                     }
433:                 }
434: 
435:                 updatingSelectionViaTreeSelection = false;
436:             }
437:         }
438:     }
