129:             Object dm = toCritique.elementAt(toCritique.size()-1);
130:             toCritique.removeElement(dm);
131:             if (!alreadyCritiqued.contains(dm)) {
132:               alreadyCritiqued.addElement(dm);
133:               Agency.applyAllCritics(dm, theDesigner());
134:               Enumeration subDMs = _cg.gen(dm);
135:               while (subDMs.hasMoreElements())
136:                 toCritique.addElement(subDMs.nextElement());
137:             }
138:           }
139:         }
140:       }
141:       // needs-more-work: limit % CPU time used
142:       try { _critiquer.sleep(getCritiquingInterval()); }
143:       catch (InterruptedException ignore) {
144:         System.out.println("InterruptedException!!!");
145:       }
146:     }
147:   }
