66: 	// don't forget to remove old Operations!
67: 	for (int i = 0; i < oldOps.size(); i++)
68: 		((MOperation)oldOps.elementAt(i)).remove();
69: 	features.addAll(newOps);
70: 	cls.setFeatures(features);
