96:    *  [visibility] [keywords] returntype name(params)[;] */
97:   public MOperation parseOperation(String s) {
98:     s = s.trim();
99:     if (s.endsWith(";")) s = s.substring(0, s.length()-1);
100:     MOperation res = new MOperationImpl();
101:     s = parseOutVisibility(res, s);
102:     s = parseOutKeywords(res, s);
103:     s = parseOutReturnType(res, s);
104:     s = parseOutName(res, s);
105:     s = parseOutParams(res, s);
106:     s = s.trim();
107:     if (s.length() > 2)
108:       System.out.println("leftover in parseOperation=|" + s + "|");
109:     return res;
110:   }
