135:   public String parseOutVisibility(MFeature f, String s) {
136:     s = s.trim();
137:     int firstSpace = s.indexOf(" ");
138:     if (firstSpace == -1) firstSpace = s.length();
139:     String visStr = s.substring(0, firstSpace);
140:     MVisibilityKind vk = MVisibilityKind.PUBLIC;
141:     if (visStr.equals("public") || s.startsWith("+"))
142:       vk = MVisibilityKind.PUBLIC;
143:     else if (visStr.equals("private") || s.startsWith("-"))
144:       vk = MVisibilityKind.PRIVATE;
145:     else if (visStr.equals("protected") || s.startsWith("#"))
146:       vk = MVisibilityKind.PROTECTED;
147: 	//    else if (visStr.equals("package") || s.startsWith("~"))
148: 	// vk = MVisibilityKind.PACKAGE;
149:     else {
150:       System.out.println("unknown visibility \"" + visStr +
151: 			 "\", using default");
152:       return s;
153:     }
154:      f.setVisibility(vk);
155: 
156:     if (s.startsWith("+") || s.startsWith("-") ||
157: 	s.startsWith("#") || s.startsWith("~"))
158:       s = s.substring(1);
159:     else
160:       s = s.substring(firstSpace+1);
161:     return s;
162:   }
