483:       name = s.substring(0, s.indexOf(":")).trim();
484:       basefirst = s.substring(s.indexOf(":") + 1).trim();
485:       if (basefirst.indexOf(":", 0) > 1) {
486:         base = basefirst.substring(0, basefirst.indexOf(":")).trim();
487:       }
488:       else base = basefirst;
489:     }
490:     else {
491:       name = s;
492:     }
