649:     private void addActivations() {
650:         MessageNode startActivationNode = null;
651:         MessageNode endActivationNode = null;
652:         int lastState = MessageNode.INITIAL;
653:         boolean startFull = false;
654:         boolean endFull = false;
655:         int nodeCount = linkPositions.size();
656:         int x = lifeLine.getX() - WIDTH / 2;
657:         for (int i = 0; i < nodeCount; ++i) {
658:             MessageNode node = (MessageNode) linkPositions.get(i);
659:             int nextState = node.getState();
660:             if (lastState != nextState && nextState == MessageNode.CREATED) {
661:                 FigRect birthFig =
662: 		    new FigRect(lifeLine.getX() - WIDTH / 2,
663: 				getYCoordinate(i)
664: 				- SequenceDiagramLayout.LINK_DISTANCE / 4,
665: 				WIDTH,
666: 				SequenceDiagramLayout.LINK_DISTANCE / 4);
667:                 birthFig.setFilled(true);
668:                 birthFig.setFillColor(Color.BLACK);
669:                 addActivationFig(birthFig);
670:             }
671:             if (lastState != nextState && nextState == MessageNode.DESTROYED) {
672:                 int y =
673: 		    getYCoordinate(i) - SequenceDiagramLayout.LINK_DISTANCE / 2;
674:                 addActivationFig(
675: 			new FigLine(x,
676: 				    y + SequenceDiagramLayout.LINK_DISTANCE / 2,
677: 				    x + WIDTH,
678: 				    y + SequenceDiagramLayout.LINK_DISTANCE));
679:                 addActivationFig(
680: 			new FigLine(x,
681: 				    y + SequenceDiagramLayout.LINK_DISTANCE,
682: 				    x + WIDTH,
683: 				    y
684: 				    + SequenceDiagramLayout.LINK_DISTANCE / 2));
685:             }
686:             if (startActivationNode == null) {
687:                 switch (nextState) {
688: 		case MessageNode.DONE_SOMETHING_NO_CALL:
689: 		    startActivationNode = node;
690: 		    startFull = true;
691: 		    break;
692: 		case MessageNode.CALLED:
693: 		case MessageNode.CREATED:
694: 		    startActivationNode = node;
695: 		    startFull = false;
696:                 default:
697:                 }
698:             } else {
699:                 switch (nextState) {
700: 		case MessageNode.DESTROYED :
701: 		case MessageNode.RETURNED :
702: 		    endActivationNode = node;
703: 		    endFull = false;
704: 		    break;
705: 		case MessageNode.IMPLICIT_RETURNED :
706: 		case MessageNode.IMPLICIT_CREATED :
707: 		    endActivationNode = (MessageNode) linkPositions.get(i - 1);
708: 		    endFull = true;
709: 		    break;
710: 		case MessageNode.CALLED :
711: 		    if (lastState == MessageNode.CREATED) {
712: 			endActivationNode =
713: 			    (MessageNode) linkPositions.get(i - 1);
714: 			endFull = false;
715: 			--i;
716: 			nextState = lastState;
717: 		    }
718: 		    break;
719: 		default:
720:                 }
721:             }
722:             lastState = nextState;
723:             if (startActivationNode != null && endActivationNode != null) {
724:                 if (startActivationNode != endActivationNode
725: 		    || startFull || endFull) {
726:                     int y1 = getYCoordinate(startActivationNode);
727:                     if (startFull) {
728:                         y1 -= SequenceDiagramLayout.LINK_DISTANCE / 2;
729:                     }
730:                     int y2 = getYCoordinate(endActivationNode);
731:                     if (endFull) {
732:                         y2 += SequenceDiagramLayout.LINK_DISTANCE / 2;
733:                     }
734:                     addActivationFig(new FigRect(x, y1, WIDTH, y2 - y1));
735:                 }
736:                 startActivationNode = null;
737: 		endActivationNode = null;
738:                 startFull = false;
739: 		endFull = false;
740:             }
741:         }
742:         if (startActivationNode != null) {
743:             endActivationNode = (MessageNode) linkPositions.get(nodeCount - 1);
744:             endFull = true;
745:             int y1 = getYCoordinate(startActivationNode);
746:             if (startFull) {
747:                 y1 -= SequenceDiagramLayout.LINK_DISTANCE / 2;
748:             }
749:             int y2 = getYCoordinate(endActivationNode);
750:             if (endFull) {
751:                 y2 += SequenceDiagramLayout.LINK_DISTANCE / 2;
752:             }
753:             addActivationFig(new FigRect(x, y1, WIDTH, y2 - y1));
754:             startActivationNode = null;
755: 	    endActivationNode = null;
756:             startFull = false;
757: 	    endFull = false;
758:         }
759:     }
