1346: 	    throws SAXException {
1347: 
1348:             DefaultHandler result = null;
1349:             String description;
1350:             // Handle stereotype groups in Figs
1351:             if (qname.equals("group")
1352:                     && ((description = attributes.getValue("description"))
1353:                             != null)
1354:                     && description.startsWith(FigMessagePort.class.getName())) {
1355:                 FigMessagePort fmp = new FigMessagePort();
1356:                 ((FigGroupHandler) container).getFigGroup().addFig(fmp);
1357:                 result = new FigGroupHandler((PGMLStackParser) stack, fmp);
1358:                 PGMLStackParser parser = (PGMLStackParser) stack;
1359:                 PGMLStackParser.setCommonAttrs(fmp, attributes);
1360:                 String ownerRef = attributes.getValue("href");
1361:                 if (ownerRef != null) {
1362:                     Object owner = parser.findOwner(ownerRef);
1363:                     if (owner != null) {
1364:                         fmp.setOwner(owner);
