110:     private static Object findNamespace(Object/*MNamespace*/ phantomNS, Object/*MModel*/ targetModel) {
111:         Object/*MNamespace*/ ns = null;
112:         Object/*MNamespace*/ targetParentNS = null;
113:         Object/*MNamespace*/ parentNS = ModelFacade.getNamespace(phantomNS);
114:         if (parentNS == null) {
115:             ns = targetModel;
116:         }
117:         else {
118:             targetParentNS = findNamespace(parentNS, targetModel);
119:             //
120:             //   see if there is already an element with the same name
121:             //
