222:         if (element == _element && _element != null) {
223:             Object/*MNamespace*/ ns = ModelFacade.getNamespace(_element);
224:             _shortName = _profile.formatElement(_element, ns);
225:             _displayName = _shortName;
226:             _longName = null;
227:         }
228:     }
