56: /**
57:  * UMLAddDialog allows the user to do a multiple select from a list of
58:  * choices in a separate dialog. The dialog has two possible uses:<ol>
59:  *
60:  * <li>As dialog as described above with a custom cellrenderer or a
61:  * default cellrenderer.
62:  *
63:  * <li>As dialog with a UMLCellRenderer. Cells in the choices list and
64:  * selected list are presented with their name instead of their
65:  * toString function.
66:  * </ol>
67:  */
68: public class UMLAddDialog extends JPanel implements ActionListener {
69: 	
70:     /**
71:      * The choices a user has
72:      */
73:     protected Vector _choices = null;
74:     /**
75:      * The preselected choices
76:      */
77:     protected Vector _preSelected = null;
78:     /**
79:      * The selected choices.
80:      */
81:     protected Vector _selected = null;
82: 	
83:     /**
84:      * The GUI list for the choices
85:      */
86:     protected JList _choicesList = null;
87:     /**
88:      * The GUI list for the selected choices
89:      */
90:     protected JList _selectedList = null;
91:     protected JButton _addButton = null;
92:     protected JButton _removeButton = null;
93:     protected JButton _okButton = null;
94:     protected JButton _cancelButton = null;
95: 	
96:     protected JDialog _dialog = null;
97:     protected String _title = null;
98: 
99:     /**
100:      * The returnvalue of the method showDialog. Returnvalue can be
101:      * either JOptionPane.OK_OPTION or JOptionPane.CANCEL_OPTION
102:      */
103:     protected int _returnValue;
104: 	
105:     /**
106:      * Constructs a UMLAddDialog with a
107:      * UMLListCellRenderer. Modelelements are represented with their
108:      * names in the choices list and the selected list.
109:      *
110:      * @param choices A vector with the choices a user has.
111:      * @param selected A vector with allready preselected choices
112:      * @param title The title of the dialog
113:      * @param multiselectAllowed True if the user may select multiple choices
114:      * @param exclusive True if choices in the selected list may not
115:      *                  appear in the choices list. If true preselected
116:      *                  choices are removed from the choices list.
117:      */
118:     public UMLAddDialog(Vector choices, Vector selected, String title,
119: 			boolean multiselectAllowed, boolean exclusive) {
120: 	this(choices, selected, title, new UMLListCellRenderer2(true),
121: 	     multiselectAllowed, exclusive);
122:     }	
123: 	
124:     /**
125:      * Constructs a UMLAddDialog with a given UMLListCellRenderer. 
126:      *
127:      * @param choices A vector with the choices a user has.
128:      * @param selected A vector with allready preselected choices
129:      * @param title The title of the dialog
130:      * @param renderer The cellrenderer of the choices list and the
131:      * selected list
132:      * @param multiselectAllowed True if the user may select multiple choices
133:      * @param exclusive True if choices in the selected list may not
134:      * appear in the choices list. If true preselected choices are
135:      * removed from the choices list.
136:      */
137:     public UMLAddDialog(Vector choices, Vector selected, String title,
138: 			ListCellRenderer renderer,
139: 			boolean multiselectAllowed, boolean exclusive) {
140: 	if (choices == null) {
141: 	    throw new IllegalArgumentException("There should allways be choices in UMLAddDialog");
142: 	}
143: 	if (exclusive && selected != null && !selected.isEmpty()) {
144: 	    choices.removeAll(selected);
145: 	}
146: 	_choices = choices;
147: 	_preSelected = selected;
148: 	_selected = new Vector();
149: 	if (title != null) {
150: 	    _title = title;
151: 	} else {
152: 	    _title = "";
153: 	}
154: 	if (selected != null) {
155: 	    _selected.addAll(selected);
156: 	}
157: 		
158: 	setLayout(new BorderLayout());
159: 		
160: 	JPanel upperPanel = new JPanel();	
161: 	JPanel panelChoices = new JPanel(new BorderLayout());
162: 	JPanel panelSelected = new JPanel(new BorderLayout());
163: 		
164: 		
165: 	_choicesList = new JList(constructListModel(choices));
166: 	_choicesList.setMinimumSize(new Dimension(150,300));
167: 	if (renderer != null) {
168: 	    _choicesList.setCellRenderer(renderer);
169: 	}
170: 	if (multiselectAllowed) {
171: 	    _choicesList.setSelectionMode(ListSelectionModel.MULTIPLE_INTERVAL_SELECTION);
172: 	} else {
173: 	    _choicesList.setSelectionMode(ListSelectionModel.SINGLE_SELECTION);
174: 	}
175: 	_choicesList.setVisibleRowCount(15);
176: 	JScrollPane choicesScroll = new JScrollPane(_choicesList);
177: 	panelChoices.add(new JLabel(Translator.localize("UMLMenu", "label.choices")), BorderLayout.NORTH);
178: 	panelChoices.add(choicesScroll, BorderLayout.CENTER);
179: 		
180: 	_addButton = new JButton(ResourceLoaderWrapper.lookupIconResource("NavigateForward"));
181: 	_addButton.addActionListener(this);
182: 	_removeButton = new JButton(ResourceLoaderWrapper.lookupIconResource("NavigateBack"));
183: 	_removeButton.addActionListener(this);
184: 	Box buttonBox = Box.createVerticalBox();
185: 	// buttonBox.add(Box.createRigidArea(new Dimension(0, 20)));
186: 	buttonBox.add(_addButton);
187: 	buttonBox.add(Box.createRigidArea(new Dimension(0, 5)));
188: 	buttonBox.add(_removeButton);
189: 		
190: 	_selectedList = new JList(constructListModel(_selected));	
191: 	_selectedList.setMinimumSize(new Dimension(150,300));
192: 	if (renderer != null) {
193: 	    _selectedList.setCellRenderer(renderer);
194: 	}
195: 	_selectedList.setSelectionMode(ListSelectionModel.MULTIPLE_INTERVAL_SELECTION);
196: 	_selectedList.setVisibleRowCount(15);
197: 	JScrollPane selectedScroll = new JScrollPane(_selectedList);
198: 	panelSelected.add(new JLabel(Translator.localize("UMLMenu", "label.selected")), BorderLayout.NORTH);
199: 	panelSelected.add(selectedScroll, BorderLayout.CENTER);
200: 		
201: 	upperPanel.add(panelChoices);	
202: 	upperPanel.add(Box.createRigidArea(new Dimension(5, 0)));
203: 	upperPanel.add(buttonBox);
204: 	upperPanel.add(Box.createRigidArea(new Dimension(5, 0)));
205: 	upperPanel.add(panelSelected);	
206: 	// upperPanel.setBorder(BorderFactory.createEtchedBorder());
207: 		
208: 	add(upperPanel, BorderLayout.NORTH);
209: 		
210: 		
211: 	JPanel okCancelPanel = new JPanel(new FlowLayout(FlowLayout.RIGHT));
212: 		
213: 	_okButton = new JButton(Translator.localize("UMLMenu", "button.ok"));
214: 	_okButton.addActionListener(this);
215: 	_cancelButton =
216: 	    new JButton(Translator.localize("UMLMenu", "button.cancel"));
217: 	_cancelButton.addActionListener(this);		
218: 	okCancelPanel.add(_okButton);
219: 	okCancelPanel.add(_cancelButton);
220: 	okCancelPanel.setBorder(BorderFactory.createEmptyBorder(10, 0, 10, 10));
221: 		
222: 	add(okCancelPanel, BorderLayout.SOUTH);
223: 	setBorder(BorderFactory.createEmptyBorder(20, 10, 20, 10));
224: 	update();
225:     }
226: 	
227:     /**
228:      * @see java.awt.event.ActionListener#actionPerformed(ActionEvent)
229:      */
230:     public void actionPerformed(ActionEvent e) {
231: 	Object source = e.getSource(); 
232: 	if (source.equals(_addButton)) {
233: 	    addSelection();
234: 	    update();
235: 	}
236: 	if (source.equals(_removeButton)) {
237: 	    removeSelection();
238: 	    update();
239: 	}
240: 	if (source.equals(_okButton)) {
241: 	    ok();
242: 	}
243: 	if (source.equals(_cancelButton)) {
244: 	    cancel();
245: 	}
246:     }
247: 	
248:     /**
249:      * Updates the add and remove button (sets
250:      * enabled/disabled). Called whenever the model is changed.
251:      */
252:     public void update() {
253: 	if (_choices.size() == 0) {
254: 	    _addButton.setEnabled(false);
255: 	} else {
256: 	    _addButton.setEnabled(true);
257: 	}
258: 	if (_selected.size() == 0) {
259: 	    _removeButton.setEnabled(false);
260: 	} else {
261: 	    _removeButton.setEnabled(true);
262: 	}
263:     }
264: 	
265:     /**
266:      * Utility method to construct a DefaultListModel from a Vector
267:      * @param vec
268:      * @return DefaultListModel
269:      */
270:     protected DefaultListModel constructListModel(Vector vec) {
271: 	DefaultListModel model = new DefaultListModel();
272: 	for (int i = 0; i < vec.size(); i++) {
273: 	    model.addElement(vec.get(i));
274: 	}
275: 	return model;		
276:     }
277: 	
278:     /**
279:      * Shows the dialog. First a dialog must be constructed using one
280:      * of the constructors of this class.  After that this method
281:      * should be called to actually show the dialog. This method
282:      * returns either JOptionPane.OK_OPTION if the user wants to
283:      * select his choices or JOptionPane.CANCEL_OPTION if he does not
284:      * want to.
285:      *
286:      * @param parent The parent frame of this dialog.
287:      * @return int The returnvalue, can be either
288:      * JOptionPane.OK_OPTION or JOptionPane.CANCEL_OPTION
289:      */
290:     public int showDialog(Component parent) {
291: 	Frame frame = parent instanceof Frame ? (Frame) parent
292: 	    : (Frame) SwingUtilities.getAncestorOfClass(Frame.class, parent);
293: 
294: 	// String title = getUI().getDialogTitle(this);
295: 
296:         _dialog = new JDialog(frame, _title, true);
297:         Container contentPane = _dialog.getContentPane();
298:         contentPane.setLayout(new BorderLayout());
299:         contentPane.add(this, BorderLayout.CENTER);
300:  
301: 	_dialog.setDefaultCloseOperation(JDialog.DO_NOTHING_ON_CLOSE);
302: 	_dialog.addWindowListener(new WindowAdapter() {
303:     	    public void windowClosing(WindowEvent we) {
304: 		cancel();
305: 	    }
306: 	});
307: 
308:         _dialog.pack();
309:         _dialog.setLocationRelativeTo(parent);
310:  
311:         _dialog.show();
312: 	return _returnValue;
313:     }
314: 	
315:     /**
316:      * Returns the choices a user can make.
317:      * @return Vector
318:      */
319:     public Vector getChoices() {
320: 	int[] indices = _choicesList.getSelectedIndices();
321: 	Vector returnVector = new Vector();
322: 	for (int i = 0; i < indices.length; i++) {
323: 	    returnVector.add(_choices.get(indices[i]));
324: 	}
325: 	return returnVector;
326:     }
327: 	
328:     /**
329:      * Returns the selected elements in the selected list
330:      * @return Vector
331:      */
332:     public Vector getSelectedChoices() {
333: 	Vector returnVector = new Vector();
334: 	if (_selectedList != null && _selected != null) {
335: 	    int[] indices = _selectedList.getSelectedIndices();			
336: 	    for (int i = 0; i < indices.length; i++) {
337: 		returnVector.add(_selected.get(indices[i]));
338: 	    }
339: 	}
340: 	return returnVector;
341:     }
342: 	
343:     /**
344:      * Returns the by the user selected elements. This method should
345:      * be called if the selected choices are to be known.
346:      *
347:      * @return Vector
348:      */
349:     public Vector getSelected() {
350: 	return _selected;
351:     }
352: 	
353:     /**
354:      * Adds the selected elements in the choices list to the selected
355:      * list. Updates the GUI too.
356:      */
357:     public void addSelection() {
358: 	Vector choices = getChoices();
359: 	_choices.removeAll(choices);
360: 	for (int i = 0; i < choices.size(); i++) {
361: 	    ((DefaultListModel) _choicesList.getModel()).removeElement(choices.get(i));
362: 	}
363: 	_selected.addAll(choices);
364: 	for (int i = 0; i < choices.size(); i++) {
365: 	    ((DefaultListModel) _selectedList.getModel()).addElement(choices.get(i));
366: 	}
367:     }
368: 	
369:     /**
370:      * Removes the selected elements in the selected list and adds
371:      * them to the choices list. Updates the GUI too.
372:      */
373:     public void removeSelection() {
374: 	Vector choices = getSelectedChoices();
375: 	_selected.removeAll(choices);
376: 	for (int i = 0; i < choices.size(); i++) {
377: 	    ((DefaultListModel) _selectedList.getModel()).removeElement(choices.get(i));
378: 	}
379: 	_choices.addAll(choices);
380: 	for (int i = 0; i < choices.size(); i++) {
381: 	    ((DefaultListModel) _choicesList.getModel()).addElement(choices.get(i));
382: 	}
383:     }
384: 	
385:     /**
386:      * Called when the okbutton is pressed. Closes this dialog and
387:      * sets the returnvalue to JOptionPane.OK_OPTION.
388:      */
389:     public void ok() {
390: 	if (_dialog != null) {
391: 	    _dialog.setVisible(false);
392: 	    _returnValue = JOptionPane.OK_OPTION;
393: 	}
394:     }
395: 	
396:     /**
397:      * Called when the cancel button is pressed. Closes this dialog
398:      * and sets the returnvalue to JOptionPane.CANCEL_OPTION.  Resets
399:      * the selected list to the originally preselection if there is
400:      * one. Otherwise the selected list is emptied.
401:      */
402:     public void cancel() {
403: 	_selected.removeAllElements();
404: 	if (_preSelected != null) {
405: 	    _selected.addAll(_preSelected);
406: 	}
407: 	if (_dialog != null) {
408: 	    _dialog.setVisible(false);
409: 	    _returnValue = JOptionPane.CANCEL_OPTION;
410: 	}
411:     }
412: }
