113:         PropertyChangeListener listener = relay.getListener();
114:         List list = (List) listeners.get(listener);
115:         if (list == null) {
116:             list = new ArrayList();
117:         }
118:         list.add(relay);
119:         listeners.put(listener, list);
120:     }
