137:      * 		java.beans.PropertyChangeListener, java.lang.Object,
138:      * 		java.lang.String[])
139:      */
140:     public void removeModelEventListener(PropertyChangeListener listener,
141:             				 Object modelelement,
142:             				 String[] eventNames) {
143:         LOG.debug("removeModelEventListener("
144:                   + listener + ", "
145:                   + modelelement + ", "
146:                   + eventNames + ")");
147:         NSUMLEventListener relay =
148:             find(modelEventListeners, listener, modelelement, eventNames);
149:         if (relay != null) {
150:             unregister(modelEventListeners, relay);
151:             relay.delete();
152:         }
153:     }
