155:     /**
156:      * @param listeners The listeners.
157:      * @param listener The PropertyChangeListener.
158:      * @param modelelement The model element.
159:      * @param eventNames The event names.
160:      * @return the found relay.
161:      */
162:     private NSUMLEventListener find(Map listeners,
163: 				    PropertyChangeListener listener,
164: 				    Object modelelement,
165: 				    String[] eventNames) {
166:         List list = (List) listeners.get(listener);
167:         if (list == null) {
168:             return null;
169:         }
170:         Iterator iter = list.iterator();
171:         while (iter.hasNext()) {
172:             NSUMLEventListener theListener = (NSUMLEventListener) iter.next();
173: 
174:             if (theListener.match(modelelement, eventNames)) {
175:                 return theListener;
176:             }
177:         }
178:         return null;
179:     }
