187:         LOG.debug("removeModelEventListener("
188:                   + listener + ", "
189:                   + modelelement + ")");
190:         NSUMLEventListener relay =
191:             find(modelEventListeners, listener, modelelement, null);
192:         if (relay != null) {
193:             unregister(modelEventListeners, relay);
194:             relay.delete();
195:         }
196:     }
