203:         List list = (List) listeners.get(relay.getListener());
204:         if (list == null) {
205:             return;
206:         }
207:         Iterator iter = list.iterator();
208:         while (iter.hasNext()) {
209:             NSUMLEventListener theListener = (NSUMLEventListener) iter.next();
210: 
211:             if (theListener == relay) {
212:                 iter.remove();
