32: /** Models the designers goals in making this design.  Provides useful
33:  *  control information to the Agency so that only critics relevant to
34:  *  the designers goals are ever executed.
35:  *
36:  *  Needs-More-Work: Really this should be part of a domain extension
37:  *  and not the kernel.  I have not developed this part of Argo very
38:  *  much. */
39: 
40: public class GoalModel extends Observable
41: implements java.io.Serializable {
42:   ////////////////////////////////////////////////////////////////
43:   // instance variables
44: 
45:   private Properties _goals = new Properties();
46: 
47:   ////////////////////////////////////////////////////////////////
48:   // constructor
49: 
50:   public GoalModel() { }
51: 
52:   ////////////////////////////////////////////////////////////////
53:   // accessors
54: 
55:   /** Reply true iff the Designer wants to achieve the given goal. */
56:   public boolean hasGoal(String goal) {
57:     String intStr = _goals.getProperty(goal);
58:     if 	(null == intStr) return false;
59:     int priority = Integer.parseInt(intStr);
60:     return priority >= 1;
61:   }
62: 
63:   public synchronized void setGoalPriority(String goal, int priority) {
64:     String priStr = (new Integer(priority)).toString();
65:     if (priority > 0) _goals.put(goal, priStr);
66:     else _goals.remove(goal);
67:   }
68: 
69:   public Object getGoalInfo(String goal) {
70:     return _goals.getProperty(goal);
71:     /* needs-more-work, we need a better representation of goals */
72:   }
73: 
