80:   public void startDesiring(String goal) { setGoalPriority(goal, 1); }
81: 
82:   /** The Designer does not care about the given goal. */
83:   public void stopDesiring(String goal) { setGoalPriority(goal, 0); }
84: 
85: 
86: } /* end class GoalModel */
