319:     /**
320:      * Scales the given fig that must be part of this FigObject.<p>
321:      *
322:      * @param f the fig to scale
323:      * @param x the new x coordinate for the FigObject
324:      * @param y the new y coordinate for the FigObject
325:      * @param w the new w coordinate for the FigObject
326:      * @param h the new h coordinate for the FigObject
327:      */
328:     private void reSize(Fig f, int x, int y, int w, int h) {
329:         if (f.isVisible()) {
330:             int newX =
331:                 (_w == 0)
332:                     ? x
333:                     : x + (int) ((f.getX() - _x) * ((float) w / (float) _w));
334:             int newY =
335:                 (_h == 0)
336:                     ? y
337:                     : y + (int) ((f.getY() - _y) * ((float) h / (float) _h));
338:             int newW =
339:                 (_w == 0)
340:                     ? 0
341:                     : (int) (((float) f.getWidth()) * ((float) w / (float) _w));
342: 
343:             int newH =
344:                 (_h == 0)
345:                     ? 0
346:                     : (int) (((float) f.getHeight())
347: 			     * ((float) h / (float) _h));
348: 
349:             f.setBounds(newX, newY, newW, newH);
350:         }
351:     }
