800:      * TODO: Does not work for EmptyNode atm.
801:      *
802:      * @param node is the given node
803:      * @return a List
804:      */
805:     public List getActivationNodes(Node node) {
806:         int start = -1;
807:         int end = -1;
808:         if (node instanceof ActivationNode) {
809:             ActivationNode activationNode = (ActivationNode) node;
810:             if (activationNode.isStart()) {
811:                 start = linkPositions.indexOf(activationNode);
812:                 ListIterator it =
813:                     linkPositions
814:                         .subList(
815:                             linkPositions.indexOf(activationNode),
816:                             linkPositions.size())
817:                         .listIterator();
818:                 while (it.hasNext()) {
819:                     Node node2 = (Node) it.next();
820:                     if (node2 instanceof ActivationNode
821:                         && ((ActivationNode) node2).isEnd()) {
822:                         end = linkPositions.indexOf(node2);
823:                         break;
824:                     }
825:                 }
826:             } else if (activationNode.isEnd()) {
827:                 end = linkPositions.indexOf(activationNode);
828:                 for (int i = end - 1; i >= 1; i--) {
829:                     Node node2 = (Node) linkPositions.get(i);
830:                     if (node2 instanceof ActivationNode
831:                         && ((ActivationNode) node2).isStart()) {
832:                         start = linkPositions.indexOf(node2);
833:                         break;
834:                     }
835:                 }
836:             } else {
837:                 // node is in between activations or does not belong
838:                 // to activation (yet)
839:                 if (!(nextNode(activationNode) instanceof ActivationNode)
840:                     || !(previousNode(activationNode)
841:                         instanceof ActivationNode)) {
842:                     return new ArrayList();
843:                 }
844:                 for (int i = getIndexOf(activationNode) + 1;
845:                     i < linkPositions.size();
846:                     i++) {
847:                     Node node2 = (Node) linkPositions.get(i);
848:                     if (node2 instanceof ActivationNode
849:                         && ((ActivationNode) node2).isEnd()) {
850:                         end = getIndexOf(node2);
851:                         break;
852:                     }
853:                 }
854:                 for (int i = getIndexOf(activationNode) - 1; i >= 0; i--) {
855:                     Node node2 = (Node) linkPositions.get(i);
856:                     if (node2 instanceof ActivationNode
857:                         && ((ActivationNode) node2).isStart()) {
858:                         start = getIndexOf(node2);
859:                         break;
860:                     }
861:                 }
862: 
863:             }
864:             if (end == -1 || start == -1) {
865:                 return new ArrayList();
866:             }
867:             return linkPositions.subList(start, end);
868: 
869:         }
870:         return new ArrayList();
871:     }
872: 
873:     /**
874:      * Returns the index of a given node.
875:      *
876:      * @param node is the given node
877:      * @return the index
878:      */
879:     public int getIndexOf(Node node) {
880:         return linkPositions.indexOf(node);
881:     }
882: 
883:     /**
884:      * See makeActivation(int startIndex, int endIndex)
885:      * @param startNode Node
886:      * @param endNode Node
887:      */
888:     public void makeActivation(Node startNode, Node endNode) {
889:         int startIndex = linkPositions.indexOf(startNode);
890:         int endIndex = linkPositions.indexOf(endNode);
891:         makeActivation(startIndex, endIndex);
892:     }
893: 
894:     /**
895:      * Makes an activation from the node with index startindex to the
896:      * node with index endindex. An activation means in this context
897:      * that the starting and ending node will be an activation node
898:      * after a call to this method.  The starting node is designated
899:      * via the start property that's a starting node. The same is true
900:      * for the ending node via the end property.<p>
901:      *
902:      * @param startIndex int
903:      * @param endIndex int
904:      */
905:     public void makeActivation(int startIndex, int endIndex) {
906:         for (int i = startIndex; i <= endIndex; i++) {
907:             Object o = linkPositions.get(i);
908:             if (!(o instanceof ActivationNode)) {
909:                 linkPositions.set(i, new ActivationNode());
910:             }
911:         }
912:         ((ActivationNode) linkPositions.get(startIndex)).setStart(true);
913:         ((ActivationNode) linkPositions.get(endIndex)).setEnd(true);
914:     }
915: 
916:     /**
917:      * Returns the node that's next to the given node.
918:      *
919:      * @param node is the given node
920:      * @return the Node
921:      */
922:     public Node nextNode(Node node) {
923:         if (getIndexOf(node) < linkPositions.size())
924:             return (Node) linkPositions.get(getIndexOf(node) + 1);
925:         else
926:             return null;
927:     }
928: 
929:     /**
930:      * Returns the node that's before the given node in the nodes list.
931:      *
932:      * @param node is the given node
933:      * @return the node
934:      */
935:     public Node previousNode(Node node) {
936:         if (getIndexOf(node) > 0) {
937:             return (Node) linkPositions.get(getIndexOf(node) - 1);
938:         } else
939:             return null;
940:     }
941: 
942:     /**
943:      * Returns true if this {@link FigObject} has activations. An
944:      * activation is in this case a start ActivationNode and an end
945:      * ActivationNode in the Nodes list (_linkPositions).<p>
946:      *
947:      * @return true if this {@link FigObject} has activations.
948:      */
949:     public boolean hasActivations() {
950:         for (int i = 0; i < linkPositions.size(); i++) {
951:             Node node = (Node) linkPositions.get(i);
952:             if (node instanceof ActivationNode) {
953:                 if (getActivationNodes(node).isEmpty()) {
954:                     return false;
955:                 }
956:             }
957:         }
958:         return true;
959:     }
960: 
961:     /**
962:      * @see org.tigris.gef.presentation.FigNode#getPortFig(java.lang.Object)
963:      */
964:     public Fig getPortFig(Object np) {
965:         if (np instanceof LinkPort) {
966:             return ((LinkPort) np).getFigLinkPort();
967:         }
968:         return null;
969:     }
970: 
971:     /**
972:      * Sets the given node on the given index in linkPositions.<p>
973:      *
974:      * @param index the given index
975:      * @param node the given node
976:      */
977:     public void setNode(int index, Node node) {
978:         linkPositions.set(index, node);
979:     }
980: 
981:     /**
982:      * Returns the ObjectNode. This is the port that represents the
983:      * object Figrect.
984:      *
985:      * @return the ObjectNode.
986:      */
987:     public ObjectNode getObjectNode() {
988:         for (int i = 0; i < linkPositions.size(); i++) {
989:             if (linkPositions.get(i) instanceof ObjectNode) {
990:                 return (ObjectNode) linkPositions.get(i);
991:             }
992:         }
993:         return null;
994:     }
995: 
996:     /**
997:      * Removes the fig from both the figs list as from the
998:      * _figActivations list and the _figLinkPorts. This assures us
999:      * that removal will indeed remove all 'pointers' to the object.<p>
1000:      *
1001:      * @see org.tigris.gef.presentation.FigGroup#removeFig(Fig)
1002:      */
1003:     public void removeFig(Fig f) {
1004:         super.removeFig(f);
1005:         figActivations.remove(f);
1006:         figFigLinkPorts.remove(f);
1007:     }
1008: 
1009:     /**
1010:      * Returns a list with the start, end and all nodes in between
1011:      * them of the activation that is prior to the given node. If the
1012:      * node is part of an activation, that activation is returned. If
1013:      * the node is null an empty list is returned.
1014:      *
1015:      * @param node is the given node
1016:      * @return a List
1017:      */
1018:     public List getPreviousActivation(Node node) {
1019:         List retList = getActivationNodes(node);
1020:         if (retList.isEmpty()) {
1021:             retList = getPreviousActivation(previousNode(node));
1022:         }
1023:         return retList;
1024:     }
1025: 
1026:     /**
1027:      * @param position the position in which the node will be added
1028:      * @param node the node to be added
1029:      */
1030:     public void addNode(int position, Node node) {
1031:         linkPositions.add(position, node);
1032:         Iterator it =
1033:             linkPositions
1034:                 .subList(position + 1, linkPositions.size())
1035:                 .iterator();
1036:         while (it.hasNext()) {
1037:             Object o = it.next();
1038:             if (o instanceof LinkPort) {
1039:                 FigLinkPort figLinkPort = ((LinkPort) o).getFigLinkPort();
1040:                 if (figLinkPort != null) {
1041:                     figLinkPort.setY(
1042:                         figLinkPort.getY()
1043:                             + SequenceDiagramLayout.LINK_DISTANCE);
1044:                 }
1045:             }
1046:         }
1047:         calcBounds();
1048:     }
1049: 
1050: }
