167:      * @param figs
168:      */
169:     public FigMessageGroup(List figs) {
170:         super(figs);
171:     }
172: 
173:     private void updateFigPositions() {
174:     	Collection figs = getFigs(); // the figs that make up this group
175:         Iterator it = figs.iterator();
176:     	if (!figs.isEmpty()) {
177:             FigMessage previousFig = null;
178:             for (int i = 0; it.hasNext(); i++) {
179:                 FigMessage fig = (FigMessage) it.next();
180:                 int y;
181:                 if (i != 0) {
182:                     y = previousFig.getY() + previousFig.getHeight() + 5;
183:                 } else {
184:                     y = getY();
185:                 }
186:                 fig.setLocation(getX(), y);
187:                 fig.endTrans();
188:                 previousFig = fig;
189:             }
190:     	}
191:     }
192: 
193: 
194: 
195:     /**
196:      * @see org.tigris.gef.presentation.Fig#calcBounds()
197:      */
198:     public void calcBounds() {
199: 	super.calcBounds();
200: 	Collection figs = getFigs();
201: 	if (!figs.isEmpty()) {
202: 	    Fig last = null;
203: 	    Fig first = null;
204: 	    // _x = first.getX();
205: 	    // _y = first.getY();
206: 	    _w = 0;
207:             Iterator it = figs.iterator();
208:             int size = figs.size();
209: 	    for (int i = 0; i < size; i++) {
210:                 Fig fig = (Fig) it.next();
211: 
212:                 if (i == 0) {
213:                     first = fig;
214:                 }
215:                 if (i == size - 1) {
216:                     last = fig;
217:                 }
218: 
219: 		if (fig.getWidth() > _w) {
220: 		    _w = fig.getWidth();
221: 		}
222: 	    }
223:             _h = last.getY() + last.getHeight() - first.getY();
224: 	} else {
225: 	    _w = 0;
226: 	    _h = 0;
227: 	}
228:     }
229: 
230: 
231: 
232:     /**
233:      * @see org.tigris.gef.presentation.FigGroup#addFig(Fig)
234:      */
235:     public void addFig(Fig f) {
236: 	super.addFig(f);
237: 	updateFigPositions();
238: 	calcBounds();
239:     }
240: 
241: 
242:     /**
243:      * @see org.tigris.gef.presentation.Fig#removeFromDiagram()
244:      */
245:     public void removeFromDiagramImpl() {
246:         Collection figs = getFigs();
247:         if (figs != null) {
248:             Iterator it = figs.iterator();
249:             while (it.hasNext()) {
250:                 Fig fig = (Fig) it.next();
251:                 fig.removeFromDiagram();
252:             }
253:         }
254:         removeAll();
255:         super.removeFromDiagram();
256:     }
257: 
258: 
259:     /**
260:      * @see org.tigris.gef.presentation.Fig#deleteFromModel()
261:      */
262:     public void deleteFromModel() {
263:     	Collection figs = getFigs();
264:         if (figs != null) {
265: 	    Iterator it = figs.iterator();
266: 	    while (it.hasNext()) {
267: 		Fig fig = (Fig) it.next();
268: 		fig.deleteFromModel();
269: 	    }
270:         }
271:         removeAll();
272:         super.deleteFromModel();
273:     }
274: 
275: }
