72: /**
73:  * <p>Class to display graphics for a UML Class in a diagram.</p>
74:  */
75: public class FigClass extends FigNodeModelElement 
76:         implements AttributesCompartmentContainer, 
77:         OperationsCompartmentContainer {
78: 
79: 
80:     ////////////////////////////////////////////////////////////////
81:     // constants
82: 
83:     ////////////////////////////////////////////////////////////////
84:     // instance variables
85: 
86:     //These are the positions of child figs inside this fig
87:     //They mst be added in the constructor in this order.
88:     private static final int BLINDER_POSN = 3;
89:     private static final int OPERATIONS_POSN = 4;
90:     private static final int ATTRIBUTES_POSN = 5;
91:     
92:     /**
93:      * <p>Manages residency of a class within a component on a deployment
94:      *   diagram. Not clear why it is public, or even why it is an instance
95:      *   variable (rather than local to the method).</p>
96:      *
97:      * not currently used. should be lazily instantiated in future.
98:      */
99: //    public Object resident =
100: //	UmlFactory.getFactory().getCore().createElementResidence();
101: 
102:     /**
103:      * <p>Text highlighted by mouse actions on the diagram.</p>
104:      */
105:     private CompartmentFigText highlightedFigText = null;
106: 
107:     /**
108:      * <p>Flag to indicate that we have just been created. This is to fix the
109:      *   problem with loading classes that have stereotypes already
110:      *   defined.</p>
111:      */
112:     private boolean newlyCreated = false;
113: 
114:     ////////////////////////////////////////////////////////////////
115:     // constructors
116: 
117:     /**
118:      * Main constructor for a {@link FigClass}.<p>
119:      *
120:      * Parent {@link FigNodeModelElement} will have created the main
121:      * box {@link #getBigPort()} and its name {@link #getNameFig()}
122:      * and stereotype (@link #getStereotypeFig()}. This constructor
123:      * creates a box for the attributes and operations.<p>
124:      *
125:      * The properties of all these graphic elements are adjusted
126:      * appropriately. The main boxes are all filled and have
127:      * outlines.<p>
128:      *
129:      * For reasons I don't understand the stereotype is created in a
130:      * box with lines. So we have to created a blanking rectangle to
131:      * overlay the bottom line, and avoid four compartments
132:      * showing.<p>
133:      *
134:      * There is some complex logic to allow for the possibility that
135:      * stereotypes may not be displayed (unlike operations and
136:      * attributes this is not a standard thing for UML). Some care is
137:      * needed to ensure that additional space is not added, each time
138:      * a stereotyped class is loaded.<p>
139:      *
140:      * There is a particular problem when loading diagrams with
141:      * stereotyped classes. Because we create a FigClass indicating
142:      * the stereotype is not displayed, we then add extra space for
143:      * such classes when they are first rendered. This ought to be
144:      * fixed by correctly saving the class dimensions, but that needs
145:      * more work. The solution here is to use a simple flag to
146:      * indicate the FigClass has just been created.<p>
147:      *
148:      * <em>Warning</em>. Much of the graphics positioning is hard
149:      * coded. The overall figure is placed at location (10,10). The
150:      * name compartment (in the parent {@link FigNodeModelElement} is
151:      * 21 pixels high. The stereotype compartment is created 15 pixels
152:      * high in the parent, but we change it to 19 pixels, 1 more than
153:      * ({@link #STEREOHEIGHT} here. The attribute and operations boxes
154:      * are created at 19 pixels, 2 more than {@link #ROWHEIGHT}.<p>
155:      *
156:      * CAUTION: This constructor (with no arguments) is the only one
157:      * that does enableSizeChecking(false), all others must set it
158:      * true.  This is because this constructor is the only one called
159:      * when loading a project. In this case, the parsed size must be
160:      * maintained.<p>
161:      */
162:     public FigClass() {
163: 
164:         // Set name box. Note the upper line will be blanked out if there is
165:         // eventually a stereotype above.
166:         getNameFig().setLineWidth(1);
167:         getNameFig().setFilled(true);
168: 
169:         // Attributes inside. First one is the attribute box itself.
170:         FigCompartment attrVec = 
171:             new FigAttributesCompartment(10, 30, 60, ROWHEIGHT + 2);
172: 
173:         // this rectangle marks the operation section; all operations
174:         // are inside it
175:         FigCompartment operVec = 
176:             new FigOperationsCompartment(10, 31 + ROWHEIGHT, 60, ROWHEIGHT + 2);
177: 
178:         // Set properties of the stereotype box. Make it 1 pixel higher than
179:         // before, so it overlaps the name box, and the blanking takes out both
180:         // lines. Initially not set to be displayed, but this will be changed
181:         // when we try to render it, if we find we have a stereotype.
182:         getStereotypeFigText().setExpandOnly(true);
183:         getStereotypeFig().setFilled(true);
184:         getStereotypeFig().setLineWidth(1);
185:         getStereotypeFigText().setEditable(false);
186:         getStereotypeFig().setHeight(STEREOHEIGHT + 1);
187:         // +1 to have 1 pixel overlap with getNameFig()
188:         getStereotypeFig().setVisible(false);
189: 
190:         // A thin rectangle to overlap the boundary line between stereotype
191:         // and name. This is just 2 pixels high, and we rely on the line
192:         // thickness, so the rectangle does not need to be filled. Whether to
193:         // display is linked to whether to display the stereotype.
194:         FigRect stereoLineBlinder =
195: 	    new FigRect(11, 10 + STEREOHEIGHT, 58, 2,
196: 			Color.white, Color.white);
197:         stereoLineBlinder.setLineWidth(1);
198:         stereoLineBlinder.setVisible(false);
199: 
200:         FigEmptyRect bigPort = new FigEmptyRect(10, 10, 0, 0);
201:         bigPort.setLineWidth(1);
202:         bigPort.setLineColor(Color.black);
203:         setBigPort(bigPort);
204:         
205:         // Mark this as newly created. This is to get round the problem with
206:         // creating figs for loaded classes that had stereotypes. They are
207:         // saved with their dimensions INCLUDING the stereotype, but since we
208:         // pretend the stereotype is not visible, we add height the first time
209:         // we render such a class. This is a complete fudge, and really we
210:         // ought to address how class objects with stereotypes are saved. But
211:         // that will be hard work.
212:         newlyCreated = true;
213: 
214:         // Put all the bits together, suppressing bounds calculations until
215:         // we're all done for efficiency.
216:         enableSizeChecking(false);
217:         setSuppressCalcBounds(true);
218:         addFig(getStereotypeFig());
219:         addFig(getNameFig());
220:         addFig(bigPort);
221:         addFig(stereoLineBlinder);
222:         addFig(operVec);
223:         addFig(attrVec);
224: 
225:         setSuppressCalcBounds(false);
226:         // Set the bounds of the figure to the total of the above (hardcoded)
227:         setBounds(10, 10, 60, 22 + 2 * ROWHEIGHT);
228:     }
229: 
230:     /**
231:      * <p>Constructor for use if this figure is created for an existing class
232:      *   node in the metamodel.</p>
233:      *
234:      * <p>Set the figure's name according to this node. This is used when the
235:      *   user click's on 'add to diagram' in the navpane.  Don't know if this
236:      *   should rather be done in one of the super classes, since similar code
237:      *   is used in FigInterface.java etc.  Andreas Rueckert
238:      *   &lt;a_rueckert@gmx.net&gt;</p>
239:      *
240:      * @param gm   Not actually used in the current implementation
241:      *
242:      * @param node The UML object being placed.
243:      */
244:     public FigClass(GraphModel gm, Object node) {
245:         this();
246:         enableSizeChecking(true);
247:         setOwner(node);
248:         if ((ModelFacade.isAClassifier(node))
249:                 && (ModelFacade.getName(node) != null)) {
250:             setName(ModelFacade.getName(node));
251:         }
252:     }
253: 
254:     /**
255:      * @see org.argouml.uml.diagram.ui.FigNodeModelElement#placeString()
256:      */
257:     public String placeString() {
258:         return "new Class";
259:     }
260: 
261:     ////////////////////////////////////////////////////////////////
262:     // accessors
263: 
264:     /**
265:      * @see org.tigris.gef.presentation.Fig#makeSelection()
266:      */
267:     public Selection makeSelection() {
268:         return new SelectionClass(this);
269:     }
270: 
271:     /**
272:      * Build a collection of menu items relevant for a right-click
273:      * popup menu on a Class.
274:      *
275:      * @param     me     a mouse event
276:      * @return           a collection of menu items
277:      *
278:      * @see org.tigris.gef.ui.PopupGenerator#getPopUpActions(java.awt.event.MouseEvent)
279:      */
280:     public Vector getPopUpActions(MouseEvent me) {
281:         Vector popUpActions = super.getPopUpActions(me);
282: 
283:         // Add...
284:         ArgoJMenu addMenu = new ArgoJMenu("menu.popup.add");
285:         addMenu.add(new ActionAddAttribute());
286:         addMenu.add(new ActionAddOperation());
287:         addMenu.add(ActionAddNote.getSingleton());
288:         popUpActions.insertElementAt(addMenu,
289:             popUpActions.size() - POPUP_ADD_OFFSET);
290: 
291:         // Show ...
292:         ArgoJMenu showMenu = new ArgoJMenu("menu.popup.show");
293:         if (isAttributesVisible() && isOperationsVisible()) {
294:             showMenu.add(ActionCompartmentDisplay.hideAllCompartments());
