646:      * @param ft    the Figtext
647:      * @param i     get the fig before fig i
648:      * @return the FigText
649:      */
650:     protected FigText getPreviousVisibleFeature(FigGroup fgVec,
651: 						FigText ft, int i) {
652:         if (fgVec == null || i < 1) {
653:             return null;
654:         }
655:         FigText ft2 = null;
656:         // TODO: come GEF V 0.12 use getFigs returning an array
657:         Vector v = new Vector(fgVec.getFigs(null));
658:         if (i >= v.size() || !((FigText) v.elementAt(i)).isVisible()) {
659:             return null;
660:         }
661:         do {
662:             i--;
663:             while (i < 1) {
664:                 fgVec = (fgVec == getAttributesFig()) 
665:                     ? getOperationsFig() 
666:                     : getAttributesFig();
667:                 v = new Vector(fgVec.getFigs(null));
668:                 i = v.size() - 1;
669:             }
670:             ft2 = (FigText) v.elementAt(i);
671:             if (!ft2.isVisible()) {
672:                 ft2 = null;
673:             }
674:         } while (ft2 == null);
675:         return ft2;
676:     }
