765:     /**
766:      * Handles changes of the model. Takes into account the event that
767:      * occured. If you need to update the whole fig, consider using
768:      * renderingChanged.<p>
769:      *
770:      * @see FigNodeModelElement#modelChanged(MElementEvent)
771:      */
772:     protected void modelChanged(MElementEvent mee) {
773:         super.modelChanged(mee);
774: 
775:         if (getOwner() == null) {
776:             return;
777:         }
778: 
779:         // attributes
780:         if (mee == null
781:                 || ModelFacade.isAAttribute(mee.getSource())
782:                 || (mee.getSource() == getOwner()
783: 		&& mee.getName().equals("feature"))) {
784:             updateAttributes();
785:             damage();
786:         }
787:         // operations
788:         if (mee == null
789:                 || ModelFacade.isAOperation(mee.getSource())
790:                 || ModelFacade.isAParameter(mee.getSource())
791:                 || (mee.getSource() == getOwner()
792: 		&& mee.getName().equals("feature"))) {
793:             updateOperations();
794:             damage();
795:         }
796:         if (mee != null && mee.getName().equals("parameter") 
797:                 && ModelFacade.isAOperation(mee.getSource())) {
798:             if (mee.getAddedValue() != null) {
799:                 UmlModelEventPump.getPump().addModelEventListener(this, 
800:                         mee.getAddedValue(), new String[] {
801:                             "name", "kind", "type", "defaultValue"});
802:             }
803:             if (mee.getRemovedValue() != null) {
804:                 UmlModelEventPump.getPump().addModelEventListener(this, 
805:                         mee.getRemovedValue());
806:             }
807:         }
808:         if (mee == null || mee.getName().equals("isAbstract")) {
809:             updateAbstract();
810:             damage();
811:         }
812:         if (mee == null || mee.getName().equals("stereotype")) {
813:             updateStereotypeText();
814:             updateAttributes();
815:             updateOperations();
816:             damage();
817:         }
818:         if (mee != null && ModelFacade.getStereotypes(getOwner())
819:                                 .contains(mee.getSource())) {
820:             updateStereotypeText();
821:             damage();
822:         }
823:         // name updating
824:         super.modelChanged(mee);
825:     }
