827:     /**
828:      * @see org.argouml.uml.diagram.ui.FigNodeModelElement#updateStereotypeText()
829:      */
830:     protected void updateStereotypeText() {
831: 
832:         Object me = /*(MModelElement)*/ getOwner();
833: 
834:         if (me == null) {
835:             return;
836:         }
837: 
838:         Rectangle rect = getBounds();
839:         Object stereo = null;
840:         if (ModelFacade.getStereotypes(me).size() > 0) {
841:             stereo = ModelFacade.getStereotypes(me).iterator().next();
842:         }
843: 
844:         if ((stereo == null)
845:                 || (ModelFacade.getName(stereo) == null)
846:                 || (ModelFacade.getName(stereo).length() == 0))	{
847: 
848:             if (getStereotypeFig().isVisible()) {
849:                 getFigAt(BLINDER_POSN).setVisible(false);
850:                 getStereotypeFig().setVisible(false);
851:                 rect.y += STEREOHEIGHT;
852:                 rect.height -= STEREOHEIGHT;
853:                 setBounds(rect.x, rect.y, rect.width, rect.height);
854:                 calcBounds();
855:             }
856:         } else {
857:             setStereotype(Notation.generateStereotype(this, stereo));
858: 
859:             if (!getStereotypeFig().isVisible()) {
860:                 getFigAt(BLINDER_POSN).setVisible(true);
861:                 getStereotypeFig().setVisible(true);
862: 
863:                 // Only adjust the stereotype height if we are not newly
864:                 // created. This gets round the problem of loading classes with
865:                 // stereotypes defined, which have the height already including
866:                 // the stereotype.
867: 
868:                 if (!newlyCreated) {
869:                     rect.y -= STEREOHEIGHT;
870:                     rect.height += STEREOHEIGHT;
871:                     setBounds(rect.x, rect.y, rect.width, rect.height);
872:                     calcBounds();
873:                 }
874:             }
875:         }
876: 
877:         // Whatever happened we are no longer newly created, so clear the
878:         // flag. Then set the bounds for the rectangle we have defined.
879:         newlyCreated = false;
880:     }
