882:     /**
883:      * <p>Sets the bounds, but the size will be at least the one returned by
884:      *   {@link #getMinimumSize()}, unless checking of size is disabled.</p>
885:      *
886:      * <p>If the required height is bigger, then the additional height is
887:      *   equally distributed among all figs (i.e. compartments), such that the
888:      *   cumulated height of all visible figs equals the demanded height<p>.
889:      *
890:      * <p>Some of this has "magic numbers" hardcoded in. In particular there is
891:      *   a knowledge that the minimum height of a name compartment is 21
892:      *   pixels.</p>
893:      *
894:      * @param x  Desired X coordinate of upper left corner
895:      *
896:      * @param y  Desired Y coordinate of upper left corner
897:      *
898:      * @param w  Desired width of the FigClass
899:      *
900:      * @param h  Desired height of the FigClass
901:      */
902:     public void setBounds(int x, int y, int w, int h) {
903: 
904:         // Save our old boundaries (needed later), and get minimum size
905:         // info. "aSize will be used to maintain a running calculation of our
906:         // size at various points.
907: 
908:         // "extra_each" is the extra height per displayed fig if requested
909:         // height is greater than minimal. "height_correction" is the height
910:         // correction due to rounded division result, will be added to the name
911:         // compartment
912: 
913:         Rectangle oldBounds = getBounds();
914:         Dimension aSize = 
915:             isCheckSize() ? getMinimumSize() : new Dimension(w, h);
916: 
917:         int newW = Math.max(w, aSize.width);
918:         int newH = h;
919: 
920:         int extraEach = 0;
921:         int heightCorrection = 0;
922: 
923:         // First compute all nessessary height data. Easy if we want less than
924:         // the minimum
925: 
926:         if (newH <= aSize.height) {
927: 
928:             // Just use the mimimum
929: 
930:             newH = aSize.height;
931: 
932:         } else {
933: 
934:             // Split the extra amongst the number of displayed compartments
935: 
936:             int displayedFigs = 1; //this is for getNameFig()
937: 
938:             if (getAttributesFig().isVisible()) {
939:                 displayedFigs++;
940:             }
941: 
942:             if (isOperationsVisible()) {
943:                 displayedFigs++;
944:             }
945: 
946:             // Calculate how much each, plus a correction to put in the name
947:             // comparment if the result is rounded
948: 
949:             extraEach = (newH - aSize.height) / displayedFigs;
950:             heightCorrection =
951: 		(newH - aSize.height) - (extraEach * displayedFigs);
952:         }
953: 
954:         // Now resize all sub-figs, including not displayed figs. Start by the
955:         // name. We override the getMinimumSize if it is less than our view (21
956:         // pixels hardcoded!). Add in the shared extra, plus in this case the
957:         // correction.
958: 
959:         int height = getNameFig().getMinimumSize().height;
960: 
961:         if (height < 21) {
962:             height = 21;
963:         }
964: 
965:         height += extraEach + heightCorrection;
966: 
967:         // Now sort out the stereotype display. If the stereotype is displayed,
968:         // move the upper boundary of the name compartment up and set new
969:         // bounds for the name and the stereotype compatments and the
970:         // stereoLineBlinder that blanks out the line between the two
971: 
972:         int currentY = y;
973: 
974:         if (getStereotypeFig().isVisible()) {
975:             currentY += STEREOHEIGHT;
976:         }
977: 
978:         getNameFig().setBounds(x, currentY, newW, height);
979:         getStereotypeFig().setBounds(x, y, newW, STEREOHEIGHT + 1);
980:         getFigAt(BLINDER_POSN).setBounds(x + 1, y + STEREOHEIGHT, newW - 2, 2);
981: 
982:         // Advance currentY to where the start of the attribute box is,
983:         // remembering that it overlaps the next box by 1 pixel. Calculate the
984:         // size of the attribute box, and update the Y pointer past it if it is
985:         // displayed.
986: 
987:         currentY += height - 1; // -1 for 1 pixel overlap
988: 
989:         int na = (isAttributesVisible())
990:     	    ? Math.max(1, getAttributesFig().getFigs(null).size() - 1)
991:     	    : 0;
992:         int no = (isOperationsVisible())
993:     	    ? Math.max(1, getOperationsFig().getFigs(null).size() - 1)
994:     	    : 0;
995:         if (isCheckSize()) {
996:             height = ROWHEIGHT * na + 2 + extraEach;
997:         } else if (newH > currentY - y && na + no > 0) {
998:             height = (newH + y - currentY) * na / (na + no) + 1;
999:         } else {
1000:             height = 1;
1001:         }
1002:         aSize = updateFigGroupSize(getAttributesFig(), x, currentY, 
1003:                 newW, height);
1004: 
1005:         if (getAttributesFig().isVisible()) {
1006:             currentY += aSize.height - 1; // -1 for 1 pixel overlap
1007:         }
1008: 
1009:         // Finally update the bounds of the operations box
1010: 
1011:         aSize =
1012: 	    updateFigGroupSize(getOperationsFig(), x, currentY, 
1013:                 newW, newH + y - currentY);
1014: 
1015:         // set bounds of big box
1016: 
1017:         getBigPort().setBounds(x, y, newW, newH);
1018: 
1019:         // Now force calculation of the bounds of the figure, update the edges
1020:         // and trigger anyone who's listening to see if the "bounds" property
1021:         // has changed.
1022: 
1023:         calcBounds();
1024:         updateEdges();
1025:         firePropChange("bounds", oldBounds, getBounds());
1026:     }
