437:     /**
438:      * <p>Gets the minimum size permitted for a class on the diagram.</p>
439:      *
440:      * <p>Parts of this are hardcoded, notably the fact that the name
441:      *   compartment has a minimum height of 21 pixels.</p>
442:      *
443:      * @return  the size of the minimum bounding box.
444:      */
445:     public Dimension getMinimumSize() {
446: 
447:         // Use "aSize" to build up the minimum size. Start with the size of the
448:         // name compartment and build up.
449: 
450:         Dimension aSize = getNameFig().getMinimumSize();
451:         if (aSize.height < 21) {
452:             aSize.height = 21;
453:         }
454: 
455:         // If we have a stereotype displayed, then allow some space for that
456:         // (width and height)
457: 
458:         if (getStereotypeFig().isVisible()) {
459:             aSize.width =
460: 		Math.max(aSize.width,
461: 			 getStereotypeFig().getMinimumSize().width);
462:             aSize.height += STEREOHEIGHT;
463:         }
464: 
465:         // Allow space for each of the attributes we have
466: 
467:         if (getAttributesFig().isVisible()) {
468: 
469:             // Loop through all the attributes, to find the widest (remember
470:             // the first fig is the box for the whole lot, so ignore it).
471: 
472:             Iterator it = getAttributesFig().getFigs(null).iterator();
473:             it.next(); // Ignore first element
474: 
475:             while (it.hasNext()) {
476:                 int elemWidth =
477: 		    ((FigText) it.next()).getMinimumSize().width + 2;
478:                 aSize.width = Math.max(aSize.width, elemWidth);
479:             }
480: 
481:             // Height allows one row for each attribute (remember to ignore the
482:             // first element.
483: 
484:             aSize.height +=
485: 		ROWHEIGHT * Math.max(1, 
486: 		        getAttributesFig().getFigs(null).size() - 1) + 1;
487:         }
488: 
489:         // Allow space for each of the operations we have
490: 
491:         if (isOperationsVisible()) {
492: 
493:             // Loop through all the operations, to find the widest (remember
494:             // the first fig is the box for the whole lot, so ignore it).
495: 
496:             Iterator it = getOperationsFig().getFigs(null).iterator();
497:             it.next(); // ignore
498: 
499:             while (it.hasNext()) {
500:                 int elemWidth =
501: 		    ((FigText) it.next()).getMinimumSize().width + 2;
502:                 aSize.width = Math.max(aSize.width, elemWidth);
503:             }
504: 
505:             aSize.height +=
506: 		ROWHEIGHT * Math.max(1, 
507: 		        getOperationsFig().getFigs(null).size() - 1) + 1;
508:         }
509: 
510:         // we want to maintain a minimum width for the class
511:         aSize.width = Math.max(60, aSize.width);
512: 
513:         // And now aSize has the answer
514: 
515:         return aSize;
516:     }
