457:     /**
458:      * Perform a list of commands that were given on the command line.
459:      *
460:      * This first implementation just has a list of commands that
461:      * is possible to give.
462:      *
463:      * @param list The commands, a list of strings.
464:      */
465:     public static void performCommands(List list) {
466: 	Iterator iter = list.iterator();
467: 
468: 	while (iter.hasNext()) {
469: 	    String commandstring = (String) iter.next();
470: 
471: 	    int pos = commandstring.indexOf('=');
472: 
473: 	    String commandname;
474: 	    String commandargument;
475: 
476: 	    if (pos == -1) {
477: 		commandname = commandstring;
478: 		commandargument = null;
479: 	    } else {
480: 		commandname = commandstring.substring(0, pos);
481: 		commandargument = commandstring.substring(pos + 1);
482: 	    }
483: 
484: 	    // Perform one command.
485: 	    Class c;
486: 	    try {
487: 		c = Class.forName(commandname);
488: 	    } catch (ClassNotFoundException e) {
489: 		System.out.println("Cannot find the command: " + commandname);
490: 		continue;
491: 	    }
492: 
493: 	    // Now create a new object.
494: 	    Object o = null;
495: 	    try {
496: 		o = c.newInstance();
497: 	    } catch (InstantiationException e) {
498: 		System.out.println(commandname
499: 				   + " could not be instantiated - skipping"
500: 				   + " (InstantiationException)");
501: 		continue;
502: 	    } catch (IllegalAccessException e) {
503: 		System.out.println(commandname
504: 				   + " could not be instantiated - skipping"
505: 				   + " (IllegalAccessException)");
506: 		continue;
507: 	    }
508: 
509: 
510: 	    if (o == null || !(o instanceof CommandLineInterface)) {
511: 		System.out.println(commandname
512: 				   + " is not a command - skipping.");
513: 		continue;
514: 	    }
515: 
516: 	    CommandLineInterface clio = (CommandLineInterface) o;
517: 
518: 	    System.out.println("Performing command "
519: 			       + commandname + "( "
520: 			       + (commandargument == null
521: 				  ? "" : commandargument) + " )");
522: 	    boolean result = clio.doCommand(commandargument);
523: 	    if (!result) {
524: 		System.out.println("There was an error executing "
525: 				   + "the command "
526: 				   + commandname + "( "
527: 				   + (commandargument == null
528: 				      ? "" : commandargument) + " )");
529: 		System.out.println("Aborting the rest of the commands.");
530: 		return;
531: 	    }
532: 	}
533:     }
