529: 		System.out.println("Aborting the rest of the commands.");
530: 		return;
531: 	    }
532: 	}
533:     }
534: 
535:     /**
536:      * Install our security handlers,
537:      * and do basic initialization of log4j.
538:      *
539:      * Log4j initialization must be done as
540:      * part of the main class initializer, so that
541:      * the log4j initialization is complete
542:      * before any other static initializers.
543:      *
544:      * Also installs a trap to "eat" certain SecurityExceptions.
545:      * Refer to {@link java.awt.EventDispatchThread} for details.
546:      */
547:     static {
548: 
549:         /*  Install the trap to "eat" SecurityExceptions.
550:          */
551:         System.setProperty(
552:             "sun.awt.exception.handler",
553:             ArgoAwtExceptionHandler.class.getName());
554: 
555:         /*  The string <code>log4j.configuration</code> is the
556:          *  same string found in
557:          *  {@link org.apache.log4j.Configuration.DEFAULT_CONFIGURATION_FILE}
558:          *  but if we use the reference, then log4j configures itself
559:          *  and clears the system property and we never know if it was
560:          *  set.
561:          *
562:          *  If it is set, then we let the static initializer in
563:          * {@link Argo} perform the initialization.
564:          */
565: 
566:         if (System.getProperty("log4j.configuration") == null) {
567:             Properties props = new Properties();
568: 	    InputStream stream = null;
569:             try {
570: 		stream =
571: 		    ClassLoader.getSystemResourceAsStream(
572: 		        DEFAULT_LOGGING_CONFIGURATION);
573: 
574: 		if (stream != null) {
575: 		    props.load(stream);
576: 		}
577:             } catch (IOException io) {
578:                 io.printStackTrace();
579:                 System.exit(-1);
580:             }
581: 
582: 	    PropertyConfigurator.configure(props);
583: 
584: 	    if (stream == null) {
585: 		BasicConfigurator.configure();
586: 		Logger.getRootLogger().getLoggerRepository()
587: 		    .setThreshold(Level.OFF);
588: 	    }
589:         }
590: 
591:         // initLogging();
592:     }
593: 
594:     /**
595:      * Do a part of the initialization that is very much GUI-stuff.
596:      *
597:      * @param doSplash true if we are updating the splash
598:      * @param theTheme is the theme to set.
599:      */
600:     private static SplashScreen initializeGUI(
601:                     boolean doSplash, String themeMemory) {
602: 	// initialize the correct look and feel
603: 	LookAndFeelMgr.getInstance().initializeLookAndFeel();
604: 	if (themeMemory != null) {
605: 	    LookAndFeelMgr.getInstance().setCurrentTheme(themeMemory);
606: 	}
607: 
608:         SplashScreen splash = null;
609:         if (doSplash) splash = new SplashScreen();
610: 
611:         // make the projectbrowser
612: 	ProjectBrowser pb = ProjectBrowser.makeInstance(splash);
613: 
614: 	JOptionPane.setRootFrame(pb);
615: 
616: 	// Set the screen layout to what the user left it before, or
617: 	// to reasonable defaults.
618: 	Dimension scrSize = Toolkit.getDefaultToolkit().getScreenSize();
619: 	pb.setCursor(Cursor.getPredefinedCursor(Cursor.WAIT_CURSOR));
620: 
621: 	int configFrameWidth =
622: 	    Configuration.getInteger(Argo.KEY_SCREEN_WIDTH,
623: 				     (int) (0.95 * scrSize.width));
624: 	int configFrameHeight =
625: 	    Configuration.getInteger(Argo.KEY_SCREEN_HEIGHT,
626: 				     (int) (0.95 * scrSize.height));
627:         int w = Math.min(configFrameWidth, scrSize.width);
628:         int h = Math.min(configFrameHeight, scrSize.height);
629: 	int x = Configuration.getInteger(Argo.KEY_SCREEN_LEFT_X, 0);
630: 	int y = Configuration.getInteger(Argo.KEY_SCREEN_TOP_Y, 0);
631: 	pb.setLocation(x, y);
632: 	pb.setSize(w, h);
633:         return splash;
634:     }
635: 
636: 
637: 
638: } /* end Class Main */
