172:     /**
173:      * Returns the Look and Feel class name identifier for the specified
174:      * display name, or null if no such Look and Feel is found.
175:      *
176:      * @param	name	display name of desired look and feel
177:      * @return			class name for desired look and feel
178:      **/
179:     public String getLookAndFeelFromName(String name) {
180:         if (name == null || DEFAULT_KEY.equals(name)) {
181:             return null;
182:         }
183: 
184:         String className = null;
185: 
186:         UIManager.LookAndFeelInfo[] lafs = UIManager.getInstalledLookAndFeels();
187:         for (int i = 0; i < lafs.length; ++i) {
188:             if (lafs[i].getName().equals(name)) {
189:                 className = lafs[i].getClassName();
190:             }
191:         }
192: 
193:         return className;
194:     }
