365:     /**
366:      * @return the small font
367:      */
368:     public Font getSmallFont() {
369:         Font font = getStandardFont();
370:         if (font.getSize2D() >= 12f) {
371:             return font.deriveFont(font.getSize2D() - 2f);
372:         }
373:         return font;
374:     }
375: 
376:     /**
377:      * Sets the look and feel in the GUI by calling UIManager.setLookAndFeel().
378:      *
379:      * @param	lafClass	class name of look and feel
380:      **/
381:     private void setLookAndFeel(String lafClass) {
382:         try {
383:             if (lafClass == null && defaultLafClass != null) {
384:                 // Set to the default LAF
385:                 UIManager.setLookAndFeel(defaultLafClass);
386:             } else {
387:                 // Set a custom LAF
388:                 UIManager.setLookAndFeel(lafClass);
389:             }
390:         } catch (UnsupportedLookAndFeelException e) {
391:             LOG.error(e);
392:         } catch (ClassNotFoundException e) {
393:             LOG.error(e);
394:         } catch (InstantiationException e) {
395:             LOG.error(e);
396:         } catch (IllegalAccessException e) {
397:             LOG.error(e);
398:         }
399:     }
400: 
401:     /**
402:      * Sets the metal theme in the GUI by calling
403:      * MetalLookAndFeel.setCurrentTheme().
404:      *
405:      * @param	theme	new MetalTheme to set
406:      **/
407:     private void setTheme(MetalTheme theme) {
408:         String currentLookAndFeel = getCurrentLookAndFeel();
409: 
410:         // If LAF is Metal (either set explicitly, or as the default)
411:         if ((currentLookAndFeel != null && currentLookAndFeel.equals(METAL_LAF))
412: 	    || (currentLookAndFeel == null
413: 	        && defaultLafClass.equals(METAL_LAF))) {
414:             try {
415:                 MetalLookAndFeel.setCurrentTheme(theme);
416:                 UIManager.setLookAndFeel(METAL_LAF);
417:             } catch (UnsupportedLookAndFeelException e) {
418:                 LOG.error(e);
419:             } catch (ClassNotFoundException e) {
420:                 LOG.error(e);
421:             } catch (InstantiationException e) {
422:                 LOG.error(e);
423:             } catch (IllegalAccessException e) {
424:                 LOG.error(e);
425:             }
426:         }
427:     }
428: 
429:     /**
430:      * Returns the MetalTheme for the specified class name.
431:      * Returns the default theme if a corresponding MetalTheme class
432:      * can not be found.
433:      *
434:      * @param	themeClass	MetalTheme class name
435:      * @return				MetalTheme object for class name
436:      **/
437:     private MetalTheme getMetalTheme(String themeClass) {
438:         MetalTheme theme = null;
439: 
440:         for (int i = 0; i < THEMES.length; ++i) {
441:             if (THEMES[i].getClass().getName().equals(themeClass)) {
442:                 theme = THEMES[i];
443:             }
444:         }
445: 
446:         if (theme == null) {
447:             theme = DEFAULT_THEME;
448:         }
449: 
450:         return theme;
451:     }
452: }
