41: /**
42:  * A class to implement the actions involved in hiding and showing
43:  * compartments on interfaces, classes and use cases.<p>
44:  *
45:  * This implementation may easily be extended for other
46:  * compartments of other figs.<p>
47:  *
48:  * The class declares a number of static instances, each with an
49:  * actionPerformed method that performs the required action.
50:  */
51: public class ActionCompartmentDisplay extends UMLAction {
52: 
53: 
54:     ///////////////////////////////////////////////////////////////////////////
55:     //
56:     // Instance variables
57:     //
58:     ///////////////////////////////////////////////////////////////////////////
59: 
60:     /**
61:      * A flag to indicate whether the action should show or hide the
62:      * relevant compartment.
63:      */
64:     private boolean display = false;
65: 
66:     /**
67:      * The compartment type:<p>
68:      * 0: attribute
69:      * 1: operation
70:      * 2: attribute and operation
71:      * 3: extensionpoint
72:      */
73:     private int cType;
74: 
75:     ///////////////////////////////////////////////////////////////////////////
76:     //
77:     // Class variables
78:     //
79:     ///////////////////////////////////////////////////////////////////////////
80: 
81:     /**
82:      * Static instance to show the attribute compartment of a class.
83:      */
84:     private static final UMLAction SHOW_ATTR_COMPARTMENT =
85:         new ActionCompartmentDisplay(true,
86:                 "action.show-attribute-compartment", 0);
87: 
88:     /**
89:      * Static instance to hide the attribute compartment of a class.
90:      */
91:     private static final UMLAction HIDE_ATTR_COMPARTMENT =
92:         new ActionCompartmentDisplay(false,
93:                 "action.hide-attribute-compartment", 0);
94: 
95:     /**
96:      * Static instance to show the operation compartment of a class.
97:      */
98:     private static final UMLAction SHOW_OPER_COMPARTMENT =
99:         new ActionCompartmentDisplay(true,
100:                 "action.show-operation-compartment", 1);
101: 
102:     /**
103:      * Static instance to hide the operation compartment of a class.
104:      */
105:     private static final UMLAction HIDE_OPER_COMPARTMENT =
106:         new ActionCompartmentDisplay(false,
107: 		"action.hide-operation-compartment", 1);
108: 
109:     /**
110:      * Static instance to show the extension point compartment of a use
111:      * case.
112:      */
113:     private static final UMLAction SHOW_EXTPOINT_COMPARTMENT =
114:         new ActionCompartmentDisplay(true,
115:                 "action.show-extension-point-compartment", 3);
116: 
117:     /**
118:      * Static instance to hide the extension point compartment of a use
119:      *   case.
120:      */
121:     private static final UMLAction HIDE_EXTPOINT_COMPARTMENT =
122:         new ActionCompartmentDisplay(false,
123:                 "action.hide-extension-point-compartment", 3);
124: 
125:     /**
126:      * Static instance to show both compartments of a class.
127:      */
128:     private static final UMLAction SHOW_ALL_COMPARTMENTS =
129:         new ActionCompartmentDisplay(true, "action.show-all-compartments", 2);
130: 
131:     /**
132:      * Static instance to hide both compartments of a class.
133:      */
134:     private static final UMLAction HIDE_ALL_COMPARTMENTS =
135:         new ActionCompartmentDisplay(false, "action.hide-all-compartments", 2);
136: 
137: 
138:     ///////////////////////////////////////////////////////////////////////////
139:     //
140:     // constructors
141:     //
142:     ///////////////////////////////////////////////////////////////////////////
143: 
144:     /**
145:      * Constructor for a new instance. Can only be called by this class or
146:      * its children, since used to create static instances only.
147:      *
148:      * @param d    <code>true</code> if the compartment is to be shown,
149:      *             <code>false</code> if it is to be hidden
150:      *
151:      * @param c    the text to be displayed for this action
152:      * @param type the type of compartment. See definition at {@link #cType}
153:      */
154:     protected ActionCompartmentDisplay(boolean d, String c, int type) {
155: 
156:         // Invoke the parent constructor
157: 	super(c, true, NO_ICON);
158: 
159:         // Save copies of the parameters
160: 	display = d;
161:         cType = type;
162:     }
163: 
164: 
165:     ///////////////////////////////////////////////////////////////////////////
166:     //
167:     // main methods
168:     //
169:     ///////////////////////////////////////////////////////////////////////////
170: 
171:     /**
172:      * Return the compartment show and/or hide actions
173:      * needed for the selected Figs.
174:      * Only returns the actions for the menu-items that make sense
175:      * for the current selection.
176:      */
177:     public static Collection getActions() {
178:         Collection actions = new ArrayList();
179:         Editor ce = Globals.curEditor();
180:         Vector figs = ce.getSelectionManager().getFigs();
181:         Iterator i = figs.iterator();
182:         boolean aOn = false;
183:         boolean aOff = false;
184:         boolean oOn = false;
185:         boolean oOff = false;
186:         boolean eOn = false;
187:         boolean eOff = false;
188:         while (i.hasNext()) {
189:             Fig f = (Fig) i.next();
190:             if (f instanceof AttributesCompartmentContainer) {
191:                 boolean v =
192:                     ((AttributesCompartmentContainer) f).isAttributesVisible();
193:                 if (v) aOn = true;
194:                 else aOff = true;
195:             }
196:             if (f instanceof OperationsCompartmentContainer) {
197:                 boolean v =
198:                     ((OperationsCompartmentContainer) f).isOperationsVisible();
199:                 if (v) oOn = true;
200:                 else oOff = true;
201:             }
202:             if (f instanceof ExtensionsCompartmentContainer) {
203:                 boolean v =
204:                     ((ExtensionsCompartmentContainer) f).isExtensionPointVisible();
205:                 if (v) eOn = true;
206:                 else eOff = true;
207:             }
208:         }
209: 
210:         if ((aOn || oOn) && (aOn || aOff)) {
211:             actions.add(HIDE_ALL_COMPARTMENTS);
212:         }
213:         if ((aOff || oOff) && (aOn || aOff)) {
214:             actions.add(SHOW_ALL_COMPARTMENTS);
215:         }
216:         if (aOn) {
217:             actions.add(HIDE_ATTR_COMPARTMENT);
218:         }
219:         if (aOff) {
220:             actions.add(SHOW_ATTR_COMPARTMENT);
221:         }
222:         if (oOn) {
223:             actions.add(HIDE_OPER_COMPARTMENT);
224:         }
225:         if (oOff) {
226:             actions.add(SHOW_OPER_COMPARTMENT);
227:         }
228:         if (eOn) {
229:             actions.add(HIDE_EXTPOINT_COMPARTMENT);
230:         }
231:         if (eOff) {
232:             actions.add(SHOW_EXTPOINT_COMPARTMENT);
233:         }
234: 
235:         return actions;
236:     }
237: 
238: 
239:     /**
240:      * Action method invoked when an event triggers this action.<p>
241:      *
242:      * The {@link #cType} instance variable defines the action to
243:      * take, and the {@link #display} instance variable whether it should
244:      * set visibility or not.<p>
245:      *
246:      * @param ae  The event that triggered us.
247:      */
248:     public void actionPerformed(ActionEvent ae) {
249: 	Iterator i =
250:             Globals.curEditor().getSelectionManager().selections().iterator();
251: 	while (i.hasNext()) {
252: 	    Selection sel = (Selection) i.next();
253: 	    Fig       f   = sel.getContent();
254: 
255:             // Perform the action
256:             if ((cType == 0) || (cType == 2)) {
257: 		if (f instanceof AttributesCompartmentContainer)
258: 		    ((AttributesCompartmentContainer) f)
259:                         .setAttributesVisible(display);
260:             }
261:             if ((cType == 1) || (cType == 2)) {
262: 		if (f instanceof OperationsCompartmentContainer)
263: 		    ((OperationsCompartmentContainer) f)
264:                         .setOperationsVisible(display);
265:             }
266:             if (cType == 3) {
267: 		((FigUseCase) f).setExtensionPointVisible(display);
268:             }
269: 	}
270:     }
271: 
272: } /* end class ActionCompartmentDisplay */
