197: 	JLabel valLab = (JLabel) slidersToDigits.get(srcSlider);
198: 	int pri = srcSlider.getValue();
199: 	d.setPriority(pri);
200: 	if (pri == 0) {
201: 	    valLab.setText(Translator.localize("label.off"));
