353:                 Object target = null;
354:                 if (targets[i] instanceof Fig
355: 		        && manager.getContents(null).contains(targets[i])) {
356: 		    target = targets[i];
357:                 } else {
358: 		    target = manager.presentationFor(targets[i]);
359:                 }
360: 
361:                 if (target != null) {
362:                     figList.add(target);
363:                 }
364:             }
365:         }
366: 
367: 	if (!figList.equals(_jgraph.selectedFigs())) {
