348:     private void select(Object[] targets) {
349:         LayerManager manager = _jgraph.getEditor().getLayerManager();
350:         Vector figList = new Vector();
351:         for (int i = 0; i < targets.length; i++) {
352:             if (targets[i] != null) {
353:                 Object target = null;
354:                 if (targets[i] instanceof Fig
355: 		        && manager.getContents(null).contains(targets[i])) {
356: 		    target = targets[i];
357:                 } else {
358: 		    target = manager.presentationFor(targets[i]);
359:                 }
360: 
361:                 if (target != null) {
362:                     figList.add(target);
363:                 }
364:             }
365:         }
366: 
367: 	if (!figList.equals(_jgraph.selectedFigs())) {
368:             _jgraph.deselectAll();
369:             _jgraph.select(figList);
370: 	}
371:     }
