1185: /**
1186:  * A map containing instances of meta-classes (modelelements) as keys and 
1187:  * EventListenerLists as values. The class is a wrapper around an underlying
1188:  * java.util.HashMap and provides some custom methods for easy access to the 
1189:  * underlying data structure.
1190:  *
1191:  * @author jaap.branderhorst@xs4all.nl
1192:  */
1193: class EventListenerHashMap {
1194: 
1195:     /**
1196:      * A null array to be shared by all empty listener lists.
1197:      */
1198:     private static final MElementListener[] NULL_ARRAY =
1199:         new MElementListener[0];
1200: 
1201:     /**
1202:      * The list of ListenerType - Listener pairs. 
1203:      */
1204:     private transient Map listenerMap = new HashMap();
1205: 
1206:     /**
1207:      * Puts the given listener as listener to the given modelelement
1208:      * and given eventKey in the map.
1209:      *
1210:      * @param element
1211:      * @param key
1212:      * @param listener
1213:      */
1214:     public synchronized void put(
1215:         MBase element,
1216:         EventKey key,
1217:         MElementListener listener) {     
1218:         EventListenerList list = (EventListenerList) listenerMap.get(element);
1219:         if (list == null) {
1220:             list = new EventListenerList();
1221:             listenerMap.put(element, list);
1222:         }
1223:         list.add(key, listener);
1224:     }
1225: 
1226:     /**
1227:      * Removes a listener for a given eventkey and a given modelelement.
1228:      * @param element
1229:      * @param key
1230:      * @param listener
1231:      */
1232:     public synchronized void remove(
1233:         MBase element,
1234:         EventKey key,
1235:         MElementListener listener) {    
1236:         EventListenerList list = (EventListenerList) listenerMap.get(element);
1237:         if (list != null) {
1238:             list.remove(key, listener);
1239:         }
1240:     }
1241: 
1242:     /**
1243:      * Removes the complete EventListenerList for the given element.
1244:      *
1245:      * @param element
1246:      */
1247:     public synchronized void remove(MBase element) {
1248:         listenerMap.remove(element);
1249:     }
1250: 
1251:     /**
1252:      * Returns all listeners that are registered for the given modelElement and
1253:      * the given EventKey.
1254:      *
1255:      * @param element
1256:      * @param key
