1417: /**
1418:  * Class containing the definitions of all events in NSUML. The file
1419:  * eventtree.xml is loaded by this class and converted to a hashmap
1420:  * containing the classes firing events as keys and (hashmaps
1421:  * containing eventnames as keys and eventtypes as values) as values.
1422:  * @author jaap.branderhorst@xs4all.nl
1423:  */
1424: class EventTreeDefinition {
1425:     private static final Logger LOG = 
1426:         Logger.getLogger(EventTreeDefinition.class);
1427:     private static final String FILE_NAME = "org/argouml/eventtree.xml";
1428:     private Map definition = new HashMap();
1429: 
1430:     /**
1431:      * Create an instance of EventTreeDefinition, reading
1432:      * org/argouml/eventtree.xml to obtain the initial configuration.
1433:      */
1434:     public EventTreeDefinition() {
1435:         Document doc = loadDocument();
1436:         synchronized (doc) { // TODO: Why is this synchronized??
1437:             addSourcesFromDocument (doc);
1438:         }
1439:     }
1440: 
1441:     /**
1442:      * <p>Add all event sources described by the given document.
1443:      * The document must match  the pattern given by the following example:
1444:      * 
1445:      * <pre>
1446:      * &lt;eventtree&gt;
1447:      *   &lt;source classname="classname of a model element"&gt;
1448:      *     &lt;eventtype name="event fired by this model element"&gt;
1449:      *       &lt;type&gt;1&lt;/type&gt;
1450:      *     &lt;/eventtype&gt;
1451:      *   &lt;/source&gt;
1452:      * &lt;/eventtree&gt;
1453:      * </pre>
1454:      *
1455:      * The classname is fully qualified.<p>
1456:      * 
1457:      * <p>The type is one of the numbers defined in {@link MElementEvent}. Each 
1458:      * of the elements can be used multiple times.
1459:      * 
1460:      * @param doc the document, the contents of which should be added to this 
1461:      *            event tree definition. This must be preparsed.
1462:      */
1463:     synchronized void addSourcesFromDocument (final Document doc) {
1464:         NodeList sources = doc.getChildNodes().item(0).getChildNodes();
1465:         for (int i = 0; i < sources.getLength(); i++) {
1466:             Element source = (Element) sources.item(i);
1467:             String className = source.getAttribute("classname");
1468:             Class sourceClass = null;
1469:             try {
1470:                 sourceClass = Class.forName(className);
1471:             } catch (ClassNotFoundException e) {
1472:                 LOG.error(e);
1473:             }
1474:             Map nameMap = new HashMap();
1475:             NodeList eventTypes = source.getChildNodes();
1476:             for (int j = 0; j < eventTypes.getLength(); j++) {
1477:                 Element eventType = (Element) eventTypes.item(j);
1478:                 String name = eventType.getAttribute("name");
1479:                 NodeList typeNodes = eventType.getChildNodes();
1480:                 int typeLength = typeNodes.getLength();
1481:                 int[] types = new int[typeLength];
1482:                 for (int k = 0; k < typeLength; k++) {
1483:                     Element typeNode = (Element) typeNodes.item(k);
1484:                     types[k] =
1485:                         Integer.parseInt(
1486:                             typeNode.getFirstChild().getNodeValue());
1487:                 }
1488:                 nameMap.put(name, types);
1489:             }
1490:             // remove case
1491:             nameMap.put(UmlModelEventPump.REMOVE, new int[] {
1492:                 0,
1493:             });
1494:             addSource (sourceClass, nameMap);
1495:         }
1496:     }
1497: 
1498:     /**
1499:      * Add event types for a single source to this event tree.
1500:      * 
1501:      * @param cSource the source class for which to add event types.
1502:      * 
1503:      * @param mpNameMap a map of the event types to add for the source class.
1504:      *                  The keys are Strings indicating the names of events, 
1505:      *                  while the values are int[] which contain all the event
1506:      *                  types the indicated event represents. The specific int 
1507:      *                  values used can be found in {@link MElementEvent}.
1508:      */
1509:     synchronized void addSource (Class cSource, Map mpNameMap) {
1510:         definition.put (cSource, mpNameMap);
1511:     }
1512: 
1513:     /**
1514:      * Returns all eventkeys that an instance of the given modelClass
1515:      * could possibly fire.
1516:      * @param modelClass
1517:      * @return The event keys.
1518:      */
1519:     public synchronized EventKey[] getEventTypes(Class modelClass) {
1520:         modelClass = formatClass(modelClass);
1521:         Map nameMap = (Map) definition.get(modelClass);
1522:         Iterator it = nameMap.keySet().iterator();
1523:         int size = 0;
1524:         while (it.hasNext()) {
1525:             size += ((int[]) nameMap.get(it.next())).length;
1526:         }
1527:         EventKey[] result = new EventKey[size + 1];
1528:         int counter = 0;
1529:         it = nameMap.keySet().iterator();
1530:         while (it.hasNext()) {
1531:             String name = (String) it.next();
1532:             int[] types = (int[]) nameMap.get(name);
1533:             EventKey[] keys = new EventKey[types.length];
1534:             for (int i = 0; i < types.length; i++) {
1535:                 keys[i] = new EventKey(types[i], name);
1536:             }
1537:             System.arraycopy(keys, 0, result, counter, keys.length);
1538:             counter += keys.length;
1539:         }
1540:         // remove event
1541:         System.arraycopy(new EventKey[] {
1542: 	    new EventKey(0, null),
1543: 	},
1544: 			 0,
1545: 			 result,
1546: 			 counter,
1547: 			 1);
1548:         return result;
1549:     }
1550: 
1551:     /**
1552:      * Returns all EventKeys (eventdefinitions) with the given eventName 
1553:      * that the given modelClass can fire.
1554:      * @param modelClass
1555:      * @param name
1556:      * @return All event keys.
1557:      */
1558:     public synchronized EventKey[] getEventTypes(Class modelClass,
1559:                                                  String name) {
1560:         modelClass = formatClass(modelClass);
1561:         Map nameMap = (Map) definition.get(modelClass);
1562:         if (nameMap != null) {
1563:             int[] types = (int[]) nameMap.get(name);
1564:             if (types != null) {
1565: 
1566:                 EventKey[] keys = new EventKey[types.length];
1567:                 for (int i = 0; i < types.length; i++) {
1568:                     keys[i] = new EventKey(types[i], name);
1569:                 }
1570:                 return keys;
1571:             }
1572:         }
1573:         return new EventKey[0];
1574:     }
1575: 
1576:     private synchronized Document loadDocument() {
1577:         DocumentBuilderFactory factory = DocumentBuilderFactory.newInstance();
1578:         try {
1579:             DocumentBuilder builder = factory.newDocumentBuilder();
1580:             Document eventNamesDoc =
1581:                 builder.parse(
1582:                     getClass().getClassLoader().getResourceAsStream(FILE_NAME));
1583:             return eventNamesDoc;
1584:         } catch (ParserConfigurationException e) {
1585:             LOG.fatal(e);
1586:             System.exit(-1);
1587:         } catch (SAXException e) {
1588:             LOG.fatal(e);
1589:             System.exit(-1);
1590:         } catch (IOException e) {
1591:             LOG.fatal(e);
1592:             System.exit(-1);
1593:         }
1594:         return null;
1595:     }
1596: 
1597:     private Class formatClass(Class inputClass) {
1598:         String name = inputClass.getName();
1599:         if (name.endsWith("Impl")) {
1600:             return inputClass;
1601:         } else {
1602:             try {
1603:                 Class returnClass = Class.forName(name + "Impl");
1604:                 return returnClass;
1605:             } catch (ClassNotFoundException ignorable) {
1606:                 // cannot happen
1607:             }
1608:         }
1609:         return null;
1610:     }
1611: }
