805:     /**
806:      * Returns true if a given associationend is a composite.
807:      * @param handle
808:      * @return boolean
809:      */
810:     public static boolean isComposite(Object handle) {
811:         if (isAAssociationEnd(handle)) {
812:             boolean composite = false;
813:             MAssociationEnd end = (MAssociationEnd) handle;
814:             if (end.getAggregation() != null
815:                 && end.getAggregation().equals(MAggregationKind.COMPOSITE))
816:                 composite = true;
817:             return composite;
818:         }
819:         throw new IllegalArgumentException("Unrecognized object " + handle);
820:     }
