823:      *
824:      * @param handle candidate
825:      * @param true if the attribute is initialized.
826:      */
827:     public static boolean isInitialized(Object handle) {
828:         if (handle instanceof MAttribute) {
829:             MExpression init = ((MAttribute) handle).getInitialValue();
830: 
831:             if (init != null
832:                 && init.getBody() != null
833:                 && init.getBody().trim().length() > 0)
834:                 return true;
835:             return false;
836:         }
837: 
838:         // ...
839:         throw new IllegalArgumentException("Unrecognized object " + handle);
840:     }
