1822:     /**
1823:      * Returns all associated classes for some given classifier. Returns an
1824:      * empty collection if the given argument o is not a classifier. The given
1825:      * parameter is included in the returned collection if it has a self-
1826:      * referencing association.
1827:      * @param o
1828:      * @return Collection
1829:      */
1830:     public static Collection getAssociatedClasses(Object o) {
1831:         Collection col = new ArrayList();
1832:         if (o instanceof MClassifier) {
1833:             MClassifier classifier = (MClassifier) o;
1834:             Collection ends = classifier.getAssociationEnds();
1835:             Iterator it = ends.iterator();
1836:             Set associations = new HashSet();
1837:             while (it.hasNext()) {
1838:                 associations.add(((MAssociationEnd) it.next()).getAssociation());
1839:             }
1840:             Collection otherEnds = new ArrayList();
1841:             it = associations.iterator();
1842:             while (it.hasNext()) {
1843:                 otherEnds.addAll(((MAssociation) it.next()).getConnections());
1844:             }
1845:             otherEnds.removeAll(ends);
1846:             it = otherEnds.iterator();
1847:             while (it.hasNext()) {
1848:                 col.add(((MAssociationEnd) it.next()).getType());
1849:             }
1850:         }
1851:         return col;
1852:     }
