35: 
36: import org.apache.log4j.Logger;
37: import org.argouml.model.UmlException;
38: 
39: 
40: /**
41:  * A BufferInputStream that is aware of XML structure.
42:  * It can searches for the first occurence of a named tag
43:  * and reads only the data (inclusively) from that tag
44:  * to the matching end tag or it can search for the first
45:  * occurence of a named tag and read on the child tags.
46:  * The tag is not expected to be an empty tag.
47:  * @author Bob Tarling
48:  */
49: public class XmiInputStream extends BufferedInputStream {
50: 
51:     private String tagName;
52:     private String endTagName;
53:     private String attributes;
54:     private boolean extensionFound;
55:     private boolean endFound;
56:     private boolean parsingExtension;
57:     private boolean readingName;
58:     private EventListenerList listenerList = new EventListenerList();
59:     
60:     private XmiExtensionParser xmlExtensionParser;
61:     
62:     private StringBuffer stringBuffer;
63:     private String type;
64:     
65:     /**
66:      * The number of bytes to be read between each progress
67:      * event.
68:      */
69:     private long eventSpacing;
70: 
71:     /**
72:      * The number of characters read so far.
73:      */
74:     private long readCount;
75: 
76:     /**
77:      * The expected stream length.
78:      */
79:     private long length;
80: 
81:     /**
82:      * Logger.
83:      */
84:     private static final Logger LOG =
85:         Logger.getLogger(XmiInputStream.class);
86: 
87:     /**
88:      * Construct a new XmlInputStream.
89:      *
90:      * @param in the input stream to wrap.
91:      * @param theTag the tag name from which to start reading
92:      * @param theLength the expected length of the input stream
93:      * @param theEventSpacing the number of characers to read before
94:      *        firing a progress event.
95:      */
96:     public XmiInputStream(
97:             InputStream in,
98:             XmiExtensionParser xmlExtensionParser,
99:             long theLength,
100:             long theEventSpacing) {
101:         super(in);
102:         this.length = theLength;
103:         this.eventSpacing = theEventSpacing;
104:         this.xmlExtensionParser  = xmlExtensionParser;
105:         LOG.info("Constructed XmiInputStream");
106:     }
107:     
108:     
109:     
110:     /**
111:      * @see java.io.InputStream#read()
112:      */
113:     public synchronized int read() throws IOException {
114: 
115:         if (endFound) {
116:             extensionFound = false;
117:             parsingExtension = false;
118:             endFound = false;
119:             readingName = false;
120:             tagName = null;
121:             endTagName = null;
122:         }
123: 
124:         int ch = super.read();
125:         
126:         if (parsingExtension) {
127:             stringBuffer.append((char) ch);
128:         }
129:         
130:         if (xmlExtensionParser != null) {
131:             if (readingName) {
132:                 if (isNameTerminator((char) ch)) {
133:                     readingName = false;
134:                     if (parsingExtension && endTagName == null) {
135:                         endTagName = "/" + tagName;
136:                     } else if (tagName.equals("XMI.extension")) {
137:                         extensionFound = true;
138:                     } else if (tagName.equals(endTagName)) {
139:                         endFound = true;
140:                         xmlExtensionParser.parse(type, stringBuffer.toString());
141:                         stringBuffer.delete(0, stringBuffer.length());
142:                     }
143:                 } else {
144:                     tagName += (char) ch;
145:                 }
146:             }
147: 
148:             if (extensionFound) {
149:                 if (ch == '>') {
150:                     extensionFound = false;
151:                     callExtensionParser();
152:                 } else {
153:                     attributes += (char) ch;
154:                 }
155:             }
156:             
157:             if (ch == '<') {
158:                 readingName = true;
159:                 tagName = "";
160:             }
161:         }
162:         return ch;
163:     }
164:     
165:     private void callExtensionParser() throws IOException {
166:         String label = null;
167:         String extender = null;
168:         for (StringTokenizer st = new StringTokenizer(attributes, " =");
169:                 st.hasMoreTokens(); ) {
170:             String attributeType = st.nextToken();
171:             if (attributeType.equals("xmi.extender")) {
172:                 extender = st.nextToken();
173:                 extender = extender.substring(1, extender.length() - 1);
174:             }
175:             if (attributeType.equals("xmi.label")) {
176:                 label = st.nextToken();
177:                 label = label.substring(1, label.length() - 1);
178:             }
179:         }
180:         if ("ArgoUML".equals(extender)) {
181:             type = label;
182:             stringBuffer = new StringBuffer();
183:             parsingExtension = true;
184:             endTagName = null;
185:         }
186:     }
187:     
188:     /**
189:      * @see java.io.InputStream#read(byte[], int, int)
190:      */
191:     public synchronized int read(byte[] b, int off, int len)
192:         throws IOException {
193: 
194:         int count;
195:         for (count = 0; count < len; ++count) {
196:             int read = read();
197:             if (read == -1) {
198:                 break;
199:             }
200:             b[count + off] = (byte) read;
201:         }
202: 
203:         if (count > 0) {
204:             return count;
205:         }
206:         return -1;
207:     }
208: 
209: 
210:     private boolean isNameTerminator(char ch) {
211:         return (ch == '>' || Character.isWhitespace(ch));
212:     }
213: 
214:     /**
215:      * The close method is overridden to prevent some class out of
216:      * our control from closing the stream (such as a SAX parser).
217:      * Use realClose() to finally close the stream for real.
218:      * @throws IOException to satisfy ancestor but will never happen.
219:      */
220:     public void close() throws IOException {
221:     }
222: 
223:     /**
224:      * Really close the input.
225:      *
226:      * @throws IOException if an I/O error occurs.
227:      */
228:     public void realClose() throws IOException {
229:         super.close();
230:     }
231: }
