341:     /**
342:      * This diagram listens to events from is namespace ModelElement;
343:      * When the modelelement is removed, we also want to delete this
344:      * diagram too.  <p>
345:      *
346:      * There is also a risk that if this diagram was the one shown in
347:      * the diagram panel, then it will remain after it has been
348:      * deleted. so we need to deselect this diagram.
349:      *
350:      * @see ru.novosoft.uml.MElementListener#removed(ru.novosoft.uml.MElementEvent)
351:      */
352:     public void removed(MElementEvent e) {
353:         Object newTarget =
354:             ProjectManager.getManager().getCurrentProject().getDiagrams().get(
355:                 0);
356:         TargetManager.getInstance().setTarget(newTarget);
357:         UmlModelEventPump.getPump().removeModelEventListener(
358:             this,
359:             namespace,
360:             UmlModelEventPump.REMOVE);
361:         ProjectManager.getManager().getCurrentProject().moveToTrash(this);
362: 
363:     }
