446:     /**
447:      * Set all toolbar buttons to unselected other then the toolbar button
448:      * with the supplied action.
449:      *
450:      * @param otherThanAction the action of the button 
451:      *                        that is NOT to be deselected
452:      */
453:     public void deselectOtherTools(Action otherThanAction) {
454:         //cat.debug("Looking for action " + otherThanAction);
455:         int toolCount = toolBar.getComponentCount();
456:         for (int i = 0; i < toolCount; ++i) {
457:             Component c = toolBar.getComponent(i);
458:             if (c instanceof ToolButton) {
459:                 ToolButton tb = (ToolButton) c;
460:                 Action action = tb.getRealAction();
461:                 if (action instanceof RadioAction) {
462:                     action = ((RadioAction) action).getAction();
463:                 }
464:                 Action otherAction = otherThanAction;
465:                 if (otherThanAction instanceof RadioAction) {
466:                     otherAction = ((RadioAction) otherThanAction).getAction();
467:                 }
468:                 if (!action.equals(otherAction)) {
469:                     //cat.debug("Unselecting " + tb);
470:                     tb.setSelected(false);
471:                     ButtonModel bm = tb.getModel();
472:                     bm.setRollover(false);
473:                     bm.setSelected(false);
474:                     bm.setArmed(false);
475:                     bm.setPressed(false);
476:                     tb.setBorderPainted(false);
477:                 } else {
478:                     //cat.debug("Selecting " + tb);
479:                     tb.setSelected(true);
480:                     ButtonModel bm = tb.getModel();
481:                     bm.setRollover(true);
482:                     tb.setBorderPainted(true);
483:                 }
484:             }
485:         }
486:     }
