445:   public ActionSaveAsXMI() {
446:     super("Save As XMI");
447:     Hashtable templates = TemplateReader.readFile("/uci/dtd/XMI.tee");
448:     expander = new OCLExpander(templates);
449:   }
450:   public boolean shouldBeEnabled() {
451:     Project p = ProjectBrowser.TheInstance.getProject();
452:     return super.shouldBeEnabled() && p != null;
453:   }
454:   public void actionPerformed(ActionEvent e) {
455:     trySave();
456:   }
457: 
458:   public boolean trySave() {
459:     //@@@: just for rapid edig-compile-debug 
460:     Hashtable templates = TemplateReader.readFile("/uci/dtd/XMI.tee");
461:     expander = new OCLExpander(templates);
462: 
463:     ProjectBrowser pb = ProjectBrowser.TheInstance;
464:     Project p =  pb.getProject();
465:     try {
466:       JFileChooser chooser;
467:       if (p != null && p.getPathname() != null && p.getPathname().length()>0) {
468: 	chooser  = new JFileChooser(p.getPathname());
469:       }
470:       else chooser = new JFileChooser();
471: 
472:       chooser.setDialogTitle("Save " + p.getName());
473:       FileFilter filter = FileFilters.XMIFilter;
474:       chooser.addChoosableFileFilter(filter);
475:       chooser.setFileFilter(filter);
476:       Hashtable stats = p.getStats();
477: 
478:       int retval = chooser.showSaveDialog(pb);
479:       if(retval == 0) {
480: 	File theFile = chooser.getSelectedFile();
481: 	if (theFile != null) {
482: 	  String pathname = chooser.getSelectedFile().getAbsolutePath();
483: 	  pb.showStatus("Writing " + pathname + "...");
484: 	  p.setPathname(chooser.getSelectedFile().getParent());
485: 	  String name = chooser.getSelectedFile().getName();
486: 	  if (!name.endsWith(".xmi")) name += ".xmi";
487: 	  if (!pathname.endsWith(".xmi")) pathname += ".xmi";
488: 	  p.setName(name);
489: 	  FileWriter fw = new FileWriter(pathname);
490: 	  p.preSave();
491: 	  expander.expand(fw, p, "", "");
492: 	  p.postSave();
493: 	  fw.close();
494: 	  pb.showStatus("Wrote " + pathname);
495: 	  pb.updateTitle();
496: 	  return true;
497: 	}
498:       }
499:     }
500:     catch (FileNotFoundException ignore) {
501:       System.out.println("got an FileNotFoundException");
502:     }
503:     catch (PropertyVetoException ignore) {
504:       System.out.println("got an PropertyVetoException in SaveAs");
505:     }
506: //     catch (PropertyVetoException ignore) {
507: //       System.out.println("got an PropertyVetoException");
508: //     }
509:     //    catch (java.lang.ClassMismatchException ignore) {
510:     //      System.out.println("got an ClassMismatchException");
511:     //    }
512:     catch (IOException ignore) {
513:       System.out.println("got an IOException");
514:       ignore.printStackTrace();
515:     }
516:     return false;
517:   }
518: } /* end class ActionSaveAsXMI */
