1235: 
1236:   public void actionPerformed(ActionEvent ae) {
1237:     ProjectBrowser pb = ProjectBrowser.TheInstance;
1238:     Object target = pb.getDetailsTarget();
1239:     Object d = pb.getTarget();
1240:     if (!(d instanceof UMLCollaborationDiagram)) return;
1241:     if (!(target instanceof AssociationRole)) return;
1242:     AssociationRole ar = (AssociationRole) target;
1243:     try {
1244:       Editor _curEditor = Globals.curEditor();
1245:       GraphModel gm = _curEditor.getGraphModel();
1246:       GraphNodeRenderer renderer = _curEditor.getGraphNodeRenderer();
1247:       Layer lay = _curEditor.getLayerManager().getActiveLayer();
1248:       SelectionManager _sm = _curEditor.getSelectionManager();
1249:       Vector figs = _sm.selections();
1250:       Selection _cf = (Selection) figs.firstElement();
1251:       FigEdge _curFig = (FigEdge) _cf.getContent();
1252:       Point _center = _curFig.center();
1253: 
1254:       Message msg = new Message();
1255:       Vector ascEnds = ar.getAssociationEndRole();
1256: 
1257:       AssociationEndRole aer1 = (AssociationEndRole) ascEnds.firstElement();
1258:       AssociationEndRole aer2 = (AssociationEndRole) ascEnds.lastElement();
1259:       ClassifierRole crSrc = (ClassifierRole) aer1.getType();
1260:       ClassifierRole crDst = (ClassifierRole) aer2.getType();
1261:       msg.setSender(crSrc);
1262:       msg.setReceiver(crDst);
1263:       UninterpretedAction ua = new UninterpretedAction();
1264:       msg.setAction(ua);
1265:       ar.addMessage(msg);
1266: 
1267:       FigNode _pers = renderer.getFigNodeFor(gm, lay, msg);
1268:       Vector messages = ar.getMessages();
1269:       int size = messages.size();
1270:       int offsetY = _pers.getHeight()/2;
1271:       _pers.setLocation(_center.x, _center.y - (offsetY * size));
1272:       _curFig.addPathItem(_pers, new PathConvPercent(_curFig, 50, 10));
1273:       lay.add(_pers);
1274:       super.actionPerformed(ae);
1275:       //System.out.println("sender = " + msg.getSender().getName());
1276:       //System.out.println("receiver = " + msg.getReceiver().getName());
1277:     }
1278:     catch (PropertyVetoException pve) {
1279:       System.out.println("PropertyVetoException in ActionMessage");
1280:     }
1281:   }
