1367:     Vector classes = new Vector();
1368:     Vector nodes = d.getGraphModel().getNodes();
1369:     java.util.Enumeration enum = nodes.elements();
1370:     while (enum.hasMoreElements()) {
1371:       Object owner = enum.nextElement();
1372:       if (!(owner instanceof MMClass) && !(owner instanceof Interface))
1373: 	continue;
1374:       Classifier cls = (Classifier) owner;
1375:       String name = cls.getName().getBody();
1376:       if (name == null || name.length() == 0) continue;
1377:       classes.addElement(cls);
1378:     }
1379:     ClassGenerationDialog cgd = new ClassGenerationDialog(classes);
1380:     cgd.show();
1381:   }
