31: // Original Author: jrobbins@ics.uci.edu
32: // $Id$
33: 
34: package uci.gef;
35: 
36: import java.util.*;
37: import java.awt.*;
38: 
39: /** This class implements a group of Figs. */
40: 
41: public class FigGroup extends Fig {
42: 
43:   ////////////////////////////////////////////////////////////////
44:   // instance variables
45: 
46:   /** The Fig's contained in this FigGroup */
47:   //? use array for speed?
48:   protected Vector _figs;
49: 
50:   ////////////////////////////////////////////////////////////////
51:   // constructors
52: 
53:   /** Construct a new FigGroup that holds no Figs. */
54:   public FigGroup() {
55:     super();
56:     _figs = new Vector();
57:   }
58: 
59:   /** Construct a new FigGroup that holds the given Figs. */
60:   public FigGroup(Vector figs) {
61:     super();
62:     _figs = figs;
63:     calcBounds();
64:   }
65: 
66:   ////////////////////////////////////////////////////////////////
67:   // accessors
68: 
69:   /** Reply an Enumeration of the Figs contained in this FigGroup. */
70:   public Enumeration elements() { return _figs.elements(); }
71: 
72:   /** Add a Fig to the group.  New Figs are added on the top. */
73:   public void addFig(Fig p) { _figs.addElement(p); calcBounds(); }
74: 
75:   /** Reply the Vector of Figs. */
76:   public Vector getFigs() { return _figs; }
77: 
78:   /** Set the Vector of Figs in this group. Fires PropertyChange with "bounds". */
79:   public void setFigs(Vector figs) {
80:     Rectangle oldBounds = getBounds();
81:     _figs = figs;
82:     calcBounds();
83:     firePropChange("bounds", oldBounds, getBounds());
84:   }
85: 
86: 
87:   /** Delete a Fig from the group. Fires PropertyChange with "bounds". */
88:   public void deleteFig(Fig p) {
89:     Rectangle oldBounds = getBounds();
90:     _figs.removeElement(p);
91:     calcBounds();
92:     firePropChange("bounds", oldBounds, getBounds());
93:   }
94: 
95:   /** Delete all Fig's from the group. Fires PropertyChange with "bounds".*/
96:   public void removeAll() {
97:     Rectangle oldBounds = getBounds();
98:     _figs.removeAllElements();
99:     calcBounds();
100:     firePropChange("bounds", oldBounds, getBounds());
101:   }
102: 
103: 
104:   /** Groups are resizable, but not reshapable, and not rotatable (for now). */
105:   public boolean isResizable() { return true; }
106:   public boolean isReshapable() { return false; }
107:   public boolean isRotatable() { return false; }
108: 
109: 
110:   ////////////////////////////////////////////////////////////////
111:   // Fig API
112: 
113:   /** Retrieve the top-most Fig containing the given point, or null.
114:    *  Needs-More-Work: just do a linear search.  Later, optimize this
115:    *  routine using Quad Trees (or other) techniques. */
116: 
117:   public Fig hitFig(Rectangle r) {
118:     Enumeration figs = elements();
119:     Fig res = null;
120:     while (figs.hasMoreElements()) {
121:       Fig f = (Fig) figs.nextElement();
122:       if (f.hit(r)) res = f;
123:     }
124:     return res;
125:   }
126: 
127:   /** Returns true if any Fig in the group contains the given point. */
128:   public boolean contains(int x, int y) {
129:     return hitFig(new Rectangle(x, y, 0, 0)) != null;
130:   }
131: 
132:   /** Returns true if any Fig in the group hits the given rect. */
133:   public boolean hit(Rectangle r) { return hitFig(r) != null; }
134: 
135:   /** Translate all the Fig in the list by the given offset. */
136:   public void translate(int dx, int dy) {
137:     Rectangle oldBounds = getBounds();
138:     Enumeration figs = _figs.elements();
139:     while (figs.hasMoreElements()) {
140:       Fig f = (Fig) figs.nextElement();
141:       f.translate(dx, dy);
142:     }
143:     _x += dx; _y += dy; // no need to call calcBounds();
144:     firePropChange("bounds", oldBounds, getBounds());
145:   }
146: 
147:   /** Set the bounding box to the given rect. Figs in the group are
148:    *  scaled to fit. Fires PropertyChange with "bounds" */
149:   public void setBounds(int x, int y, int w, int h) {
150:     Rectangle oldBounds = getBounds();
151:     Enumeration figs = _figs.elements();
152:     while (figs.hasMoreElements()) {
153:       Fig f = (Fig) figs.nextElement();
154:       int newX = (_w == 0) ? x : x + ((f.getX() - _x) * w) / _w;
155:       int newY = (_h == 0) ? y : y + ((f.getY() - _y) * h) / _h;
156:       int newW = (_w == 0) ? 0 : (f.getWidth() * w) / _w;
157:       int newH = (_h == 0) ? 0 : (f.getHeight() * h) / _h;
158:       f.setBounds(newX, newY, newW, newH);
159:     }
160:     calcBounds(); //_x = x; _y = y; _w = w; _h = h;
161:     firePropChange("bounds", oldBounds, getBounds());
162:   }
163: 
164:   ////////////////////////////////////////////////////////////////
165:   // display methods
166: 
167:   /** Paint all the Figs in this group. */
168:   public void paint(Graphics g) {
169:     Enumeration figs = elements();
170:     while (figs.hasMoreElements()) {
171:       Fig f = (Fig) figs.nextElement();
172:       f.paint(g);
173:     }
174:   }
175: 
176:   /** Accumulate a bounding box for all the Figs in the group. */
177:   public void calcBounds() {
178:     Rectangle bbox; // could be blank final
179:     Enumeration figs = _figs.elements();
180:     if (figs.hasMoreElements()) bbox = ((Fig)figs.nextElement()).getBounds();
181:     else bbox = new Rectangle(0, 0, 0, 0);
182:     while (figs.hasMoreElements()) {
183:       Fig f = (Fig) figs.nextElement();
184:       bbox.add(f.getBounds());
185:     }
186:     _x = bbox.x;
187:     _y = bbox.y;
188:     _w = bbox.width;
189:     _h = bbox.height;
190:   }
191: 
192: } /* end class FigGroup */
