323:     /**
324:      * Transform a string of XML data according to the service required.
325:      *
326:      * @param url The URL of the XML to be transformed
327:      * @param version the version of the persistence format
328:      *                the XML is to be transformed to.
329:      * @return the URL of the transformed XML
330:      * @throws OpenException on XSLT transformation error or file read
331:      */
332:     public final URL transform(URL url, int version)
333:         throws OpenException {
334: 
335:         try {
336:             String upgradeFilesPath = "/org/argouml/persistence/upgrades/";
337:             String upgradeFile = "upgrade" + version + ".xsl";
338: 
339:             // TODO: But should instead access a resource inside the jar
340:             String xsltFileName = upgradeFilesPath + upgradeFile;
341:             URL xsltUrl = UmlFilePersister.class.getResource(xsltFileName);
342:             LOG.info("Resource is " + xsltUrl);
343: 
344:             // Read xsltStream into a temporary file
345:             // Get url for temp file.
346:             // openStream from url and wrap in StreamSource
347:             StreamSource xsltStreamSource =
348:                 new StreamSource(xsltUrl.openStream());
349: 
350:             TransformerFactory factory = TransformerFactory.newInstance();
351:             Transformer transformer = factory.newTransformer(xsltStreamSource);
352: 
353:             File file = File.createTempFile("upgrade_" + version + "_", ".uml");
354:             file.deleteOnExit();
355: 
356:             String encoding = "UTF-8";
357:             FileOutputStream stream =
358:                 new FileOutputStream(file);
359:             Writer writer = new BufferedWriter(new OutputStreamWriter(
360:                     stream, encoding));
361:             Result result = new StreamResult(writer);
362: 
363:             StreamSource inputStreamSource = new StreamSource(url.openStream());
364:             transformer.transform(inputStreamSource, result);
365: 
366:             writer.close();
367:             return file.toURL();
368:         } catch (IOException e) {
369:             throw new OpenException(e);
370:         } catch (TransformerException e) {
371:             throw new OpenException(e);
372:         }
373:     }
