375:     /**
376:      * Read an XML file at the given URL and extracts the version number
377:      * from the root tag.
378:      * @param url the URL of the XML file
379:      * @return The version number
380:      * @throws IOException
381:      */
382:     private String getVersion(URL url) throws IOException {
383:         BufferedInputStream inputStream =
384:             new BufferedInputStream(url.openStream());
385:         BufferedReader reader =
386:             new BufferedReader(new InputStreamReader(inputStream));
387:         String rootLine = reader.readLine();
388:         while (!rootLine.startsWith("<uml ")) {
389:             rootLine = reader.readLine();
390:         }
391:         inputStream.close();
392:         reader.close();
393:         return getVersion(rootLine);
394:     }
395: 
396:     /**
397:      * Get the version attribute value from a string of XML.
398:      * @param rootLine the line
399:      * @return the version
400:      */
401:     protected String getVersion(String rootLine) {
402:         String version;
403:         int versionPos = rootLine.indexOf("version=\"");
404:         if (versionPos > 0) {
405:             int startPos = versionPos + 9;
406:             int endPos = rootLine.indexOf("\"", startPos);
407:             version = rootLine.substring(startPos, endPos);
408:         } else {
409:             version = "1";
410:         }
411:         return version;
412:     }
