244:                         persister = new TodoListMemberFilePersister();
245:                     } else if (projectMember instanceof ProjectMemberModel) {
246:                         persister = new ModelMemberFilePersister();
247:                     }
248:                     persister.save(projectMember, writer, indent);
249:                 }
250:             }
251: 
