307:     private URL upgrade(URL projectFile) throws OpenException {
308:         try {
309:             int versionFromFile = Integer.parseInt(getVersion(projectFile));
310: 
311:             LOG.info("Loading uml file of version " + versionFromFile);
312:             while (versionFromFile < PERSISTENCE_VERSION) {
313:                 ++versionFromFile;
314:                 LOG.info("Upgrading to version " + versionFromFile);
315:                 projectFile = transform(projectFile, versionFromFile);
316:             }
317:             return projectFile;
318:         } catch (IOException e) {
319:             throw new OpenException(e);
320:         }
321:     }
