433:   ////////////////////////////////////////////////////////////////
434:   // image loading
435:   
436:     protected static ImageIcon loadIconResource(String name) {
437:     String imgName = imageName(name);
438:     ImageIcon res = null;
439:     try {
440:       java.net.URL imgURL = Critic.class.getResource(imgName);
441:       return new ImageIcon(imgURL);
442:     }
443:     catch (Exception ex) {
444:       return new ImageIcon(name);
445:     }
446:   }
447: 
448:   protected static String imageName(String name) {
449:     return "/uci/Images/" + stripJunk(name) + ".gif";
450:   }
451: 
452:   protected static String stripJunk(String s) {
453:     String res = "";
454:     int len = s.length();
455:     for (int i = 0; i < len; i++) {
456:       char c = s.charAt(i);
457:       if (Character.isJavaLetterOrDigit(c)) res += c;
458:     }
459:     return res;
460:   }
