117:     public String GenerateFile(Object o, String path) {
118: 	MClassifier cls = (MClassifier) o;
119: 	sect = new Section();
120: 
121: 	String name = cls.getName();
122: 	if (name == null || name.length() == 0) return null;
123: 	String filename = name + ".cs";
124: 	if (!path.endsWith(FILE_SEPARATOR)) path += FILE_SEPARATOR;
125: 
126: 	String packagePath = cls.getNamespace().getName();
127: 	MNamespace parent = cls.getNamespace().getNamespace();
128: 	while (parent != null) {
129: 	    // ommit root package name; it's the model's root
130: 	    if (parent.getNamespace() != null)
131: 		packagePath = parent.getName() + "." + packagePath;
132: 	    parent = parent.getNamespace();
133: 	}
134: 
135: 	int lastIndex = -1;
136: 	do {
137: 	    File f = new File(path);
138: 	    if (!f.isDirectory()) {
139: 		if (!f.mkdir()) {
140: 		    System.out.println(" could not make directory " + path);
141: 		    return null;
142: 		}
143: 	    }
144: 	    if (lastIndex == packagePath.length())
145: 		break;
146: 	    int index = packagePath.indexOf(".", lastIndex + 1);
147: 	    if (index == -1)
148: 		index = packagePath.length();
149: 	    path += packagePath.substring(lastIndex + 1, index) + FILE_SEPARATOR;
150: 	    lastIndex = index;
151: 	} while (true);
152: 	String pathname = path + filename;
153: 	System.out.println("-----" + pathname + "-----");
154: 
155: 	//String pathname = path + filename;
156: 	// TODO: package, project basepath, tagged values to configure
157: 	File f = new File(pathname);
158: 	if (f.exists()) {
159: 	    System.out.println("Generating (updated) " + f.getPath());
160: 	    sect.read(pathname);
161: 	} else {
162: 	    System.out.println("Generating (new) " + f.getPath());
163: 	}
164: 	String header = SINGLETON.generateHeader(cls, pathname, packagePath);
165: 	String src = SINGLETON.generate(cls);
166: 	if (packagePath.length() > 0) src += "\n}";
167: 	BufferedWriter fos = null;
168: 	try {
169: 	    fos = new BufferedWriter(new FileWriter(f));
170: 	    fos.write(header);
171: 	    fos.write(src);
172: 	}
173: 	catch (IOException exp) { }
174: 	finally {
175: 	    try {
176: 		if (fos != null) fos.close();
177: 	    }
178: 	    catch (IOException exp) {
179: 		System.out.println("FAILED: " + f.getPath());
180: 	    }
181: 	}
182: 
183: 	sect.write(pathname, INDENT);
184: 	System.out.println("written: " + pathname);
185: 
186: 
187: 	File f1 = new File(pathname + ".bak");
188: 	if (f1.exists()) {
189: 	    f1.delete();
190: 	}
191: 
192: 	File f2 = new File(pathname);
193: 	if (f2.exists()) {
194: 	    f2.renameTo(new File(pathname + ".bak"));
195: 	}
196: 
197: 	File f3 = new File(pathname + ".out");
198: 	if (f3.exists()) {
199: 	    f3.renameTo(new File(pathname));
200: 	}
201: 
202: 	System.out.println("----- end updating -----");
203: 	return pathname;
204:     }
