396: 	String slash = "";
397: 	//    if (attr.containsStereotype(MStereotype.DERIVED)) slash = "/";
398: 	String attr_name = attr.getName();
399: 	MVisibilityKind vis = attr.getVisibility();
400: 
401: 	if (MVisibilityKind.PUBLIC.equals(vis)) {
402: 	    // use original attribute name, no change
403: 	}
404: 	if (MVisibilityKind.PRIVATE.equals(vis)) {
405: 	    attr_name = attr.getOwner().getName() + "_" + attr_name;
406: 
407: 	}
408: 	if (MVisibilityKind.PROTECTED.equals(vis)) {
