481: 	    Iterator ownedEnum = ownedElements.iterator();
482: 	    while (ownedEnum.hasNext()) {
483: 		MModelElement me = (MModelElement) ownedEnum.next();
484: 		s += generate(me);
485: 		s += "\n\n";
486: 	    }
487: 	}
488: 	else {
489: 	    s += "(no elements)";
490: 	}
491: 	s += "\n}\n";
492: 	return s;
493:     }
