733:     /**
734:      * Enhance/Create the doccomment for the given model element, including tags
735:      * for any OCL constraints connected to the model element. The tags generated
736:      * are suitable for use with the ocl injector which is part of the Dresden OCL
737:      * Toolkit and are in detail:
738:      *
739:      * &nbsp;@invariant for each invariant specified
740:      * &nbsp;@precondition for each precondition specified
741:      * &nbsp;@postcondition for each postcondition specified
742:      * &nbsp;@key-type specifying the class of the keys of a mapped association
743:      * &nbsp; Currently mapped associations are not supported yet...
744:      * &nbsp;@element-type specifying the class referenced in an association
745:      *
746:      * @since 2001-09-26 ArgoUML 0.9.3
747:      * @author Steffen Zschaler
748:      *
749:      * @param me the model element for which the documentation comment is needed
750:      * @param ae the association end which is represented by the model element
751:      * @return the documentation comment for the specified model element, either
752:      * enhanced or completely generated
753:      */
754:     public String generateConstraintEnrichedDocComment (MModelElement me,
755: 							MAssociationEnd ae) {
756: 	String sDocComment = generateConstraintEnrichedDocComment (me);
757: 
758: 	MMultiplicity m = ae.getMultiplicity();
759: 	if (!(MMultiplicity.M1_1.equals(m) || MMultiplicity.M0_1.equals (m))) {
760: 	    // Multiplicity greater 1, that means we will generate some sort of
761: 	    // collection, so we need to specify the element type tag
762: 
763: 	    // Prepare doccomment
764: 	    if (sDocComment != null) {
765: 		// Just remove closing */
766: 		sDocComment = sDocComment.substring (0, sDocComment.indexOf ("*/") + 1);
767: 	    }
768: 	    else {
769: 		if (VERBOSE) {
770: 		    sDocComment = INDENT + "/**\n" +
771: 			INDENT + " * \n" +
772: 			INDENT + " *";
773: 		} else {
774: 		    sDocComment = "";
775: 		}
776: 	    }
777: 
778: 	    // Build doccomment
779: 	    sDocComment += " @element-type " + ae.getType().getName();
780: 
781: 	    sDocComment += "\n" +
782: 		INDENT + " */";
783: 
784: 	    return sDocComment;
785: 	}
786: 	else {
787: 	    return ((sDocComment != null) ? (sDocComment) : (""));
788: 	}
789:     }
