731:     /**
732:      * Enhance/Create the doccomment for the given model element, including tags
733:      * for any OCL constraints connected to the model element. The tags generated
734:      * are suitable for use with the ocl injector which is part of the Dresden OCL
735:      * Toolkit and are in detail:
736:      *
737:      * &nbsp;@invariant for each invariant specified
738:      * &nbsp;@precondition for each precondition specified
739:      * &nbsp;@postcondition for each postcondition specified
740:      * &nbsp;@key-type specifying the class of the keys of a mapped association
741:      * &nbsp; Currently mapped associations are not supported yet...
742:      * &nbsp;@element-type specifying the class referenced in an association
743:      *
744:      * @since 2001-09-26 ArgoUML 0.9.3
745:      * @author Steffen Zschaler
746:      *
747:      * @param me the model element for which the documentation comment is needed
748:      * @param ae the association end which is represented by the model element
749:      * @return the documentation comment for the specified model element, either
750:      * enhanced or completely generated
751:      */
752:     public String generateConstraintEnrichedDocComment (MModelElement me,
753: 							MAssociationEnd ae) {
754: 	String sDocComment = generateConstraintEnrichedDocComment (me);
755: 
756: 	MMultiplicity m = ae.getMultiplicity();
757: 	if (!(MMultiplicity.M1_1.equals(m) || MMultiplicity.M0_1.equals (m))) {
758: 	    // Multiplicity greater 1, that means we will generate some sort of
759: 	    // collection, so we need to specify the element type tag
760: 
761: 	    // Prepare doccomment
762: 	    if (sDocComment != null) {
763: 		// Just remove closing */
764: 		sDocComment = sDocComment.substring (0, sDocComment.indexOf ("*/") + 1);
765: 	    }
766: 	    else {
767: 		if (VERBOSE) {
768: 		    sDocComment = INDENT + "/**\n" +
769: 			INDENT + " * \n" +
770: 			INDENT + " *";
771: 		} else {
772: 		    sDocComment = "";
773: 		}
774: 	    }
775: 
776: 	    // Build doccomment
777: 	    sDocComment += " @element-type " + ae.getType().getName();
778: 
779: 	    sDocComment += "\n" +
780: 		INDENT + " */";
781: 
782: 	    return sDocComment;
783: 	}
784: 	else {
785: 	    return ((sDocComment != null) ? (sDocComment) : (""));
786: 	}
787:     }
