49: public class UMLStateDiagram extends UMLDiagram {
50:     /**
51:      * Logger.
52:      */
53:     private static final Logger LOG = Logger.getLogger(UMLStateDiagram.class);
54: 
55:     /**
56:      * this diagram needs to be deleted when its statemachine is deleted.
57:      */
58:     private Object theStateMachine;
59: 
