175:     protected void addListenerToNode(Object node) {
176:         if (node instanceof MBase) {
177:             // UmlModelEventPump.getPump().removeModelEventListener(this, ((MBase)node));
178:             UmlModelEventPump.getPump().addModelEventListener(
179:                 this,
180:                 ((MBase) node));
181:         }
182:         TreeModel tm = getModel();
183:         int childCount = tm.getChildCount(node);
184:         for (int i = 0; i < childCount; i++) {
185:             Object child = tm.getChild(node, i);
186:             if (child instanceof MBase) {
187:                 UmlModelEventPump.getPump().removeModelEventListener(
188:                     this,
189:                     ((MBase) child));
190:                 UmlModelEventPump.getPump().addModelEventListener(
191:                     this,
192:                     ((MBase) child));
193: 
194:             }
195:         }
196:     }
