211:         if (r instanceof MBase) {
212:             // UmlModelEventPump.getPump().removeModelEventListener(this, (MBase)r);
213:             UmlModelEventPump.getPump().addModelEventListener(this, (MBase) r);
214:         }
215: 
216:         int childCount = newModel.getChildCount(r);
217:         for (int i = 0; i < childCount; i++) {
218:             Object child = newModel.getChild(r, i);
219:             if (child instanceof MBase) {
220:                 // UmlModelEventPump.getPump().removeModelEventListener(this, (MBase)child);
221:                 UmlModelEventPump.getPump().addModelEventListener(
222:                     this,
223:                     (MBase) child);
224:             }
225:         }
226:         reexpand();
