252:     /**
253:      * This is the real update function. It won't return until the tree
254:      * really is updated.
255:      * <P>
256:      * Never call this one from any code.
257:      *
258:      * @since 0.13.1
259:      */
260:     public void doForceUpdate() {
261:         Object rootArray[] = new Object[1];
262:         rootArray[0] = getModel().getRoot();
263:         Object noChildren[] = null;
264:         int noIndexes[] = null;
265:         TreeModelEvent tme = new TreeModelEvent(this, new TreePath(rootArray));
266:         treeModelListener.treeStructureChanged(tme);
267:         TreeModel tm = getModel();
268:         if (tm instanceof NavPerspective) {
269:             NavPerspective np = (NavPerspective) tm;
270:             np.fireTreeStructureChanged(this, rootArray, noIndexes, noChildren);
271:         }
272:         reexpand();
273:     }
