290:         _reexpanding = true;
291:         Object[] path2 = new Object[1];
292:         path2[0] = getModel().getRoot();
293:         TreeModelEvent tme = new TreeModelEvent(this, path2, null, null);
294:         treeModelListener.treeStructureChanged(tme);
295:         treeDidChange();
