342: /**
343:  * This class is used to defer the actual update until "late"
344:  * in the invokeLater()-call chain.
345:  * <P>
346:  * The real update will hopefully take place at the end of whatever long
347:  * chain of forceUpdate:s that will be performed.
348:  */
349: class DisplayTextTreeRun implements Runnable {
350:     protected Category cat;
351:     private DisplayTextTree _tree;
352:     int _timesToRun = 0;
353:     boolean _queued = false;
354: 
355:     public DisplayTextTreeRun(Category c, DisplayTextTree t) {
356:         cat = c;
357:         _tree = t;
358:     }
359: 
360:     public synchronized void onceMore() {
361:         if (!_queued) {
362:             _queued = true;
363:             SwingUtilities.invokeLater(this);
364:         }
365:         _timesToRun++;
366:     }
367: 
368:     public synchronized void run() {
369:         if (_timesToRun > 100)
370:             cat.debug("" + _timesToRun + " forceUpdates encountered.");
371: 
372:         if (_timesToRun > 0) {
373:             // another forceUpdate was seen, wait again
374:             _queued = true;
375:             SwingUtilities.invokeLater(this);
376:             _timesToRun = 0;
377:         } else if (_queued) {
378:             _queued = false;
379:             SwingUtilities.invokeLater(this);
380:         } else {
381:             _tree.doForceUpdate();
382:         }
383:     }
384: }
