424:     /* Required by LayoutManager. */
425:     public Dimension minimumLayoutSize(Container parent) {
426:         synchronized (parent.getTreeLock()) {
427:             int componentCount = parent.getComponentCount();
428:             int actualRows = rows;
429:             int actualCols = cols;
430: 
431:             if (actualRows > 0) {
432:                 actualCols = (componentCount + actualRows - 1) / actualRows;
433:             } else {
434:                 actualRows = (componentCount + actualCols - 1) / actualCols;
435:             }
436: 
437:             colWidth = new int[actualCols];
438:             rowHeight = new int[actualRows];
439:             int largestMinimumWidth = 0;
440:             int largestMinimumHeight = 0;
441: 
442:             for (int c = 0; c < actualCols; ++c) {
443:                 for (int r = 0; r < actualRows; ++r) {
444:                     int i = r * actualCols + c;
445:                     if (i < componentCount) {
446:                         if (parent.getComponent(i).getMinimumSize().getWidth()
447: 			    > colWidth[c]) 
448: 			{
449:                             colWidth[c] =
450: 				(int) parent.getComponent(i)
451: 				    .getMinimumSize().getWidth();
452:                             if (colWidth[c] > largestMinimumWidth)
453: 				largestMinimumWidth = colWidth[c];
454:                         }
455:                         if (parent.getComponent(i).getMinimumSize().getHeight()
456: 			    > rowHeight[r]) {
457:                             rowHeight[r] =
458: 				(int) parent.getComponent(i)
459: 				    .getMinimumSize().getHeight();
460:                             if (rowHeight[r] > largestMinimumHeight)
461: 				largestMinimumHeight = rowHeight[r];
462:                         }
463:                     }
464:                 }
465:             }
466: 
467:             return calculateSizes(parent, colWidth, rowHeight,
468: 				  actualRows, actualCols,
469: 				  largestMinimumWidth, largestMinimumHeight);
470:         }
471:     }
