473:     public void layoutContainer(Container parent) {
474:         synchronized (parent.getTreeLock()) {
475:             int ncomponents = parent.getComponentCount();
476:             if (ncomponents == 0) {
477:                 return;
478:             }
479:             Insets insets = parent.getInsets();
480:             int nrows = this.rows;
481:             int ncols = this.cols;
482: 
483:             if (nrows > 0) {
484:                 ncols = (ncomponents + nrows - 1) / nrows;
485:             } else {
486:                 nrows = (ncomponents + ncols - 1) / ncols;
487:             }
488: 
489:             colWidth = new int[ncols];
490:             rowHeight = new int[nrows];
491:             largestWidth = 0;
492:             largestHeight = 0;
493: 
494:             if (cellSizing == FITPARENT) {
495:                 int availableWidth =
496: 		    parent.getWidth() 
497: 		    - (insets.left + insets.right + (ncols - 1) * h);
498:                 int availableHeight =
499: 		    parent.getHeight()
500: 		    - (insets.top + insets.bottom + (nrows - 1) * vgap);
501:                 largestWidth = availableWidth / ncols;
502:                 largestHeight = availableHeight / nrows;
503:             }
504:             else {
505:                 for (int c = 0; c < ncols; ++c) {
506:                     for (int r = 0; r < nrows; ++r) {
507:                         int i = r * ncols + c;
508:                         if (i < ncomponents) {
509:                             if (parent.getComponent(i)
510: 				.getPreferredSize().getWidth()
511: 				> colWidth[c])
512: 			    {
513:                                 colWidth[c] =
514: 				    (int) parent.getComponent(i)
515: 				        .getPreferredSize().getWidth();
516:                                 if (colWidth[c] > largestWidth)
517: 				    largestWidth = colWidth[c];
518:                             }
519:                             if (parent.getComponent(i)
520: 				.getPreferredSize().getHeight()
521: 				> rowHeight[r])
522: 			    {
523:                                 rowHeight[r] =
524: 				    (int) parent.getComponent(i)
525: 				        .getPreferredSize().getHeight();
526:                                 if (rowHeight[r] > largestHeight)
527: 				    largestHeight = rowHeight[r];
528:                             }
529:                         }
530:                     }
531:                 }
532:             }
533: 
534:             int cellWidth;
535:             int cellHeight;
536:             for (int c = 0, x = insets.left;
537: 		 c < ncols;
538: 		 x += cellWidth + h, ++c)
539: 	    {
540:                 cellWidth = getComponentCellWidth(c);
541:                 for (int r = 0, y = insets.top;
542: 		     r < nrows;
543: 		     y += cellHeight + vgap, ++r)
544: 		{
545:                     cellHeight = getComponentCellHeight(r);
546: 
547:                     int i = r * ncols + c;
548: 
549:                     if (i < ncomponents) {
550:                         positionComponentInCell(parent.getComponent(i), x, y,
551: 						cellWidth, cellHeight);
552:                     }
553:                 }
554:             }
555:         }
556:     }
557: 
558: 
559:     protected Dimension calculateSizes(Container parent, 
560: 				       int colWidth[], int rowHeight[],
561: 				       int actualRows, int actualCols,
562: 				       int largestWidth, int largestHeight)
563:     {
564:         int w = 0;
565:         int h = 0;
566:         if (cellSizing == GridLayout2.ROWCOLPREFERRED) {
567:             for (int c = 0; c < actualCols; ++c) w += colWidth[c];
568:             for (int r = 0; r < actualRows; ++r) h += rowHeight[r];
569:         }
570:         else {
571:             w = largestWidth * actualCols;
572:             h = largestHeight * actualRows;
573:         }
574: 
575:         Insets insets = parent.getInsets();
576:         return new Dimension(insets.left + insets.right + w 
577: 			     + (actualCols - 1) * this.h,
578:                              insets.top + insets.bottom + h
579: 			     + (actualRows - 1) * vgap);
580:     }
581: 
582:     protected int getComponentCellHeight(int row) {
583:         if (cellSizing == ROWCOLPREFERRED) return rowHeight[row];
584:         return largestHeight;
585:     }
586: 
587:     protected int getComponentCellWidth(int col) {
588:         if (cellSizing == ROWCOLPREFERRED) return colWidth[col];
589:         return largestWidth;
590:     }
591: 
592:     protected void positionComponentInCell(Component comp,
593: 					   int x, int y,
594: 					   int cellWidth, int cellHeight)
595:     {
596:         int componentWidth;
597:         int componentHeight;
598:         if (fill == VERTICAL || fill == NONE) {
599:             componentWidth = (int) comp.getPreferredSize().getWidth();
600:         }
601:         else {
602:             componentWidth = cellWidth;
603:         }
604: 
605:         if (fill == HORIZONTAL || fill == NONE) {
606:             componentHeight = (int) comp.getPreferredSize().getHeight();
607:         }
608:         else {
609:             componentHeight = cellHeight;
610:         }
611: 
612:         int xAnchor, yAnchor;
613:         if (fill == BOTH || fill == HORIZONTAL
614: 	    || anchor == NORTHWEST || anchor == WEST || anchor == SOUTHWEST)
615: 	{
616:             xAnchor = x;
617:         }
618:         else if (anchor == NORTHEAST || anchor == EAST || anchor == SOUTHEAST)
619: 	{
620:             xAnchor = x + cellWidth - componentWidth;
621:         }
622:         else {
623:             xAnchor = x + (cellWidth - componentWidth) / 2;
624:         }
625: 
626:         if (fill == BOTH || fill == VERTICAL
627: 	    || anchor == NORTH || anchor == NORTHWEST || anchor == NORTHEAST)
628: 	{
629:             yAnchor = y;
630:         }
631:         else if (anchor == SOUTHEAST || anchor == SOUTH || anchor == SOUTHWEST)
632: 	{
633:             yAnchor = y + cellHeight - componentHeight;
634:         }
635:         else {
636:             yAnchor = y + (cellHeight - componentHeight) / 2;
637:         }
638: 
639:         comp.setBounds(xAnchor, yAnchor, componentWidth, componentHeight);
640:     }
