28: package org.argouml.swingext;
29: 
30: import java.awt.*;
31: 
32: /**
33:  * Same as the standard java class GridLayout but allows more
34:  * flexability for sizing of columns and rows.
35:  *
36:  * @author Bob Tarling
37:  */
38: public class GridLayout2 implements LayoutManager, java.io.Serializable {
39: 
40:      /**
41:        * Do not resize the child components.
42:        */
43:     public static final int NONE = 0;
44: 
45:      /**
46:        * Resize all child components to fit their cell both
47:        * horizontally and vertically.
48:        */
49:     public static final int BOTH = 1;
50: 
51:      /**
52:        * Resize all child components to fit their cell horizontally
53:        * but not vertically.
54:        */
55:     public static final int HORIZONTAL = 2;
56: 
57:      /**
58:        * Resize all child components to fit their cell vertically but
59:        * not horizontally.
60:        */
61:     public static final int VERTICAL = 3;
62: 
63:      /**
64:       * Put the component in the center of its display area.
65:       */
66:     public static final int CENTER = 10;
