473:     public void layoutContainer(Container parent) {
474:         synchronized (parent.getTreeLock()) {
475:             int ncomponents = parent.getComponentCount();
476:             if (ncomponents == 0) {
477:                 return;
478:             }
479:             Insets insets = parent.getInsets();
480:             int nrows = this.rows;
481:             int ncols = this.cols;
482: 
483:             if (nrows > 0) {
484:                 ncols = (ncomponents + nrows - 1) / nrows;
485:             } else {
486:                 nrows = (ncomponents + ncols - 1) / ncols;
487:             }
488: 
489:             colWidth = new int[ncols];
490:             rowHeight = new int[nrows];
491:             largestWidth = 0;
492:             largestHeight = 0;
493: 
494:             if (cellSizing == FITPARENT) {
495:                 int availableWidth =
496: 		    parent.getWidth() 
497: 		    - (insets.left + insets.right + (ncols - 1) * h);
498:                 int availableHeight =
499: 		    parent.getHeight()
500: 		    - (insets.top + insets.bottom + (nrows - 1) * vgap);
501:                 largestWidth = availableWidth / ncols;
502:                 largestHeight = availableHeight / nrows;
503:             }
504:             else {
505:                 for (int c = 0; c < ncols; ++c) {
506:                     for (int r = 0; r < nrows; ++r) {
507:                         int i = r * ncols + c;
508:                         if (i < ncomponents) {
509:                             if (parent.getComponent(i)
510: 				.getPreferredSize().getWidth()
511: 				> colWidth[c])
512: 			    {
513:                                 colWidth[c] =
514: 				    (int) parent.getComponent(i)
515: 				        .getPreferredSize().getWidth();
516:                                 if (colWidth[c] > largestWidth)
517: 				    largestWidth = colWidth[c];
518:                             }
519:                             if (parent.getComponent(i)
520: 				.getPreferredSize().getHeight()
521: 				> rowHeight[r])
522: 			    {
523:                                 rowHeight[r] =
524: 				    (int) parent.getComponent(i)
525: 				        .getPreferredSize().getHeight();
526:                                 if (rowHeight[r] > largestHeight)
527: 				    largestHeight = rowHeight[r];
528:                             }
529:                         }
530:                     }
531:                 }
532:             }
533: 
534:             int cellWidth;
535:             int cellHeight;
536:             for (int c = 0, x = insets.left;
537: 		 c < ncols;
538: 		 x += cellWidth + h, ++c)
539: 	    {
540:                 cellWidth = getComponentCellWidth(c);
541:                 for (int r = 0, y = insets.top;
542: 		     r < nrows;
543: 		     y += cellHeight + vgap, ++r)
544: 		{
545:                     cellHeight = getComponentCellHeight(r);
546: 
547:                     int i = r * ncols + c;
548: 
549:                     if (i < ncomponents) {
550:                         positionComponentInCell(parent.getComponent(i), x, y,
551: 						cellWidth, cellHeight);
552:                     }
553:                 }
554:             }
555:         }
556:     }
